test('semantic zoom restores ordinary Chat and Browser detail from outline through 35%', () => {
  const project = (width, height, fontPx, zoom, previous = 'outline') => surfaceSemanticLevel({
    width: width * zoom, height: height * zoom, fontPx: fontPx * zoom, previous,
    // The production caller supplies these reference sizes explicitly.
    detailWidth: 240, detailHeight: 180,
  });
  for (const zoom of [.69, .5, .35]) {
    assert.equal(project(320, 420, 13, zoom), 'detail', `minimum Chat at ${zoom}`);
    assert.equal(project(320, 420, 10, zoom), 'detail', `minimum Chat with 10px font at ${zoom}`);
    assert.equal(project(720, 500, 11, zoom), 'detail', `normal Browser at ${zoom}`);
    assert.equal(project(720, 500, 16, zoom), 'detail', `measured Browser at ${zoom}`);
  }
});

test('semantic zoom delays abstraction on zoom-out and keeps a stable detail hysteresis band', () => {
  const projected = (width, height, fontPx, zoom, previous) => surfaceSemanticLevel({
    width: width * zoom, height: height * zoom, fontPx: fontPx * zoom, previous,
    detailWidth: 240, detailHeight: 180,
  });
  assert.equal(projected(320, 420, 13, 1), 'detail');
  assert.equal(projected(320, 420, 13, .5, 'detail'), 'detail');
  assert.equal(projected(320, 420, 13, .3, 'detail'), 'detail');
  assert.equal(projected(320, 420, 13, .2772, 'detail'), 'detail');
  assert.equal(projected(320, 420, 13, .277, 'detail'), 'outline', 'minimum Chat leaves detail just below 27.72%');
  assert.equal(projected(320, 420, 13, .25, 'outline'), 'outline', 'gradual zoom-out keeps the existing outline hysteresis');
  assert.equal(projected(320, 420, 13, .24, 'outline'), 'marker', 'the original 77.44px outline exit remains intact');
  assert.equal(projected(320, 420, 13, .30, 'outline'), 'outline', 'zoom-in holds outline below the 31.5% entry');
  assert.equal(projected(320, 420, 13, .315, 'outline'), 'detail');
  assert.equal(projected(448, 343, 11, .3, 'outline'), 'detail');
  assert.equal(projected(448, 343, 11, .264, 'detail'), 'detail');
  assert.equal(projected(448, 343, 11, .263, 'detail'), 'outline', 'native Browser leaves detail near 26.36%');
  assert.equal(projected(448, 343, 11, .25, 'outline'), 'outline');
  assert.equal(projected(448, 343, 11, .20, 'outline'), 'outline');
  assert.equal(projected(720, 500, 14, .21, 'detail'), 'detail');
  assert.equal(projected(720, 500, 14, .20, 'detail'), 'outline');
  assert.equal(projected(720, 500, 14, .23, 'outline'), 'outline');
  assert.equal(projected(720, 500, 14, .24, 'outline'), 'detail');
});

test('semantic zoom uses all projected pixel thresholds for small and large Cards', () => {
  const entered = { width: 100.8, height: 75.6, fontPx: 3.3, previous: 'outline' };
  assert.equal(surfaceSemanticLevel(entered), 'detail', 'all entry thresholds are inclusive');
  for (const [field, value] of [['width', 100.79], ['height', 75.59], ['fontPx', 3.29]]) {
    assert.equal(surfaceSemanticLevel({ ...entered, [field]: value }), 'outline', `${field} independently gates entry`);
  }
  const staying = { width: 240 * .42 * .88, height: 180 * .42 * .88, fontPx: 2.9, previous: 'detail' };
  assert.equal(surfaceSemanticLevel(staying), 'detail', 'all exit thresholds are inclusive');
  for (const [field, value] of [['width', staying.width - .01], ['height', staying.height - .01], ['fontPx', 2.89]]) {
    assert.equal(surfaceSemanticLevel({ ...staying, [field]: value }), 'outline', `${field} independently gates retention`);
  }
  assert.equal(surfaceSemanticLevel({ ...staying, previous: 'outline' }), 'outline', 'the same projection remains in the hysteresis gap');
  assert.equal(surfaceSemanticLevel({ width: 200, height: 140, fontPx: 14 }), 'detail');
  assert.equal(surfaceSemanticLevel({ width: 200 * .5, height: 140 * .5, fontPx: 14 * .5 }), 'outline',
    'a small Card abstracts when its projected dimensions are too small');
  const large = (zoom, previous) => surfaceSemanticLevel({ width: 1600 * zoom, height: 900 * zoom, fontPx: 16 * zoom, previous });
  assert.equal(large(.21, 'outline'), 'detail');
  assert.equal(large(.20, 'outline'), 'outline', 'a large Card still needs enough projected font');
  assert.equal(large(.19, 'detail'), 'detail');
  assert.equal(large(.18, 'detail'), 'outline');
  assert.equal(surfaceSemanticLevel({ width: 126, height: 84, fontPx: 3.3, previous: 'outline', detailWidth: 300, detailHeight: 200 }), 'detail');
  assert.equal(surfaceSemanticLevel({ width: 125.99, height: 84, fontPx: 3.3, previous: 'outline', detailWidth: 300, detailHeight: 200 }), 'outline',
    'caller-supplied reference dimensions scale the same way');
});

test('semantic zoom preserves outline-to-marker thresholds and hysteresis', () => {
  assert.equal(surfaceSemanticLevel({ width: 1600 * .07, height: 900 * .07, fontPx: 14 * .07 }), 'outline');
  assert.equal(surfaceSemanticLevel({ width: 720 * .07, height: 500 * .07, fontPx: 14 * .07 }), 'marker');
  assert.equal(surfaceSemanticLevel({ width: 88, height: 52, fontPx: .1 }), 'outline');
  assert.equal(surfaceSemanticLevel({ width: 87.99, height: 52, fontPx: .1 }), 'marker');
  assert.equal(surfaceSemanticLevel({ width: 88, height: 51.99, fontPx: .1 }), 'marker');
  assert.equal(surfaceSemanticLevel({ width: 78, height: 46, fontPx: 1, previous: 'outline' }), 'outline');
  assert.equal(surfaceSemanticLevel({ width: 70, height: 40, fontPx: 1, previous: 'outline' }), 'marker');
});

test('semantic zoom rejects degenerate and non-finite projections safely', () => {
  for (const bad of [0, -1, NaN, Infinity, -Infinity]) {
    for (const field of ['width', 'height', 'fontPx']) {
      assert.equal(surfaceSemanticLevel({ width: 720, height: 500, fontPx: 14, [field]: bad }),
        'marker', `${field}=${bad} cannot produce a visible detail proxy`);
    }
  }
  assert.equal(surfaceSemanticLevel(), 'marker');
});

test('semantic zoom counts connected local marker regions, never every Canvas Card', () => {
  const markers = [
    { id: 'a', cx: 0, cy: 0 }, { id: 'b', cx: 30, cy: 0 }, { id: 'c', cx: 60, cy: 0 },
    { id: 'far-1', cx: 500, cy: 0 }, { id: 'far-2', cx: 530, cy: 0 },
    { id: 'unrelated', cx: 1000, cy: 0 },
  ];
  const original = structuredClone(markers);
  assert.deepEqual(surfaceProximityClusters(markers), [['a', 'b', 'c'], ['far-1', 'far-2']]);
  assert.deepEqual(surfaceProximityClusters(markers.filter(item => item.id !== 'b')),
    [['far-1', 'far-2']], 'removal cannot leave a stale count or bridge');
  assert.deepEqual(surfaceProximityClusters(markers.filter(item => !item.id.startsWith('far-'))),
    [['a', 'b', 'c']], 'closing a region does not absorb unrelated Cards');
  assert.deepEqual(markers, original);
  assert.deepEqual(surfaceProximityClusters([
    { id: 'overlap-a', cx: 200, cy: 100, width: 80, height: 20 },
    { id: 'overlap-b', cx: 250, cy: 100, width: 80, height: 20 },
    { id: 'invalid', cx: NaN, cy: 100 }, { id: 'degenerate', cx: 200, cy: 100, width: 0 },
  ]), [['overlap-a', 'overlap-b']]);
  assert.deepEqual(surfaceProximityClusters(null), []);
});

test('production first-use focus presents the live Browser Card with the existing fullscreen system', () => {
  const body = surfaceSource.match(/  function focusInitialBrowserCard\(card, \{ persist = false \} = \{\}\) \{([\s\S]*?)\n  \}/)?.[1];
  assert.ok(body);
  const focus = compileFunction(`return function focusInitialBrowserCard(card, { persist = false } = {}) {${body}\n  }`,
    ['state', 'setSurfaceMode', 'document', 'SurfaceState', 'persistentEntityGeometry', 'safeViewportRect', 'enterCardFullscreen', 'isCardFullscreen', 'persistDeskSession']);
  const browser = { id: 'browser-view-a', _xulBrowser: { uri: 'https://example.test/' },
    geometry: { x: 15, y: 20, width: 1200, height: 720 }, classList: { remove() {} }, dataset: {} };
  const originalTarget = browser._xulBrowser;
  const originalGeometry = structuredClone(browser.geometry);
  const safe = { left: 0, top: 0, width: 1200, height: 720 };
  const state = { surface: { mode: 'desk' }, setCanvasViewportTarget: viewport => { state.camera = viewport; } };
  const classes = new Set();
  const document = { documentElement: { classList: {
    add: name => classes.add(name), remove: name => classes.delete(name),
  } } };
  let fullscreenCard = null, persisted = 0;
  const run = focus(state, () => { state.surface.mode = 'desk'; }, document, { fitSurfaceCamera }, card => card.geometry,
    () => { assert.ok(classes.has('egd-initial-browser-focus')); return safe; },
    card => { fullscreenCard = card; state.cardFullscreen = { cardId: card.id }; },
    card => state.cardFullscreen?.cardId === card.id, () => { persisted++; });
  assert.equal(run(browser), true);
  assert.equal(state.surface.browserCardId, browser.id);
  assert.equal(state.surface.mode, 'desk');
  assert.equal(fullscreenCard, browser);
  assert.ok(classes.has('egd-initial-browser-focus'));
  assert.equal(state.surface.initialBrowserFocus, true);
  assert.equal(browser._xulBrowser, originalTarget);
  assert.deepEqual(browser.geometry, originalGeometry);
  assert.equal(state.camera.zoom, 1);
  assert.equal(state.camera.pan.x, safe.left - browser.geometry.x);
  assert.equal(browser.dataset.testid, 'browser-card');
  assert.equal(persisted, 0);
  assert.ok(browser.geometry.width * state.camera.zoom * 0.5 < safe.width);
  assert.equal(browser.id, 'browser-view-a', 'zooming the camera never replaces the Browser view');
});

test('new Chat height reserves the readable composer above the Dock at 600/800/960/1280', () => {
  const body = surfaceSource.match(/  function fitCodexChatCardToReadableViewport\(card, safe, bodyFontPx\) \{([\s\S]*?)\n  \}/)?.[1];
  assert.ok(body, 'use the production Chat-only height cap');
  const fit = compileFunction(`return function fitCodexChatCardToReadableViewport(card, safe, bodyFontPx) {${body}\n  }`,
    ['window', 'state', 'visibleChatZoomRect', 'parsePxNumber', 'ZOOM_MAX', 'CHAT_ZOOM_GAP'])(
    { getComputedStyle: () => ({ minHeight: '420px', borderTopWidth: '1px', borderBottomWidth: '1px' }) },
    { zoom: 1 }, () => null,
    (value, fallback = 0) => Number.parseFloat(value) || fallback, 4, 8);
  const spawnStart = surfaceSource.indexOf('  function spawnCodexChatCard(');
  const browserStart = surfaceSource.indexOf('  // ============ Canvas Entity: Browser Card', spawnStart);
  const spawnBody = surfaceSource.slice(spawnStart, browserStart);
  assert.match(spawnBody,
    /fitCodexChatCardToReadableViewport\(card, safe,\s*/,
    'new Chat creation must apply the cap after mounting its actual body');
  assert(spawnBody.indexOf('host.appendChild(card)') < spawnBody.indexOf('fitCodexChatCardToReadableViewport(card, safe,') &&
    spawnBody.indexOf('fitCodexChatCardToReadableViewport(card, safe,') < spawnBody.indexOf("markAgendaDirty('create-chat-card', card)"),
  'the capped geometry must be in place before Chat creation is recorded');
  for (const { width, height } of [{ width: 600, height: 600 }, { width: 800, height: 600 },
    { width: 960, height: 700 }, { width: 1280, height: 776 }]) {
    const safe = { left: 24, top: 76, right: width - 24, bottom: height - 76,
      width: width - 48, height: height - 152 };
    const card = { style: { height: '680px', maxHeight: '' },
      classList: { contains: () => false }, getBoundingClientRect: () => ({}) };
    assert.equal(fit(card, safe, 11), true);
    const projectedHeight = (Number.parseFloat(card.style.maxHeight) + 2) * (10.6 / 11);
    assert(projectedHeight <= safe.height, `${width}x${height}: Chat bottom remains above Dock`);
    assert(Number.parseFloat(card.style.maxHeight) >= 420, `${width}x${height}: CSS minimum is preserved`);
    assert.equal(card.style.height, '680px', 'Dock fit never overwrites the saved world height');
    assert.equal(fit(card, safe, 11), false, 'a second fit does not keep resizing the Card');
  }
});

test('Chat Zoom clearance caps only presentation height and recovers on wider viewports', () => {
  const fitBody = surfaceSource.match(/  function fitCodexChatCardToReadableViewport\(card, safe, bodyFontPx\) \{([\s\S]*?)\n  \}/)?.[1];
  const zoomBody = surfaceSource.match(/  function visibleChatZoomRect\(\) \{([\s\S]*?)\n  \}/)?.[1];
  const geometryBody = surfaceSource.match(/  function persistentEntityGeometry\(entity\) \{([\s\S]*?)\n  \}/)?.[1];
  const screenBody = surfaceSource.match(/    const screenRect = \(card, zoom, pan\) => \{([\s\S]*?)\n    \};/)?.[1];
  assert.ok(fitBody && zoomBody && geometryBody && screenBody);
  const state = { zoom: 10.6 / 11, cardFullscreen: null };
  const zoomIndicator = { getBoundingClientRect: () => zoomRect };
  let zoomRect = { left: 88, right: 250, top: 492, bottom: 533, width: 162, height: 41 };
  let indicatorVisible = true;
  let screenLeft = 227;
  let screenTop = 76;
  const window = { getComputedStyle: node => node === zoomIndicator
    ? { display: indicatorVisible ? 'flex' : 'none', visibility: 'visible', opacity: '1' }
    : { minHeight: '420px', boxSizing: 'content-box', borderTopWidth: '1px', borderBottomWidth: '1px' } };
  const document = { getElementById: id => id === 'egd-zoom-indicator' ? zoomIndicator : null };
  const px = (value, fallback = 0) => Number.parseFloat(value) || fallback;
  const visibleZoom = compileFunction(`return function visibleChatZoomRect() {${zoomBody}\n  }`,
    ['document', 'window'])(document, window);
  const fit = compileFunction(`return function fitCodexChatCardToReadableViewport(card, safe, bodyFontPx) {${fitBody}\n  }`,
    ['window', 'state', 'visibleChatZoomRect', 'parsePxNumber', 'ZOOM_MAX', 'CHAT_ZOOM_GAP'])(
    window, state, visibleZoom, px, 4, 8);
  const persistent = compileFunction(`return function persistentEntityGeometry(entity) {${geometryBody}\n  }`,
    ['state', 'parsePxNumber'])(state, px);
  const screenRect = compileFunction(`return (card, zoom, pan) => {${screenBody}\n    }`,
    ['parsePxNumber'])(px);
  const card = { id: 'chat-a', isConnected: true,
    style: { left: '147px', top: '76px', width: '440px', height: '680px', maxHeight: '', zIndex: '9' },
    classList: { contains: name => name === 'egd-chat-card' },
    getBoundingClientRect() {
      const visibleHeight = Math.min(px(this.style.height), px(this.style.maxHeight, Infinity));
      return { left: screenLeft, right: screenLeft + 442 * state.zoom, top: screenTop,
        bottom: screenTop + (visibleHeight + 2) * state.zoom, width: 442 * state.zoom,
        height: (visibleHeight + 2) * state.zoom };
    } };
  const saved = persistent(card);
  const safeFor = (width, height) => ({ left: 24, top: 76, right: width - 24,
    bottom: height - 76, width: width - 48, height: height - 152 });
  for (const [width, screenX] of [[800, 227], [600, 120]]) {
    screenLeft = screenX;
    assert.equal(fit(card, safeFor(width, 600), 11), width === 800);
    const visible = card.getBoundingClientRect();
    assert(visible.bottom <= zoomRect.top - 8 + 0.01, `${width}x600: full Chat stays 8px above Zoom`);
    assert(Number.parseFloat(card.style.maxHeight) >= 420, 'header, footer, and readable font retain CSS minimum');
    assert.deepEqual(persistent(card), saved, 'temporary presentation cap cannot change saved or Board geometry');
    const projected = screenRect(card, state.zoom, { x: 0, y: 0 });
    assert.equal(projected.world.height, 680, 'semantic snapshot retains saved world height');
    assert.equal(projected.visualWorld.height, Number.parseFloat(card.style.maxHeight),
      'camera projection uses the displayed height');
  }
  const narrowCap = Number.parseFloat(card.style.maxHeight);
  const projectionBody = surfaceSource.match(/    const focusProjection = \(entry, \{ revealHeader = false \} = \{\}\) => \{([\s\S]*?)\n    \};/)?.[1];
  assert.ok(projectionBody, 'exercise the actual Chat focus camera after presentation fit');
  state.pan = { x: 0, y: 0 };
  let target = null;
  state.setCanvasViewportTarget = value => { target = value; };
  const focus = compileFunction(`return (entry, { revealHeader = false } = {}) => {${projectionBody}\n    }`,
    ['state', 'authorVisible', 'screenRect', 'safeViewportRect', 'SurfaceState', 'ZOOM_MAX',
      'detailWidth', 'detailHeight', 'focusCanvasCard', 'visibleChatZoomRect',
      'window', 'parsePxNumber', 'CHAT_ZOOM_GAP'])(state, () => true, screenRect,
    () => safeFor(600, 600), { fitSurfaceCamera }, 4, 240, 180, () => {}, visibleZoom, window, px, 8);
  focus({ card, kind: 'chat', bodyFontPx: 11 }, { revealHeader: true });
  assert.ok(target, 'Dock Chat focus produces one camera target');
  const projected = screenRect(card, target.zoom, target.pan);
  screenLeft = projected.x; screenTop = projected.y;
  state.zoom = target.zoom; state.pan = target.pan;
  assert(screenTop >= 76 - 0.01, 'Chat header remains below the rail');
  assert(card.getBoundingClientRect().bottom <= zoomRect.top - 8 + 0.01,
    'focus uses the same Zoom top minus 8px boundary and cannot recenter into overlap');
  assert.equal(fit(card, safeFor(600, 600), 11), false,
    'settled camera does not toggle the presentation cap on the next frame');
  const settledTarget = target;
  target = null;
  focus({ card, kind: 'chat', bodyFontPx: 11 }, { revealHeader: true });
  assert(Math.abs(target.pan.y - settledTarget.pan.y) < 0.01,
    'repeated Chat focus has no cap/recenter oscillation');
  assert.deepEqual(persistent(card), saved);
  screenTop = 76;
  zoomRect = { left: 15, right: 177, top: 645, bottom: 686, width: 162, height: 41 };
  screenLeft = 227;
  for (const [width, height] of [[960, 700], [1280, 776]]) {
    fit(card, safeFor(width, height), 11);
    assert(Number.parseFloat(card.style.maxHeight) > narrowCap,
      `${width}x${height}: Zoom-only cap clears; only the existing Dock cap may remain`);
    assert.deepEqual(persistent(card), saved);
  }
  fit(card, safeFor(1280, 900), 11);
  assert.equal(card.style.maxHeight, '', 'enough vertical space restores the full saved display height');
  assert.equal(screenRect(card, state.zoom, { x: 0, y: 0 }).visualWorld.height, 680);
  assert.deepEqual(persistent(card), saved);

  zoomRect = { left: 0, right: 80, top: 492, bottom: 533, width: 80, height: 41 };
  screenLeft = 120;
  fit(card, safeFor(600, 600), 11);
  const dockOnly = card.style.maxHeight;
  assert(Number.parseFloat(dockOnly) > narrowCap, 'non-intersecting Zoom does not trigger its extra cap');
  indicatorVisible = false;
  zoomRect.left = 88; zoomRect.right = 250;
  assert.equal(fit(card, safeFor(600, 600), 11), false, 'a hidden Zoom is ignored');
  assert.equal(card.style.maxHeight, dockOnly);
  assert.deepEqual(persistent(card), saved);

  indicatorVisible = true;
  card.style.height = '540px'; // a restored/user-sized Chat Card, not the new-card default
  const custom = persistent(card);
  fit(card, safeFor(600, 600), 11);
  assert.equal(card.style.height, '540px');
  assert.deepEqual(persistent(card), custom);
  zoomRect = { left: 88, right: 250, top: 791, bottom: 832, width: 162, height: 41 };
  fit(card, safeFor(1280, 900), 11);
  assert.equal(card.style.maxHeight, '', 'a wide viewport restores the exact user-sized display');
  assert.deepEqual(persistent(card), custom);
  zoomRect = { left: 88, right: 250, top: 492, bottom: 533, width: 162, height: 41 };
  fit(card, safeFor(600, 600), 11);
  assert.notEqual(card.style.maxHeight, '');
  card.classList.contains = name => name === 'egd-chat-card' || name === 'egd-card-fullscreen';
  fit(card, safeFor(600, 600), 11);
  assert.equal(card.style.maxHeight, '', 'fullscreen is never held to the temporary Chat cap');
});

