test('human Chat Dock open after initial Browser focus and zoom-out focuses only a compact Chat to readable detail', () => {
  const projectionBody = surfaceSource.match(/    const focusProjection = \(entry, \{ revealHeader = false \} = \{\}\) => \{([\s\S]*?)\n    \};/)?.[1];
  const compactBody = surfaceSource.match(/    const focusChatDockIfCompact = card => \{([\s\S]*?)\n    \};/)?.[1];
  const dockStart = surfaceSource.indexOf('  function buildDock() {');
  const dockEnd = surfaceSource.indexOf('    const divider =', dockStart);
  const dockBody = surfaceSource.slice(dockStart, dockEnd).match(/onclick: \(\) => \{([\s\S]*?)\n\s*\},\n\s*\}, el\('span', \{ class: 'egd-dock-icon' \}/)?.[1];
  assert.ok(projectionBody && compactBody && dockBody, 'use the production Dock and semantic-projection paths');

  const fitBody = surfaceSource.match(/  function fitCodexChatCardToReadableViewport\(card, safe, bodyFontPx\) \{([\s\S]*?)\n  \}/)?.[1];
  assert.ok(fitBody);
  let safe = { left: 147, top: 76, right: 1256, bottom: 694, width: 1109, height: 618 };
  let dockZoomRect = null;
  const browser = { x: 15, y: 20, width: 1200, height: 720 };
  const initial = fitSurfaceCamera(browser,
    { left: 0, top: 0, width: 1200, height: 800 }, 1);
  const cameraTargets = [], focused = [];
  const frames = new Map(), listeners = new Map();
  let nextFrame = 0, composerFocuses = 0;
  const window = { requestAnimationFrame: fn => { frames.set(++nextFrame, fn); return nextFrame; },
    cancelAnimationFrame: id => frames.delete(id),
    getComputedStyle: () => ({ minHeight: '420px', borderTopWidth: '1px', borderBottomWidth: '1px' }) };
  const viewport = { id: 'canvas-viewport' };
  const document = { activeElement: { id: 'dock-button' },
    getElementById: () => null,
    addEventListener: (name, fn) => listeners.set(name, fn),
    removeEventListener: (name, fn) => { if (listeners.get(name) === fn) listeners.delete(name) },
    emit: (name, target) => listeners.get(name)?.({ target }) };
  const flushFrames = () => { const pending = [...frames.values()]; frames.clear(); pending.forEach(fn => fn()) };
  const state = { panModifier: false, zoom: initial.zoom, zoomTarget: initial.zoom,
    pan: initial.pan, panTarget: initial.pan, codex: { activeThreadId: 'room', hudView: 'list',
      chatCardEntityId: null, chatDockMode: 'hud',
      threadDrafts: { room: 'unsent human draft' } },
    setCanvasViewportTarget: target => { cameraTargets.push(target); state.zoomTarget = target.zoom; state.panTarget = target.pan; },
    codexBridge: { selectThread: (id, options) => { assert.equal(id, 'room'); assert.deepEqual(options, { openConversation: true }); } } };
  const fitChat = compileFunction(`return function fitCodexChatCardToReadableViewport(card, safe, bodyFontPx) {${fitBody}\n  }`,
    ['window', 'state', 'visibleChatZoomRect', 'parsePxNumber', 'ZOOM_MAX', 'CHAT_ZOOM_GAP'])(
    window, state, () => dockZoomRect, (value, fallback = 0) => Number.parseFloat(value) || fallback, 4, 8);
  assert.equal(state.zoom, 1, 'initial Browser focus is the starting camera');
  state.zoom = state.zoomTarget = 0.83;

  const composer = { isConnected: true, disabled: false,
    focus: () => { composerFocuses++; document.activeElement = composer } };
  const messages = { scrollTop: 247 };
  const card = { id: 'chat-card', isConnected: true,
    style: { left: '100px', top: '90px', width: '440px', height: '680px', maxHeight: '' },
    classList: { contains: name => name === 'egd-chat-card' },
    getBoundingClientRect() {
      const zoom = state.zoom;
      const height = Math.min(Number.parseFloat(this.style.height),
        Number.parseFloat(this.style.maxHeight) || Infinity);
      const left = state.pan.x + Number.parseFloat(this.style.left) * zoom;
      const top = state.pan.y + Number.parseFloat(this.style.top) * zoom;
      return { left, top, right: left + 442 * zoom, bottom: top + (height + 2) * zoom,
        width: 442 * zoom, height: (height + 2) * zoom };
    },
    contains: node => node === composer,
    querySelector: selector => selector === '.egd-codex-input' ? composer
      : selector === '.egd-codex-messages' ? messages : null };
  const entries = new Map();
  const syncEntries = () => { if (!entries.has(card)) entries.set(card, {
    card, kind: 'chat', bodyFontPx: 11, level: null, visibilityDirty: false,
  }); };
  const screenRect = (target, zoom, pan = state.panTarget) => {
    const world = { x: parseFloat(target.style.left), y: parseFloat(target.style.top),
      width: parseFloat(target.style.width), height: parseFloat(target.style.height) };
    const visualWorld = { ...world, height: Math.min(world.height,
      parseFloat(target.style.maxHeight) || Infinity) };
    return { world, x: pan.x + world.x * zoom, y: pan.y + world.y * zoom,
      visualWorld, width: world.width * zoom, height: visualWorld.height * zoom };
  };
  const surface = { surfaceSemanticLevel, fitSurfaceCamera };
  const focusProjection = compileFunction(`return (entry, { revealHeader = false } = {}) => {${projectionBody}\n    }`,
    ['state', 'authorVisible', 'screenRect', 'safeViewportRect', 'SurfaceState', 'ZOOM_MAX',
      'detailWidth', 'detailHeight', 'focusCanvasCard', 'visibleChatZoomRect',
      'window', 'parsePxNumber', 'CHAT_ZOOM_GAP'])(state, () => true, screenRect, () => safe,
    surface, 4, 240, 180, target => focused.push(target), () => dockZoomRect,
    window, (value, fallback = 0) => Number.parseFloat(value) || fallback, 8);
  state.focusChatDockIfCompact = compileFunction(`let cancelPendingChatComposerFocus = () => {};\nreturn card => {${compactBody}\n    }`,
    ['state', 'syncEntries', 'entries', 'authorVisible', 'screenRect', 'SurfaceState',
      'detailWidth', 'detailHeight', 'safeViewportRect', 'fitCodexChatCardToReadableViewport',
      'focusProjection', 'window', 'document', 'viewport', 'visibleChatZoomRect',
      'parsePxNumber', 'CHAT_ZOOM_GAP'])(state, syncEntries, entries, () => true,
    screenRect, surface, 240, 180, () => safe, fitChat, focusProjection, window, document, viewport,
    () => dockZoomRect,
    (value, fallback = 0) => Number.parseFloat(value) || fallback, 8);
  let spawned = 0, returnCueDismissed = 0;
  const dockClick = compileFunction(`return () => {${dockBody}\n          }`,
    ['kind', 'item', 'state', 'spawnCodexChatCard', 'toggleHUD', 'dismissChatReturnCue'])(
    'left', { id: 'chat', label: '채팅' }, state, () => {
      spawned++; state.activeEntityId = card.id; state.codex.chatCardEntityId = card.id;
      state.codex.chatDockMode = 'canvas'; return card;
    },
    () => assert.fail('Chat Dock must not toggle a visible Chat off'), () => { returnCueDismissed++; });

  dockClick();
  assert.equal(spawned, 1);
  assert.equal(returnCueDismissed, 1, 'the Dock Chat also clears a way-back-to-Chat cue');
  assert.equal(cameraTargets.length, 1, 'compact Chat opens with its existing focus projection');
  assert(Math.abs(cameraTargets[0].zoom - 10.6 / 11) < 0.001);
  assert.ok(cameraTargets[0].pan.y + 90 * cameraTargets[0].zoom >= safe.top,
    'the focused Chat header clears the topbar after the Card is presentation-capped');
  assert.ok(cameraTargets[0].pan.y + (90 + Number.parseFloat(card.style.maxHeight) + 2) * cameraTargets[0].zoom <= safe.bottom,
    'the focused Chat composer-bearing Card remains above the Dock');
  assert.equal(focused[0], card);
  assert.equal(state.codex.hudView, 'conversation');
  assert.equal(state.codex.threadDrafts.room, 'unsent human draft');
  assert.equal(composerFocuses, 0, 'camera target alone is not an immediate keyboard focus');
  state.zoom = cameraTargets[0].zoom;
  state.pan = { ...cameraTargets[0].pan };
  entries.get(card).level = 'detail';
  document.activeElement = viewport; // semantic restoration may move focus here during animation
  flushFrames();
  assert.equal(composerFocuses, 1, 'composer receives keyboard focus after readable animation settles');
  assert.equal(state.focusChatDockIfCompact({ ...card,
    classList: { contains: name => name === 'egd-browser-card' } }), false,
  'this human Dock repair must not change Browser or other View LOD/camera');
  assert.equal(cameraTargets.length, 1);

  state.zoom = state.zoomTarget = 0.83;
  entries.get(card).level = 'outline';
  dockClick();
  assert.equal(cameraTargets.length, 2);
  const otherCard = { id: 'other-card' };
  document.activeElement = otherCard;
  state.activeEntityId = otherCard.id;
  document.emit('mousedown', otherCard);
  state.zoom = cameraTargets[1].zoom;
  state.pan = { ...cameraTargets[1].pan };
  entries.get(card).level = 'detail';
  flushFrames();
  assert.equal(composerFocuses, 1, 'another human Card click cancels the pending Chat keyboard focus');

  // The presentation-capped Card is safe at its settled readable focus;
  // forcing 100% here would make even this fixture taller than safe.
  state.zoom = state.zoomTarget = cameraTargets[1].zoom;
  state.pan = state.panTarget = { ...cameraTargets[1].pan };
  entries.get(card).level = 'detail';
  dockClick();
  assert.equal(spawned, 3, 'the existing Chat Card is reused, not closed');
  assert.equal(cameraTargets.length, 2, 'normal readable zoom keeps the human camera unchanged');
  assert.equal(composerFocuses, 1, 'normal visible Chat keeps its existing input ownership');
  assert.equal(state.codex.threadDrafts.room, 'unsent human draft');

  // A normal wheel pan may leave the same readable Chat's header above the
  // rail. Only the later explicit Dock click should reveal it again.
  const panBody = surfaceSource.match(/    const panCanvasByWheel = \(ev\) => \{([\s\S]*?)\n    \};/)?.[1];
  assert.ok(panBody);
  const panWheel = compileFunction(`return ev => {${panBody}\n    }`,
    ['state', 'normalizeWheelDelta', 'WHEEL_PAN_SPEED', 'scheduleAnimate'])(state, () => 1, 1.15, () => {});
  state.zoom = state.zoomTarget = 0.968;
  state.pan = state.panTarget = { x: 328.77, y: 0 };
  panWheel({ deltaX: 0, deltaY: 236.85 / 1.15 });
  state.pan = { ...state.panTarget }; // settled wheel animation
  const offscreen = screenRect(card, state.zoomTarget, state.panTarget);
  assert.ok(Math.abs(offscreen.x - 425.57) < 0.01 && Math.abs(offscreen.y + 149.73) < 0.01);
  assert.equal(cameraTargets.length, 2, 'wheel pan never auto-reveals Chat');
  const originalWorldRect = structuredClone(card.style);
  const originalThread = state.codex.activeThreadId;
  const originalDraft = state.codex.threadDrafts.room;
  const originalScroll = messages.scrollTop;
  entries.get(card).level = 'detail';
  dockClick();
  assert.equal(spawned, 4, 'Dock reuses the existing Chat View');
  assert.equal(cameraTargets.length, 3, 'Dock reveals an offscreen detail Chat by camera only');
  const reveal = cameraTargets.at(-1);
  assert.ok(reveal.pan.y + 90 * reveal.zoom >= safe.top,
    'the existing Chat title is reachable below the topbar');
  assert.ok(reveal.pan.y + (90 + 32) * reveal.zoom <= safe.bottom,
    'the whole Chat header remains reachable above the Dock');
  assert.deepEqual(card.style, originalWorldRect);
  assert.equal(state.codex.activeThreadId, originalThread);
  assert.equal(state.codex.threadDrafts.room, originalDraft);
  assert.equal(messages.scrollTop, originalScroll);

  // At CSS min-height the presentation cannot contract any further. The
  // detail-level Card fits Dock, but its footer still crosses the Zoom gap.
  // A Dock re-click must move the camera instead of taking the old early exit.
  safe = { left: 24, top: 76, right: 776, bottom: 524, width: 752, height: 448 };
  dockZoomRect = { left: 88, right: 250, top: 492, bottom: 533, width: 162, height: 41 };
  card.style.maxHeight = '420px';
  const savedWorld = { ...card.style };
  state.zoom = state.zoomTarget = 10.6 / 11;
  state.pan = state.panTarget = { x: 100, y: 90 - 90 * state.zoom };
  entries.get(card).level = 'detail';
  assert.equal(fitChat(card, safe, 11), false, 'CSS minimum blocks a further height reduction');
  assert(card.getBoundingClientRect().bottom > dockZoomRect.top - 8,
    'initial detail Card violates the required Zoom clearance despite fitting Dock');
  const beforeZoomRepair = cameraTargets.length;
  dockClick();
  assert.equal(cameraTargets.length, beforeZoomRepair + 1,
    'Dock re-click cannot early-return when Zoom masks the minimum-height Chat');
  const repaired = cameraTargets.at(-1);
  state.zoom = state.zoomTarget = repaired.zoom;
  state.pan = state.panTarget = { ...repaired.pan };
  assert(card.getBoundingClientRect().bottom <= dockZoomRect.top - 8 + 0.5,
    'Chat-only camera target clears the actual outer Card from Zoom');
  assert.deepEqual(card.style, savedWorld, 'camera repair does not change saved world geometry or size');
  assert.equal(fitChat(card, safe, 11), false, 'settled minimum-height cap does not oscillate');
  entries.get(card).level = 'detail';
  dockClick();
  assert.equal(cameraTargets.length, beforeZoomRepair + 1,
    'a second Dock click at the settled Zoom-safe target does not recenter again');
  assert.equal(state.codex.threadDrafts.room, 'unsent human draft');
  safe = { left: 24, top: 76, right: 1256, bottom: 824, width: 1232, height: 748 };
  dockZoomRect = { left: 88, right: 250, top: 791, bottom: 832, width: 162, height: 41 };
  assert.equal(fitChat(card, safe, 11), true, 'wide viewport removes the temporary cap');
  assert.equal(card.style.maxHeight, '');
  assert.equal(card.style.height, '680px', 'wide recovery restores the original displayed height');
  assert.equal(card.style.left, savedWorld.left);
  assert.equal(card.style.top, savedWorld.top);
  dockZoomRect = null;

  for (const size of [{ width: 800, height: 600 }, { width: 600, height: 600 },
    { width: 960, height: 700 }, { width: 1280, height: 776 }]) {
    safe = { left: 24, top: 76, right: size.width - 24, bottom: size.height - 76,
      width: size.width - 48, height: size.height - 152 };
    card.style.height = '680px'; // existing pre-fix Chat, same DOM identity and draft
    state.zoom = state.zoomTarget = size.width === 800 ? 1 : 0.83;
    entries.get(card).level = size.width === 800 ? 'detail' : 'outline';
    const before = cameraTargets.length;
    dockClick();
    assert.equal(cameraTargets.length, before + 1,
      `${size.width}x${size.height}: even a detail-level but clipped Chat is revealed`);
    assert.equal(state.codex.chatCardEntityId, card.id);
    assert.equal(state.codex.threadDrafts.room, 'unsent human draft');
    assert.deepEqual(browser, { x: 15, y: 20, width: 1200, height: 720 },
      'Chat reveal does not resize the Browser world');
    const target = cameraTargets.at(-1);
    const actualHeight = Number.parseFloat(card.style.maxHeight) || Number.parseFloat(card.style.height);
    const x = target.pan.x + 100 * target.zoom;
    const y = target.pan.y + 90 * target.zoom;
    assert(x >= safe.left - 0.5 && x + 440 * target.zoom <= safe.right + 0.5);
    assert(y >= safe.top - 0.5 && y + (actualHeight + 2) * target.zoom <= safe.bottom + 0.5,
      `${size.width}x${size.height}: composer-bearing Card is fully above the Dock`);
  }
});

test('production Focus frames the unchanged world Card and does not pin it during later camera frames', () => {
  const enterBody = surfaceSource.match(/  function enterCardFullscreen\(card\) \{([\s\S]*?)\n  \}/)?.[1];
  const layoutBody = surfaceSource.match(/  function syncCardFullscreenLayout\(\{ reframe = false \} = \{\}\) \{([\s\S]*?)\n  \}/)?.[1];
  assert.ok(enterBody && layoutBody);
  const enter = compileFunction(`return function enterCardFullscreen(card) {${enterBody}\n  }`,
    ['state', 'exitCardFullscreen', 'isCardFullscreen', 'document', 'getCardRect', 'cardZ', 'setActiveEntity', 'setHudPresentationHidden', 'closeDeskMinimap', 'syncCardFullscreenLayout', 'syncViewportAgendaRail']);
  const layout = compileFunction(`return function syncCardFullscreenLayout({ reframe = false } = {}) {${layoutBody}\n  }`,
    ['state', 'document', 'safeViewportRect', 'syncViewportAgendaRail', 'parsePxNumber', 'SurfaceState', 'ZOOM_MAX']);
  const target = { uri: 'https://example.test/', session: {} };
  const card = { id: 'browser-view-a', isConnected: true, _xulBrowser: target,
    style: { left: '45px', top: '60px', width: '900px', height: '620px', zIndex: '41000' },
    classList: {
      contains: name => name === 'egd-browser-card',
      add: name => { assert.equal(name, 'egd-card-fullscreen'); },
    } };
  const prior = structuredClone(card.style);
  const rootClasses = new Set();
  const document = { documentElement: { classList: { add: name => rootClasses.add(name) } },
    getElementById: id => id === card.id ? card : null };
  const state = { surface: { initialBrowserFocus: true }, cardFullscreen: null,
    pan: { x: 0, y: 0 }, zoom: 1, setCanvasViewportTarget(camera) { this.camera = camera; } };
  let safeOptions = null, activated = null;
  const syncLayout = layout(state, document, options => {
    safeOptions = options;
    return { left: 0, top: 0, width: 1600, height: 960 };
  }, () => {}, Number.parseFloat, Surface, 4);
  const enterFullscreen = enter(state, () => assert.fail('no previous fullscreen Card'), () => false,
    document, current => structuredClone(current.style), 42000, current => { activated = current; },
    () => {}, () => assert.fail('no minimap is open'), syncLayout, () => {});
  enterFullscreen(card);
  assert.equal(activated, card);
  assert.equal(state.cardFullscreen.cardId, card.id);
  assert.deepEqual(state.cardFullscreen.rect, prior);
  assert.deepEqual(card.style, { ...prior, zIndex: '42001' });
  assert.deepEqual(state.camera, fitSurfaceCamera({ x: 45, y: 60, width: 900, height: 620 },
    { left: 0, top: 0, width: 1600, height: 960 }, 4));
  state.camera = null; state.zoom = .2; state.pan = { x: 300, y: 200 };
  syncLayout();
  assert.equal(state.camera, null, 'ordinary camera apply cannot reframe Focus');
  assert.deepEqual(card.style, { ...prior, zIndex: '42001' });
  assert.deepEqual(safeOptions, { avoidHud: false, margin: 0 });
  assert.ok(rootClasses.has('egd-card-fullscreen-active'));
  assert.ok(rootClasses.has('egd-browser-fullscreen-active'));
  assert.equal(card._xulBrowser, target);
});

function createFullscreenHarness({ hudInitiallyHidden = false, minimapInitiallyOpen = true } = {}) {
  const body = signature => {
    const header = `  function ${signature} {`;
    const start = surfaceSource.indexOf(header);
    if (start < 0) return null;
    const end = surfaceSource.indexOf('\n  }', start + header.length);
    return end < 0 ? null : surfaceSource.slice(start + header.length, end);
  };
  const compile = (signature, dependencies) => {
    const source = body(signature);
    assert.ok(source, `production ${signature} must remain testable`);
    return compileFunction(`return function ${signature} {${source}\n  }`, dependencies);
  };
  const rootClasses = new Set();
  const hudClasses = new Set(hudInitiallyHidden ? ['egd-hud-hidden'] : []);
  const cards = new Map();
  const viewport = { innerWidth: 1280, innerHeight: 774 };
  let minimapOpen = minimapInitiallyOpen;
  let hudFitCount = 0;
  let saved = 0;
  const minimap = { remove: () => { minimapOpen = false; } };
  const hud = { classList: {
    contains: name => hudClasses.has(name),
    toggle: (name, enabled) => enabled ? hudClasses.add(name) : hudClasses.delete(name),
  } };
  const document = {
    documentElement: { classList: {
      add: name => rootClasses.add(name),
      remove: name => rootClasses.delete(name),
    } },
    getElementById: id => id === 'egd-hud' ? hud
      : id === 'egd-desk-minimap' ? (minimapOpen ? minimap : null)
        : cards.get(id) || null,
  };
  const state = { surface: { initialBrowserFocus: false, browserCardId: 'browser-view-a' },
    cardFullscreen: null, activeEntityId: null, pan: { x: 100, y: 50 }, zoom: 2,
    panTarget: { x: 100, y: 50 }, zoomTarget: 2,
    setCanvasViewportTarget(camera) {
      this.pan = { ...camera.pan }; this.panTarget = { ...camera.pan };
      this.zoom = camera.zoom; this.zoomTarget = camera.zoom;
    } };
  const safeCalls = [];
  const safe = compile('safeViewportRect(options = {})', ['window', 'document'])(viewport, document);
  const setHud = compile('setHudPresentationHidden(hidden)', ['document', 'syncHudViewportFit'])(document, () => { hudFitCount++; });
  const getRect = compile('getCardRect(card)', [])();
  const applyRect = compile('applyCardRect(card, rect)', [])();
  const isFullscreen = compile('isCardFullscreen(card)', ['state'])(state);
  const layout = compile('syncCardFullscreenLayout({ reframe = false } = {})',
    ['state', 'document', 'safeViewportRect', 'syncViewportAgendaRail', 'parsePxNumber', 'SurfaceState', 'ZOOM_MAX'])(
    state, document, options => {
      safeCalls.push(options);
      return safe(options);
    }, () => {}, Number.parseFloat, Surface, 4);
  const hudCloses = [];
  const restoreHud = compile('restoreHudAfterCardFullscreen(fullscreen)', ['state', 'setHudPresentationHidden', 'toggleHUD'])(
    state, setHud, appId => { hudCloses.push(appId); state.hudOpen = false; hudClasses.add('egd-hud-hidden'); });
  const exit = compile('exitCardFullscreen(card = null, options = {})',
    ['state', 'document', 'applyCardRect', 'restoreHudAfterCardFullscreen', 'toggleDeskMinimap', 'setActiveEntity', 'syncViewportAgendaRail', 'scheduleDeskSessionSave'])(
    state, document, applyRect, restoreHud, () => {
      assert.equal(state.cardFullscreen, null, 'minimap reopens after fullscreen state clears');
      minimapOpen = !minimapOpen;
    }, card => { state.activeEntityId = card?.id || null; }, () => {}, () => { saved++; });
  const enter = compile('enterCardFullscreen(card)',
    ['state', 'exitCardFullscreen', 'isCardFullscreen', 'document', 'getCardRect', 'cardZ', 'setActiveEntity', 'setHudPresentationHidden', 'closeDeskMinimap', 'syncCardFullscreenLayout', 'syncViewportAgendaRail'])(
    state, exit, isFullscreen, document, getRect, 40000,
    card => { state.activeEntityId = card?.id || null; }, setHud,
    () => document.getElementById('egd-desk-minimap')?.remove(), layout, () => {});
  const makeCard = (id, kind, rect) => {
    const classes = new Set(['egd-canvas-card', kind]);
    const card = { id, isConnected: true, style: { ...rect }, classList: {
      contains: name => classes.has(name),
      add: name => classes.add(name),
      remove: name => classes.delete(name),
    }, remove() { this.isConnected = false; cards.delete(id); } };
    cards.set(id, card);
    return card;
  };
  const browserRect = { left: '45px', top: '60px', width: '900px', height: '620px', zIndex: '41000' };
  const browser = makeCard('browser-view-a', 'egd-browser-card', browserRect);
  const chatRect = { left: '70px', top: '80px', width: '640px', height: '450px', zIndex: '41001' };
  const chat = makeCard('chat-view-a', 'egd-chat-card', chatRect);
  return { browser, browserRect, chat, chatRect, cards, document, state, rootClasses, hudClasses,
    safeCalls, enter, exit, layout, isFullscreen, hudCloses,
    get minimapOpen() { return minimapOpen; },
    set minimapOpen(value) { minimapOpen = value; },
    get hudFitCount() { return hudFitCount; },
    get saved() { return saved; } };
}

test('normal Browser and Chat Focus keep zoom-in focused and unfold only zoom-out without a camera jump', () => {
  const factorBody = surfaceSource.match(/    const zoomCanvasByFactor = \(factor, cx, cy\) => \{([\s\S]*?)\n    \};\n    const zoomCanvasByWheel/)?.[1];
  assert.ok(factorBody);
  for (const kind of ['browser', 'chat']) {
    const h = createFullscreenHarness(), card = h[kind];
    const geometry = { ...card.style }, runtime = Object.freeze({ url: 'https://example.test/', viewport: [1440, 900], fullZoom: 1.25 });
    card._browser = runtime;
    h.enter(card);
    let animated = 0;
    const zoom = compileFunction(`return (factor, cx, cy) => {${factorBody}}`,
      ['state', 'ZOOM_MIN', 'ZOOM_MAX', 'exitCardFullscreen', 'enterLocalDesk', 'frame', 'window', 'apply', 'scheduleAnimate'])(
      h.state, .01, 4, h.exit, () => assert.fail('ordinary Focus is not first-use mode'), 0,
      { cancelAnimationFrame() {} }, h.layout, () => { animated++; });
    const originalZoom = h.state.zoom;
    zoom(1.1, 320, 250);
    assert.equal(h.state.cardFullscreen.cardId, card.id, 'zoom-in must KEEP Focus');
    assert.equal(h.state.zoom, originalZoom * 1.1);
    assert.ok(h.rootClasses.has('egd-card-fullscreen-active'));
    const before = { zoom: h.state.zoom, pan: { ...h.state.pan } };
    const oldScreen = { x: Number.parseFloat(geometry.left) * before.zoom + before.pan.x,
      y: Number.parseFloat(geometry.top) * before.zoom + before.pan.y };
    zoom(.99, 930, 640);
    assert.equal(h.state.cardFullscreen, null);
    assert.equal(h.rootClasses.has('egd-card-fullscreen-active'), false);
    assert.equal(h.state.zoom, before.zoom, 'release changes no rendered camera before the next animation frame');
    assert.deepEqual(h.state.pan, before.pan);
    assert.equal(h.state.zoomTarget, before.zoom * .99);
    assert.ok(Math.abs(h.state.panTarget.x - (930 - (930 - before.pan.x) * .99)) < 1e-9);
    assert.ok(Math.abs(h.state.panTarget.y - (640 - (640 - before.pan.y) * .99)) < 1e-9);
    const nextScreen = { x: Number.parseFloat(geometry.left) * h.state.zoomTarget + h.state.panTarget.x,
      y: Number.parseFloat(geometry.top) * h.state.zoomTarget + h.state.panTarget.y };
    assert.ok(Math.abs(nextScreen.x - (930 + (oldScreen.x - 930) * .99)) < 1e-9);
    assert.ok(Math.abs(nextScreen.y - (640 + (oldScreen.y - 640) * .99)) < 1e-9);
    assert.equal(animated, 1);
    assert.deepEqual(card.style, geometry, 'no original-size restoration jump: dimensions never changed');
    assert.equal(card._browser, runtime);
    assert.equal(h.state.canvasUserCameraRevision, 2);
  }
});

function terminalFrameWheelHarness() {
  // Execute the production camera functions and shared session, not a second
  // implementation of the routing policy. Only DOM/animation are stand-ins.
  const binding = name => {
    const start = surfaceSource.indexOf(`    ${name} = `);
    const end = surfaceSource.indexOf('\n    };', start);
    assert.ok(start > 0 && end > start, name);
    return surfaceSource.slice(start, end + '\n    };'.length);
  };
  const constant = name => Number(surfaceSource.match(new RegExp(`const ${name} = ([\\d.]+);`))[1]);
  class Element {
    constructor() { this.isConnected = true; this.hidden = false; }
    closest(selector) { return this.hud && selector.includes('#egd-hud') ? this : null; }
  }
  const state = { activeEntityId: 'terminal-a', pan: { x: 50, y: -20 }, panTarget: { x: 50, y: -20 },
    zoom: .5, zoomTarget: .5, surface: {}, cardFullscreen: null };
  const frame = new Element(), body = new Element(), card = new Element(), outside = new Element();
  const runtime = {};
  Object.assign(frame, { localName: 'iframe', offsetWidth: 800, offsetHeight: 600, clientLeft: 2, clientTop: 3, contentWindow: runtime,
    getBoundingClientRect: () => ({ left: 580 * state.zoom + state.pan.x, top: 460 * state.zoom + state.pan.y,
      width: frame.offsetWidth * state.zoom, height: frame.offsetHeight * state.zoom }) });
  body.contains = target => target === frame;
  Object.assign(card, { id: 'terminal-a', _termBrowser: frame, contains: target => target === frame || target === body,
    querySelector: selector => selector === '.egd-card-body' ? body : null });
  const listeners = {}, effects = { animated: 0, applied: 0, exits: 0 };
  const document = { getElementById: id => id === card.id ? card : null,
    addEventListener(type, fn, options) {
      assert.deepEqual(options, { passive: false, capture: true }); listeners[type] = fn;
    } };
  frame.ownerDocument = document;
  frame.contentDocument = { defaultView: { frameElement: frame } };
  const closest = frame.closest;
  frame.closest = selector => selector === '.egd-terminal-card' ? card : closest.call(frame, selector);
  let now = 100;
  const start = surfaceSource.indexOf('    // Global wheel capture:');
  const end = surfaceSource.indexOf('\n    // Canvas zoom uses the same camera', start);
  assert.ok(start > 0 && end > start);
  const source = ['const normalizeWheelDelta', 'const panCanvasByWheel', 'const shouldAllowActiveEntityScroll',
    'const shouldAllowHudScroll', 'const wheelSession', 'const resetWheelSession', 'const resolveWheelSessionOwner',
    'state.nativeGestureHook', 'const zoomCanvasByFactor', 'const zoomCanvasByWheel'].map(binding).join('\n');
  const controls = compileFunction(`let frame = 0;\n${source}\n${surfaceSource.slice(start, end)}\nreturn { wheelSession, resetWheelSession };`,
    ['state', 'document', 'window', 'Element', 'performance', 'WheelEvent', 'WHEEL_PAN_SPEED', 'WHEEL_ZOOM_SPEED',
      'WHEEL_SESSION_IDLE_MS', 'ZOOM_MIN', 'ZOOM_MAX', 'scheduleAnimate', 'apply', 'exitCardFullscreen', 'enterLocalDesk'])(
    state, document, { innerHeight: 900 }, Element, { now: () => now }, { DOM_DELTA_LINE: 1, DOM_DELTA_PAGE: 2 },
    constant('WHEEL_PAN_SPEED'), constant('WHEEL_ZOOM_SPEED'), constant('WHEEL_SESSION_IDLE_MS'), constant('ZOOM_MIN'), constant('ZOOM_MAX'),
    () => { effects.animated++; }, () => { effects.applied++; }, (_card, options) => {
      assert.deepEqual(options, { preserveCamera: true }); state.cardFullscreen = null; effects.exits++;
    }, () => { state.surface.initialBrowserFocus = false; });
  const event = (patch = {}) => ({ target: {}, deltaX: 4, deltaY: 10, deltaMode: 0, clientX: 200, clientY: 120,
    ctrlKey: false, metaKey: false, preventDefault() { this.prevented = true; }, stopPropagation() { this.stopped = true; }, ...patch });
  return { ...controls, state, frame, card, body, outside, effects, listeners, runtime, event,
    advance: ms => { now += ms; }, idleMs: constant('WHEEL_SESSION_IDLE_MS'),
    panSpeed: constant('WHEEL_PAN_SPEED'), zoomSpeed: constant('WHEEL_ZOOM_SPEED'),
    route(ev = event()) {
      assert.equal(typeof state.routeTerminalFrameWheel, 'function', 'the Terminal iframe must use the common wheel router');
      return state.routeTerminalFrameWheel(card, frame, ev);
    } };
}

test('Terminal frame wheel keeps active native scroll and pans inactive hover without activation', () => {
  const h = terminalFrameWheelHarness();
  assert.equal(h.route(), false);
  assert.deepEqual(h.state.panTarget, { x: 50, y: -20 });
  assert.equal(h.effects.animated, 0);
  assert.equal(h.state.activeEntityId, h.card.id);
  for (const activeEntityId of ['browser-b', null]) {
    for (const [deltaMode, unit] of [[0, 1], [1, 16], [2, 900]]) {
      h.resetWheelSession(); h.state.activeEntityId = activeEntityId;
      const before = { ...h.state.panTarget }, ev = h.event({ deltaMode });
      assert.equal(h.route(ev), true);
      assert.deepEqual(h.state.panTarget, { x: before.x - 4 * unit * h.panSpeed, y: before.y - 10 * unit * h.panSpeed });
      assert.equal(h.state.activeEntityId, activeEntityId, 'hover never selects/focuses Terminal');
      assert.equal(ev.prevented, undefined, 'the child listener consumes the original event from the returned boolean');
    }
  }
  assert.equal(h.card._termBrowser, h.frame);
  assert.equal(h.frame.contentWindow, h.runtime);
});

test('Terminal frame wheel maps the rendered iframe anchor through camera scale for common modifier zoom', () => {
  for (const zoom of [.35, .5, 1.7]) {
    const h = terminalFrameWheelHarness();
    h.state.zoom = zoom;
    // While animation is in flight, use the displayed frame rect for the event
    // anchor, but the same target-camera math as an outer-document wheel.
    h.state.zoomTarget = zoom * 1.1;
    h.state.panTarget = { x: 75, y: -40 };
    const ev = h.event({ ctrlKey: true, deltaY: -10 });
    const rect = h.frame.getBoundingClientRect();
    const anchor = { x: rect.left + (ev.clientX + h.frame.clientLeft) * zoom,
      y: rect.top + (ev.clientY + h.frame.clientTop) * zoom };
    const before = { pan: { ...h.state.panTarget }, zoom: h.state.zoomTarget };
    const factor = Math.exp(10 * h.zoomSpeed);
    assert.equal(h.route(ev), true);
    assert.ok(Math.abs(h.state.zoomTarget - before.zoom * factor) < 1e-12);
    for (const axis of ['x', 'y']) {
      const world = (anchor[axis] - before.pan[axis]) / before.zoom;
      assert.ok(Math.abs(world * h.state.zoomTarget + h.state.panTarget[axis] - anchor[axis]) < 1e-9,
        `${axis}: iframe content CSS coordinates must become chrome viewport coordinates`);
    }
    assert.equal(h.state.activeEntityId, h.card.id);
    assert.equal(h.effects.animated, 1);
    assert.equal(h.effects.applied, 0);
  }
  const h = terminalFrameWheelHarness();
  assert.equal(h.route(h.event({ metaKey: true })), true, 'normal Cmd-wheel remains common Canvas pan');
  assert.equal(h.state.zoomTarget, .5);
  assert.deepEqual(h.state.panTarget, { x: 50 - 4 * h.panSpeed, y: -20 - 10 * h.panSpeed });
});

test('Terminal frame wheel preserves Focus on zoom-in and reveals Canvas only on zoom-out', () => {
  for (const modifier of ['ctrlKey', 'metaKey']) {
    const h = terminalFrameWheelHarness();
    h.state.cardFullscreen = { cardId: h.card.id };
    assert.equal(h.route(h.event({ [modifier]: true, deltaY: -10 })), true);
    assert.equal(h.state.cardFullscreen.cardId, h.card.id);
    assert.equal(h.effects.exits, 0);
    assert.equal(h.effects.applied, 1);
    const displayed = { pan: { ...h.state.pan }, zoom: h.state.zoom };
    const ev = h.event({ [modifier]: true, deltaY: 10 });
    const rect = h.frame.getBoundingClientRect();
    const factor = Math.exp(-10 * h.zoomSpeed);
    assert.equal(h.route(ev), true);
    assert.equal(h.state.cardFullscreen, null);
    assert.equal(h.effects.exits, 1);
    assert.equal(h.effects.animated, 1);
    assert.deepEqual(h.state.pan, displayed.pan, 'no saved-camera jump before animation');
    assert.equal(h.state.zoom, displayed.zoom);
    assert.ok(Math.abs(h.state.zoomTarget - displayed.zoom * factor) < 1e-12);
    const anchorX = rect.left + (ev.clientX + h.frame.clientLeft) * displayed.zoom;
    assert.ok(Math.abs(h.state.panTarget.x - (anchorX - (anchorX - displayed.pan.x) * factor)) < 1e-9);
    assert.equal(h.card._termBrowser, h.frame);
    assert.equal(h.frame.contentWindow, h.runtime);
    assert.equal(h.state.activeEntityId, h.card.id);
  }
});

test('Terminal frame wheel shares outer-document gesture ownership and native begin/end boundaries', () => {
  const h = terminalFrameWheelHarness();
  assert.equal(h.route(), false);
  const outsideEvent = h.event({ target: h.outside });
  h.listeners.wheel(outsideEvent);
  assert.equal(outsideEvent.prevented, true);
  assert.equal(outsideEvent.stopped, true);
  assert.equal(h.effects.animated, 0, 'entity-owned gesture cannot become Canvas pan at a frame boundary');
  h.state.activeEntityId = 'browser-b';
  assert.equal(h.route(), true);
  assert.equal(h.effects.animated, 0, 'losing selection does not steal an in-flight entity gesture');
  h.advance(h.idleMs + 1);
  assert.equal(h.route(), true);
  assert.equal(h.effects.animated, 1, 'the next inactive hover gesture pans');

  h.state.nativeGestureHook({ kind: 'gestureScrollBegin' });
  h.listeners.wheel(h.event({ target: h.outside }));
  const before = h.effects.animated;
  h.state.activeEntityId = h.card.id;
  h.advance(h.idleMs * 2);
  assert.equal(h.route(), true, 'Canvas-owned native gesture remains Canvas-owned across the iframe');
  assert.equal(h.effects.animated, before + 1);
  h.state.nativeGestureHook({ kind: 'gestureScrollEnd' });
  assert.equal(h.route(), false, 'the next gesture on active Terminal returns to native scroll');
  const hudEvent = h.event({ target: Object.assign(h.outside, { hud: true }) });
  h.listeners.wheel(hudEvent);
  assert.equal(hudEvent.prevented, undefined);
  assert.equal(h.wheelSession.owner, null, 'HUD retains its existing reset/native policy');
});

test('Terminal frame wheel ignores stale owners and invalid projections without changing the camera', () => {
  const mutations = [h => { h.card.isConnected = false; }, h => { h.frame.isConnected = false; },
    h => { h.card._termBrowser = {}; }, h => { h.card.contains = () => false; },
    h => { h.frame.offsetWidth = 0; }, h => { h.frame.getBoundingClientRect = () => ({ left: NaN, top: 0, width: 100, height: 100 }); }];
  for (const mutate of mutations) {
    const h = terminalFrameWheelHarness(); mutate(h);
    assert.equal(h.route(h.event({ ctrlKey: true })), false);
    assert.deepEqual(h.state.panTarget, { x: 50, y: -20 });
    assert.equal(h.state.zoomTarget, .5);
    assert.equal(h.wheelSession.owner, null);
    assert.equal(h.effects.animated + h.effects.applied, 0);
  }
});

test('Terminal frame wheel chrome capture normalizes a child-realm target and caches the native-scroll result', () => {
  const h = terminalFrameWheelHarness();
  // Gecko chrome capture sees a foreign-document target and frame-local client
  // coordinates BEFORE the Terminal window listener. A foreign realm Element
  // is not an instanceof chrome Element; the owned iframe in the path is.
  class ChildElement { constructor() { this.ownerDocument = h.frame.contentDocument; } }
  const target = new ChildElement();
  const ev = h.event({ target, composedPath: () => [target, h.frame.contentDocument, h.frame, h.body, h.card] });
  h.listeners.wheel(ev);
  assert.equal(ev.prevented, undefined);
  assert.equal(ev.stopped, undefined);
  assert.equal(h.effects.animated, 0);
  assert.equal(h.wheelSession.owner, 'entity', 'parent capture uses the mapped iframe for ownership');
  const routedAt = h.wheelSession.lastTs;
  h.advance(h.idleMs + 1);
  assert.equal(h.route(ev), false);
  assert.equal(h.wheelSession.lastTs, routedAt, 'child hook reuses the same event result without routing again');
  assert.deepEqual(h.state.panTarget, { x: 50, y: -20 });
  assert.equal(h.state.activeEntityId, h.card.id);
});

test('Terminal frame wheel chrome capture does not double-pan or zoom at untranslated child coordinates', () => {
  for (const zoom of [.35, .5, 1.7]) for (const ctrlKey of [false, true]) {
    const h = terminalFrameWheelHarness();
    h.state.activeEntityId = 'browser-b';
    h.state.zoom = h.state.zoomTarget = zoom;
    const target = { ownerDocument: h.frame.contentDocument };
    const ev = h.event({ target, composedPath: () => [target, h.frame.contentDocument, h.frame, h.body, h.card], ctrlKey, deltaY: -18 });
    const rect = h.frame.getBoundingClientRect(), before = { ...h.state.panTarget };
    h.listeners.wheel(ev);
    assert.equal(ev.prevented, true);
    assert.equal(ev.stopped, true, 'parent consumes the Canvas-owned child event before native Terminal scroll');
    assert.equal(h.effects.animated, 1);
    assert.equal(h.route(ev), true);
    assert.equal(h.effects.animated, 1, 'exactly one camera mutation per native event');
    if (ctrlKey) {
      const factor = Math.exp(18 * h.zoomSpeed);
      const anchorX = rect.left + (ev.clientX + h.frame.clientLeft) * zoom;
      const anchorY = rect.top + (ev.clientY + h.frame.clientTop) * zoom;
      assert.ok(Math.abs(h.state.panTarget.x - (anchorX - (anchorX - before.x) * factor)) < 1e-9);
      assert.ok(Math.abs(h.state.panTarget.y - (anchorY - (anchorY - before.y) * factor)) < 1e-9);
    } else {
      assert.deepEqual(h.state.panTarget, { x: before.x - ev.deltaX * h.panSpeed, y: before.y - ev.deltaY * h.panSpeed });
    }
    assert.equal(h.state.activeEntityId, 'browser-b', 'hover routing must not select the Terminal');
  }
  const h = terminalFrameWheelHarness();
  h.card._termBrowser = {}; // Not an owned Terminal iframe: preserve the existing outer policy.
  const ev = h.event({ target: { ownerDocument: h.frame.contentDocument }, composedPath: () => [h.frame] });
  h.listeners.wheel(ev);
  assert.equal(ev.prevented, true); assert.equal(ev.stopped, true);
  assert.equal(h.effects.animated, 1);
});

test('Terminal frame wheel origin checks preserve Browser remote and already-chrome coordinate routes', () => {
  for (const kind of ['different-child-document', 'unowned-frame', 'browser-remote', 'chrome-frame-target']) {
    const h = terminalFrameWheelHarness();
    const ev = h.event({ ctrlKey: true, deltaY: -18, target: { ownerDocument: h.frame.contentDocument },
      composedPath: () => [h.frame] });
    if (kind === 'different-child-document') ev.target.ownerDocument = {};
    if (kind === 'unowned-frame') h.card._termBrowser = {};
    if (kind === 'browser-remote') h.frame.localName = 'browser';
    if (kind === 'chrome-frame-target') ev.target = h.frame;
    h.state.routeTerminalFrameWheel = () => assert.fail(`${kind}: must not enter the Terminal child-coordinate route`);
    h.listeners.wheel(ev);
    const factor = Math.exp(18 * h.zoomSpeed);
    assert.equal(ev.prevented, true); assert.equal(ev.stopped, true);
    assert.ok(Math.abs(h.state.panTarget.x - (ev.clientX - (ev.clientX - 50) * factor)) < 1e-9);
    assert.ok(Math.abs(h.state.panTarget.y - (ev.clientY - (ev.clientY + 20) * factor)) < 1e-9);
    assert.equal(h.effects.animated, 1);
  }
});

test('Focus wheel routing consumes directional camera zoom but leaves active body scroll native', () => {
  const start = surfaceSource.indexOf('    // Global wheel capture:');
  const end = surfaceSource.indexOf('\n    }, { passive: false, capture: true });', start);
  assert.ok(start > 0 && end > start);
  const listeners = {}, wheelSession = { owner: null, nativeActive: false, lastTs: 0 };
  class Element { closest() { return null; } }
  const state = { cardFullscreen: { cardId: 'browser-a' }, activeEntityId: 'browser-a' };
  const factors = []; let pan = 0;
  const source = surfaceSource.slice(start, end + '\n    }, { passive: false, capture: true });'.length);
  compileFunction(source, ['document', 'state', 'Element', 'performance', 'wheelSession', 'WHEEL_SESSION_IDLE_MS',
    'resolveWheelSessionOwner', 'zoomCanvasByWheel', 'panCanvasByWheel', 'shouldAllowHudScroll', 'resetWheelSession', 'shouldAllowActiveEntityScroll'])(
    { addEventListener(type, fn, options) { assert.equal(options.capture, true); assert.equal(options.passive, false); listeners[type] = fn; } },
    state, Element, { now: () => 100 }, wheelSession, 250,
    () => { wheelSession.owner = 'entity'; wheelSession.entityId = 'browser-a'; },
    ev => factors.push(ev.deltaY), () => { pan++; }, () => false, () => {}, () => true);
  for (const deltaY of [-10, 10]) {
    const event = { target: new Element(), ctrlKey: true, deltaY,
      preventDefault() { this.prevented = true; }, stopPropagation() { this.stopped = true; } };
    listeners.wheel(event);
    assert.equal(event.prevented, true, 'pinch/ctrl-wheel cannot leak to Browser page zoom');
    assert.equal(event.stopped, true);
  }
  assert.deepEqual(factors, [-10, 10]);
  wheelSession.owner = 'entity'; wheelSession.entityId = 'browser-a';
  const scroll = { target: new Element(), deltaY: 20,
    preventDefault() { assert.fail('normal active body scroll stays native'); }, stopPropagation() { assert.fail('normal scroll'); } };
  listeners.wheel(scroll);
  assert.equal(pan, 0);
});

test('ordinary Browser maximize changes only the camera and keeps Desk chrome, and explicit restore restores the camera', () => {
  const h = createFullscreenHarness();
  h.enter(h.browser);
  assert.equal(h.state.cardFullscreen.cardId, h.browser.id);
  assert.equal(h.state.cardFullscreen.mode, 'maximized', 'a Browser is maximized like every other View type');
  assert.equal(h.state.cardFullscreen.hudMode, 'hidden');
  assert.deepEqual(h.safeCalls.at(-1), { avoidHud: false, margin: 10 });
  assert.deepEqual(h.browser.style, { ...h.browserRect, zIndex: '40001' });
  assert.equal(h.state.zoom, 754 / 620);
  assert.ok(!h.rootClasses.has('egd-browser-fullscreen-active'), 'the top bar and Dock stay while maximized');
  assert.ok(!h.rootClasses.has('egd-card-focus-active'));
  assert.ok(h.rootClasses.has('egd-card-fullscreen-active'));
  assert.ok(h.hudClasses.has('egd-hud-hidden'));
  assert.equal(h.minimapOpen, false);
  assert.equal(h.exit(h.browser), true);
  assert.deepEqual(h.browser.style, h.browserRect);
  assert.equal(h.state.zoom, 2);
  assert.deepEqual(h.state.pan, { x: 100, y: 50 });
  assert.ok(!h.rootClasses.has('egd-browser-fullscreen-active'));
  assert.ok(!h.rootClasses.has('egd-card-fullscreen-active'));
  assert.ok(!h.hudClasses.has('egd-hud-hidden'));
  assert.equal(h.minimapOpen, true);
  assert.equal(h.hudFitCount, 1);

  const previouslyHidden = createFullscreenHarness({ hudInitiallyHidden: true, minimapInitiallyOpen: false });
  previouslyHidden.enter(previouslyHidden.browser);
  previouslyHidden.exit(previouslyHidden.browser);
  assert.ok(previouslyHidden.hudClasses.has('egd-hud-hidden'));
  assert.equal(previouslyHidden.minimapOpen, false);
});

test('focus view is a separate user choice for any View type: edge to edge, Desk chrome hidden, cleared on restore', () => {
  for (const kind of ['browser', 'chat']) {
    const h = createFullscreenHarness();
    const card = h[kind];
    h.state.cardFocusIntent = card.id;
    h.enter(card);
    assert.equal(h.state.cardFullscreen.mode, 'focus');
    assert.equal(h.state.cardFocusIntent, null, 'the intent is spent by one entry');
    assert.deepEqual(h.safeCalls.at(-1), { avoidHud: false, margin: 0 });
    assert.ok(h.rootClasses.has('egd-card-focus-active'));
    assert.equal(h.rootClasses.has('egd-browser-fullscreen-active'), kind === 'browser', 'only a Browser goes Chrome-like');
    assert.deepEqual(card.style, { ...h[`${kind}Rect`], zIndex: '40001' }, 'focus view is still only a camera pose');
    assert.equal(h.exit(card), true);
    assert.deepEqual(card.style, h[`${kind}Rect`]);
    assert.deepEqual(h.state.pan, { x: 100, y: 50 });
    for (const name of ['egd-card-focus-active', 'egd-browser-fullscreen-active', 'egd-card-fullscreen-active']) assert.ok(!h.rootClasses.has(name));
    h.enter(card);
    assert.equal(h.state.cardFullscreen.mode, 'maximized', 'the next plain maximize is not a focus view');
  }
});

test('while maximized only a pinned Chat refits the View, and a Chat the user opened survives restore', () => {
  const h = createFullscreenHarness({ hudInitiallyHidden: true, minimapInitiallyOpen: true });
  h.enter(h.chat);
  h.state.cardFullscreen.hudMode = 'peek';
  h.layout({ reframe: true });
  assert.deepEqual(h.safeCalls.at(-1), { avoidHud: false, margin: 10 }, 'a peek overlays the View without resizing it');
  h.state.cardFullscreen.hudMode = 'pinned';
  h.rootClasses.add('egd-maximize-hud-pinned');
  h.layout({ reframe: true });
  assert.deepEqual(h.safeCalls.at(-1), { avoidHud: true, margin: 10 });
  assert.deepEqual(h.state.cardFullscreen.rect, h.chatRect, 'restoreRect is unchanged by pinning');
  h.state.cardFullscreen.hudKeptOnRestore = true;
  h.minimapOpen = true; // the user reopened the minimap while maximized
  assert.equal(h.exit(h.chat), true);
  assert.ok(!h.hudClasses.has('egd-hud-hidden'), 'Chat stays open although it was closed before maximizing');
  assert.ok(!h.rootClasses.has('egd-maximize-hud-pinned'));
  assert.equal(h.minimapOpen, true, 'restore does not toggle an already open minimap shut');
  assert.deepEqual(h.chat.style, h.chatRect);
});

test('a Chat that was only peeked at while maximized is closed, not left open-but-hidden, on restore', () => {
  const peeked = createFullscreenHarness({ hudInitiallyHidden: true });
  peeked.enter(peeked.chat);
  peeked.state.hudOpen = true; // the right-edge peek mounted Chat, then the pointer left
  peeked.state.cardFullscreen.hudMode = 'hidden';
  assert.equal(peeked.exit(peeked.chat), true);
  assert.deepEqual(peeked.hudCloses, [null], 'the hidden Chat is closed through the ordinary close path');
  assert.equal(peeked.state.hudOpen, false);
  assert.ok(peeked.hudClasses.has('egd-hud-hidden'));

  const openBefore = createFullscreenHarness({ hudInitiallyHidden: false });
  openBefore.state.hudOpen = true;
  openBefore.enter(openBefore.chat);
  assert.ok(openBefore.hudClasses.has('egd-hud-hidden'));
  assert.equal(openBefore.exit(openBefore.chat), true);
  assert.deepEqual(openBefore.hudCloses, [], 'a Chat that was open before maximizing is shown again, never closed');
  assert.ok(!openBefore.hudClasses.has('egd-hud-hidden'));
  assert.equal(openBefore.state.hudOpen, true);
});

test('switching from Browser to non-Browser fullscreen clears Browser chrome mode and preserves restoration', () => {
  const h = createFullscreenHarness();
  h.enter(h.browser);
  h.enter(h.chat);
  assert.equal(h.state.cardFullscreen.cardId, h.chat.id);
  assert.deepEqual(h.browser.style, h.browserRect);
  assert.ok(!h.browser.classList.contains('egd-card-fullscreen'));
  assert.ok(!h.rootClasses.has('egd-browser-fullscreen-active'));
  assert.ok(h.rootClasses.has('egd-card-fullscreen-active'));
  assert.deepEqual(h.safeCalls.at(-1), { avoidHud: false, margin: 10 });
  assert.deepEqual(h.chat.style, { ...h.chatRect, zIndex: '40002' });
  assert.ok(h.hudClasses.has('egd-hud-hidden'));
  assert.equal(h.minimapOpen, false);
  assert.equal(h.exit(h.chat), true);
  assert.deepEqual(h.chat.style, h.chatRect);
  assert.ok(!h.hudClasses.has('egd-hud-hidden'));
  assert.equal(h.minimapOpen, true);
});

test('closing a fullscreen Browser clears presentation state without restoring a Card about to be removed', () => {
  const h = createFullscreenHarness();
  h.enter(h.browser);
  const body = surfaceSource.match(/  function closeCanvasCard\(card, cleanup\) \{([\s\S]*?)\n  \}/)?.[1];
  assert.ok(body);
  const close = compileFunction(`return function closeCanvasCard(card, cleanup) {${body}\n  }`,
    ['isCardFullscreen', 'exitCardFullscreen', 'unregisterSourceRefCard', 'state', 'setActiveEntity', 'syncOntologyPresentationState', 'markAgendaDirty', 'boardNotice', 'console', 'TAG'])(
    h.isFullscreen, h.exit, () => {}, h.state, card => { h.state.activeEntityId = card?.id || null; }, () => {}, () => {}, () => {}, { warn() {} }, 'test');
  let cleaned = 0;
  h.browser._cleanup = () => { cleaned++; };
  assert.equal(close(h.browser), true);
  assert.equal(cleaned, 1);
  assert.equal(h.browser.isConnected, false);
  assert.equal(h.state.cardFullscreen, null);
  assert.equal(h.state.activeEntityId, null);
  assert.ok(!h.rootClasses.has('egd-browser-fullscreen-active'));
  assert.ok(!h.rootClasses.has('egd-card-fullscreen-active'));
  assert.ok(!h.hudClasses.has('egd-hud-hidden'));
  assert.equal(h.minimapOpen, true);
  assert.equal(h.browser.style.width, '900px', 'close must not rewrite geometry before removal');
});

test('missing fullscreen Browser removes both root presentation classes on layout sync', () => {
  const h = createFullscreenHarness();
  h.state.surface.initialBrowserFocus = true;
  h.rootClasses.add('egd-initial-browser-focus');
  h.enter(h.browser);
  h.browser.remove();
  h.layout();
  assert.equal(h.state.cardFullscreen, null);
  assert.equal(h.state.surface.initialBrowserFocus, false);
  assert.ok(!h.rootClasses.has('egd-initial-browser-focus'));
  assert.ok(!h.rootClasses.has('egd-card-fullscreen-active'));
  assert.ok(!h.rootClasses.has('egd-browser-fullscreen-active'));
});

test('Browser fullscreen CSS hides Desk chrome and removes outer Card decoration', () => {
  const css = readFileSync(new URL('../overlay/CSS/eg-desk-surface.uc.css', import.meta.url), 'utf8');
  const hidden = css.match(/:root\.egd-browser-fullscreen-active #egd-desk-rail,([\s\S]*?)\{([^}]+)\}/);
  assert.ok(hidden);
  for (const id of ['egd-dock', 'egd-preset-bag', 'egd-hud', 'egd-zoom-indicator', 'egd-desk-minimap']) {
    assert.match(hidden[1], new RegExp(`#${id}\\b`));
  }
  assert.match(hidden[2], /display:\s*none\s*!important/);
  const card = css.match(/:root\.egd-browser-fullscreen-active \.egd-browser-card\.egd-card-fullscreen \{([^}]+)\}/)?.[1];
  assert.ok(card);
  for (const declaration of [/border:\s*0/, /border-radius:\s*0/, /box-shadow:\s*none/]) assert.match(card, declaration);
  assert.match(css, /:root\.egd-browser-fullscreen-active \.egd-browser-card\.egd-card-fullscreen \.egd-card-header \{\s*border-radius:\s*0/);
});

