test('right Chat HUD leaves the existing bottom Dock controls hit-test clear at 1280×776', () => {
  const css = readFileSync(new URL('../overlay/CSS/eg-desk-surface.uc.css', import.meta.url), 'utf8');
  const rule = selector => css.match(new RegExp(`^${selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')} \\{([^}]+)\\}`, 'm'))?.[1] || '';
  const hud = rule('#egd-hud');
  const dock = rule('#egd-dock');
  const px = (body, property) => Number.parseFloat(body.match(new RegExp(`${property}:\\s*(\\d+)px`))?.[1]);
  const hudCut = Number.parseFloat(hud.match(/height:\s*calc\(100vh - (\d+)px\)/)?.[1]);
  const viewportHeight = 776;
  const hudBottom = px(hud, 'top') + Math.min(px(hud, 'max-height'), viewportHeight - hudCut);
  const dockTop = viewportHeight - px(dock, 'bottom') - px(dock, 'height');
  assert.ok(Number.isFinite(hudBottom) && Number.isFinite(dockTop));
  assert.ok(hudBottom <= dockTop - 8, `HUD bottom ${hudBottom} must clear Dock top ${dockTop}`);
});

test('zoom actions clear the 18-button Dock at 800×600 and 960×700 without moving the 1280×776 chrome', () => {
  const css = readFileSync(new URL('../overlay/CSS/eg-desk-surface.uc.css', import.meta.url), 'utf8');
  const baseZoom = css.match(/^#egd-zoom-indicator \{([^}]+)\}/m)?.[1] || '';
  const narrowZoom = css.match(/@media \(max-width: 1080px\) \{\s*#egd-zoom-indicator \{([^}]+)\}/)?.[1] || '';
  const dock = css.match(/^#egd-dock \{([^}]+)\}/m)?.[1] || '';
  const bag = css.match(/^#egd-preset-bag \{([^}]+)\}/m)?.[1] || '';
  const px = (body, property) => Number.parseFloat(body.match(new RegExp(`\\b${property}:\\s*(\\d+)px`))?.[1]);
  const measuredZoom = { width: 152, height: 41 }; // central QA 800×600 box
  // Central QA measured 598px for 15 buttons; the arrow, label and highlight
  // tools add 3 × (32px + 6px gap). Content width stays fixed above 700px.
  const measuredDockWidth = 598 + 3 * (32 + 6);
  const zoomRect = (width, height) => {
    const responsive = width <= 1080 ? narrowZoom : '';
    const left = px(responsive, 'left') || px(baseZoom, 'left');
    const bottomInset = px(responsive, 'bottom') || px(baseZoom, 'bottom');
    return { left, right: left + measuredZoom.width,
      top: height - bottomInset - measuredZoom.height, bottom: height - bottomInset };
  };
  const dockRect = (width, height) => {
    const left = (width - measuredDockWidth) / 2;
    const bottom = height - px(dock, 'bottom');
    return { left, right: left + measuredDockWidth,
      top: bottom - px(dock, 'height'), bottom };
  };
  const overlaps = (a, b) => a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;
  const smallZoom = zoomRect(800, 600);
  const smallDock = dockRect(800, 600);
  assert.ok(!overlaps(smallZoom, smallDock),
    `zoom ${JSON.stringify(smallZoom)} must not cover Dock ${JSON.stringify(smallDock)}`);
  assert.ok(smallZoom.bottom <= smallDock.top - 8, 'place the whole zoom group above the Dock');
  assert.ok(smallZoom.left >= px(bag, 'left') + px(bag, 'width') + 8,
    'the moved zoom group also clears the preset rail at the left edge');
  assert.ok(smallZoom.right <= 800 - 10 - 396 - 8,
    'the moved zoom group remains left of the right HUD');
  assert.deepEqual(zoomRect(960, 700), { left: 88, right: 240, top: 591, bottom: 632 },
    'at 960px the full Dock would reach the corner group, so zoom sits above the Dock');
  assert.ok(zoomRect(960, 700).bottom <= dockRect(960, 700).top - 8);
  assert.deepEqual(zoomRect(1280, 776), { left: 15, right: 167, top: 721, bottom: 762 });
  assert.ok(!overlaps(zoomRect(960, 700), dockRect(960, 700)));
  assert.ok(!overlaps(zoomRect(1280, 776), dockRect(1280, 776)));
  assert.ok(dockRect(1081, 700).left >= zoomRect(1081, 700).right + 8,
    'just above the breakpoint the corner group keeps 8px clear of the Dock');
  assert.doesNotMatch(narrowZoom, /(?:z-index|pointer-events|display|transform|width|height):/,
    'the responsive rule only repositions the existing clickable zoom controls');
  assert.match(surfaceSource, /zoomOutButton\.addEventListener\('click'/);
  assert.match(surfaceSource, /zoomInButton\.addEventListener\('click'/);
  assert.match(surfaceSource, /zoomFitButton\.addEventListener\('click'/);
  assert.match(surfaceSource, /dock\.appendChild\(makeGroup\(DOCK_RIGHT, 'right'\)\)/);
});

test('600×600 narrow HUD clears every zoom hit point and the Dock while larger HUDs stay put', () => {
  const css = readFileSync(new URL('../overlay/CSS/eg-desk-surface.uc.css', import.meta.url), 'utf8');
  const baseHud = css.match(/^#egd-hud \{([^}]+)\}/m)?.[1] || '';
  const narrowHud = css.match(/@media \(max-width: 700px\) \{\s*#egd-hud \{([^}]+)\}/)?.[1] || '';
  const baseZoom = css.match(/^#egd-zoom-indicator \{([^}]+)\}/m)?.[1] || '';
  const narrowZoom = css.match(/@media \(max-width: 1080px\) \{\s*#egd-zoom-indicator \{([^}]+)\}/)?.[1] || '';
  const dock = css.match(/^#egd-dock \{([^}]+)\}/m)?.[1] || '';
  const px = (body, property) => Number.parseFloat(body.match(new RegExp(`\\b${property}:\\s*(\\d+)px`))?.[1]);
  const heightCut = body => Number.parseFloat(body.match(/height:\s*calc\(100vh - (\d+)px\)/)?.[1]);
  const hudRect = (width, height) => {
    const body = width <= 700 && narrowHud ? narrowHud : baseHud;
    const top = px(baseHud, 'top');
    const right = width - px(baseHud, 'right');
    const panelWidth = Math.min(396, width - 20);
    const bottom = top + Math.min(px(baseHud, 'max-height'), height - heightCut(body));
    return { left: right - panelWidth, right, top, bottom };
  };
  const zoomRect = (width, height) => {
    const body = width <= 1080 && narrowZoom ? narrowZoom : baseZoom;
    const left = px(body, 'left');
    const bottom = height - px(body, 'bottom');
    return { left, right: left + 152, top: bottom - 41, bottom };
  };
  const contains = (rect, x, y) => x >= rect.left && x < rect.right && y >= rect.top && y < rect.bottom;
  const hud = hudRect(600, 600), zoom = zoomRect(600, 600);
  const dockTop = 600 - px(dock, 'bottom') - px(dock, 'height');
  for (const x of [zoom.left + 8, zoom.left + 76, zoom.right - 8]) {
    const y = (zoom.top + zoom.bottom) / 2;
    assert.ok(!contains(hud, x, y), `HUD must not intercept zoom hit point (${x}, ${y})`);
    assert.ok(y < dockTop, `Dock must not intercept zoom hit point (${x}, ${y})`);
  }
  assert.ok(hud.bottom <= zoom.top - 8, 'the narrow HUD leaves an 8px clearance above the zoom group');
  assert.ok(zoom.top - hud.bottom <= 12, 'the clearance does not needlessly shrink the Chat HUD');
  assert.ok(zoom.bottom <= dockTop - 8, 'the zoom group remains clear above the Dock');
  assert.ok(dockTop - hud.bottom >= 8, 'the narrow HUD also clears the Dock');
  assert.deepEqual(hudRect(800, 600), { left: 394, right: 790, top: 72, bottom: 532 });
  assert.deepEqual(hudRect(960, 700), { left: 554, right: 950, top: 72, bottom: 632 });
  assert.deepEqual(hudRect(1280, 776), { left: 874, right: 1270, top: 72, bottom: 708 });
  assert.doesNotMatch(narrowHud, /(?:display|visibility|pointer-events|z-index|width|transform):/,
    'the narrow rule changes only HUD clearance, not its actions or horizontal topology');
});

test('wheel or focused-URL keyboard zoom-out reveals the same live Browser Card without geometry restoration', () => {
  const exitBody = surfaceSource.match(/  function exitCardFullscreen\(card = null, options = \{\}\) \{([\s\S]*?)\n  \}/)?.[1];
  const enterBody = surfaceSource.match(/  function enterLocalDesk\(\) \{([\s\S]*?)\n  \}/)?.[1];
  const factorBody = surfaceSource.match(/    const zoomCanvasByFactor = \(factor, cx, cy\) => \{([\s\S]*?)\n    \};\n    const zoomCanvasByWheel/)?.[1];
  const wheelBody = surfaceSource.match(/    const zoomCanvasByWheel = \(ev\) => \{([\s\S]*?)\n    \};\n\n    const zoomAtSafeCenter/)?.[1];
  const keyBody = surfaceSource.match(/    const handleCanvasZoomKeydown = \(ev\) => \{([\s\S]*?)\n    \};\n    \/\/ 리셋/)?.[1];
  assert.ok(exitBody && enterBody && factorBody && wheelBody && keyBody);
  assert.match(surfaceSource, /window\.addEventListener\('keydown', handleCanvasZoomKeydown, true\)/);
  const exit = compileFunction(`return function exitCardFullscreen(card = null, options = {}) {${exitBody}\n  }`,
    ['state', 'document', 'applyCardRect', 'restoreHudAfterCardFullscreen', 'toggleDeskMinimap', 'setActiveEntity', 'syncViewportAgendaRail', 'scheduleDeskSessionSave']);
  const enter = compileFunction(`return function enterLocalDesk() {${enterBody}\n  }`,
    ['state', 'exitCardFullscreen', 'document', 'scheduleDeskSessionSave']);
  const zoomFactor = compileFunction(`return function zoomCanvasByFactor(factor, cx, cy) {${factorBody}\n    }`,
    ['state', 'ZOOM_MIN', 'ZOOM_MAX', 'enterLocalDesk', 'frame', 'window', 'apply', 'scheduleAnimate', 'safeViewportRect', 'exitCardFullscreen']);
  const zoom = compileFunction(`return function zoomCanvasByWheel(ev) {${wheelBody}\n    }`,
    ['normalizeWheelDelta', 'zoomCanvasByFactor', 'WHEEL_ZOOM_SPEED']);
  const keydown = compileFunction(`return function handleCanvasZoomKeydown(ev) {${keyBody}\n    }`,
    ['state', 'syncPanModeCursor', 'zoomCanvasByFactor', 'window', 'scheduleAnimate', 'ViewportExtras']);
  const nativeBrowser = { uri: 'https://example.test/page', session: {} };
  const rect = { left: '45px', top: '60px', width: '900px', height: '620px', zIndex: '41000' };
  const browser = { id: 'browser-view-a', isConnected: true, _xulBrowser: nativeBrowser,
    style: { ...rect, zIndex: '42000' },
    classList: { remove: name => { assert.equal(name, 'egd-card-fullscreen'); } } };
  const classes = new Set(['egd-initial-browser-focus', 'egd-card-fullscreen-active']);
  const document = { documentElement: { classList: { remove: name => classes.delete(name) } },
    getElementById: id => id === browser.id ? browser : null };
  const state = { surface: { browserCardId: browser.id, initialBrowserFocus: true },
    cardFullscreen: { cardId: browser.id, rect, previousHudHidden: false, previousMinimapOpen: false },
    pan: { x: 0, y: 0 }, panTarget: { x: 0, y: 0 }, zoom: 1, zoomTarget: 1 };
  let saved = 0, activated = null, animated = 0;
  const exitFullscreen = exit(state, document, (card, prior) => Object.assign(card.style, prior),
    () => {}, () => assert.fail('closed minimap should stay closed'), card => { activated = card; },
    () => {}, () => { saved++; });
  const enterDesk = enter(state, exitFullscreen, document, () => { saved++; });
  const applyFactor = zoomFactor(state, .01, 4, enterDesk, 0,
    { cancelAnimationFrame() {} }, () => {}, () => { animated++; },
    () => ({ left: 0, top: 0, width: 1600, height: 960 }), exitFullscreen);
  const zoomOut = zoom(() => 1, applyFactor, .0044);
  zoomOut({ deltaY: 100, clientX: 800, clientY: 480 });
  assert.equal(state.surface.initialBrowserFocus, false);
  assert.equal(state.cardFullscreen, null);
  assert.deepEqual(browser.style, rect);
  assert.equal(browser._xulBrowser, nativeBrowser);
  assert.equal(activated, browser);
  assert.ok(!classes.has('egd-initial-browser-focus'));
  assert.ok(!classes.has('egd-card-fullscreen-active'));
  assert.ok(state.zoomTarget < 1);
  assert.equal(animated, 1);
  assert.equal(saved, 1);
  assert.equal(enterDesk(), false, 'returning to Desk a second time must not refocus Browser');

  // At the zoom clamp, the outward gesture still exits Browser focus.
  state.surface.initialBrowserFocus = true;
  state.cardFullscreen = { cardId: browser.id, rect, previousHudHidden: false, previousMinimapOpen: false };
  state.zoom = state.zoomTarget = .01;
  classes.add('egd-initial-browser-focus');
  classes.add('egd-card-fullscreen-active');
  zoomOut({ deltaY: 100, clientX: 800, clientY: 480 });
  assert.equal(state.surface.initialBrowserFocus, false);
  assert.equal(state.cardFullscreen, null);
  assert.equal(saved, 2);
  assert.equal(animated, 1, 'clamped zoom does not schedule a redundant animation');

  // Invoke the production key handler directly with a focused URL input.
  // This tests the handler, not native OS key delivery or a synthetic DOM event.
  state.surface.initialBrowserFocus = true;
  state.cardFullscreen = { cardId: browser.id, rect, previousHudHidden: false, previousMinimapOpen: false };
  state.zoom = state.zoomTarget = 1;
  state.pan = { x: 0, y: 0 };
  state.panTarget = { x: 0, y: 0 };
  Object.assign(browser.style, { ...rect, zIndex: '42000' });
  classes.add('egd-initial-browser-focus');
  classes.add('egd-card-fullscreen-active');
  const handleKey = keydown(state, () => {}, applyFactor, { innerWidth: 1600, innerHeight: 960 }, () => { animated++; }, { ZOOM_STEP: 1.25 });
  let prevented = 0, stopped = 0;
  const urlKey = { target: { className: 'egd-card-url' }, key: '-', code: 'Minus', ctrlKey: true,
    metaKey: false, altKey: false, isComposing: false, keyCode: 189,
    preventDefault: () => { prevented++; }, stopImmediatePropagation: () => { stopped++; } };
  handleKey({ ...urlKey, ctrlKey: false });
  handleKey({ ...urlKey, isComposing: true });
  assert.equal(state.surface.initialBrowserFocus, true, 'plain typing and IME must not zoom the Desk');
  assert.equal(prevented, 0);
  handleKey(urlKey);
  assert.equal(prevented, 1);
  assert.equal(stopped, 1);
  assert.equal(state.surface.initialBrowserFocus, false);
  assert.equal(state.cardFullscreen, null);
  assert.deepEqual(browser.style, rect);
  assert.equal(browser._xulBrowser, nativeBrowser);
  assert.ok(state.zoomTarget < 1);
  assert.equal(saved, 3);
  assert.equal(animated, 2);
  const zoomedOut = state.zoomTarget;
  handleKey({ ...urlKey, key: '+', code: 'Equal', ctrlKey: false, metaKey: true, shiftKey: true });
  assert.ok(state.zoomTarget > zoomedOut, '⌘+plus uses the same Desk camera');
  assert.equal(browser._xulBrowser, nativeBrowser);
  assert.equal(prevented, 2);
  assert.equal(stopped, 2);
});

