  const body = surfaceSource.match(/else shell\.slots\.content\.appendChild\(el\('button', \{ 'aria-label': '저장된 당시 입력 불러오기', onclick: async \(\) => \{([\s\S]*?)\n    \} \}, '당시 입력 불러오기'\)\);/)?.[1];
