test('Agent 관리 drives the profile routes with revision checks, conflict reload and delete confirmation', () => {
  for (const route of ["'/profiles'", "'/draft'", "'/activate'", "'/lifecycle'", "'/revisions'", "'/diff'", '`/revisions/${revision}`']) {
    assert.ok(settingsSource.includes(route), `route ${route}`);
  }
  assert.match(settingsSource, /method: 'PUT', body: \{ body: checked\.body, expectedRevision: agents\.baseRevision \}/);
  assert.match(settingsSource, /body: \{ revision: detail\.headRevision, expectedActiveRevision: detail\.activeRevision \?\? null \}/);
  assert.match(settingsSource, /error\?\.code === 'PROFILE_REVISION_CONFLICT'[\s\S]*agents\.notice = ChatState\.PROFILE_CONFLICT_TEXT/);
  assert.match(settingsSource, /action === 'delete' && !window\.confirm\(/);
  // Going back to an old version writes its body as a new draft; activate is not used for it.
  const revert = settingsSource.match(/const revertTo = async \(detail, revision\) => \{([\s\S]*?)\n    \};/)?.[1] || '';
  assert.match(revert, /`\/revisions\/\$\{revision\}`[\s\S]*'\/draft'[\s\S]*body: \{ body: old\.body, expectedRevision: detail\.headRevision \}/);
  assert.doesNotMatch(revert, /\/activate/);
  assert.equal(Chat.PROFILE_CONFLICT_TEXT, '다른 곳에서 바뀌었습니다. 최신 내용을 불러왔습니다.');
  assert.equal(Chat.profileRequestErrorText({ status: 409, code: 'PROFILE_REVISION_CONFLICT' }), Chat.PROFILE_CONFLICT_TEXT);
  for (const error of [{ status: 503, code: 'PROFILE_STORE_UNAVAILABLE' }, { status: 404, code: 'PROFILE_ROUTE_NOT_FOUND' }, new TypeError('NetworkError')]) {
    assert.match(Chat.profileRequestErrorText(error), /Agent 저장소에 연결하지 못했습니다/);
  }
  assert.doesNotMatch(Chat.profileRequestErrorText({ status: 400, code: 'INVALID_PROFILE', message: 'name must be 1–40 characters' }), /[A-Za-z]{4,}/,
    'server English stays internal');
});

test('the Agent form needs a name, keeps the approved six colors and the store limits, and saves the store body shape', () => {
  assert.deepEqual(Chat.PROFILE_AVATAR_PALETTE, AVATAR_PALETTE);
  assert.deepEqual(Chat.PROFILE_TONE_OPTIONS.map(option => option.value), PROFILE_TONES);
  assert.deepEqual(Chat.PROFILE_TONE_OPTIONS.map(option => option.label), ['담백', '따뜻', '간결', '격식', '유쾌']);
  const empty = Chat.validateProfileForm(Chat.profileFormFromBody(null));
  assert.equal(empty.ok, false);
  assert.deepEqual(empty.errors, [{ field: 'name', message: '담당자 이름을 입력해 주세요.' }]);
  const base = { ...Chat.profileFormFromBody(null), name: '자료 정리 담당' };
  const reject = (patch, field) => {
    const result = Chat.validateProfileForm({ ...base, ...patch });
    assert.equal(result.ok, false, JSON.stringify(patch).slice(0, 80));
    assert.ok(result.errors.some(error => error.field === field && /[가-힣]/.test(error.message)), `${field} error for ${JSON.stringify(patch).slice(0, 60)}`);
    assert.equal(result.body, null);
  };
  reject({ name: '   ' }, 'name');
  reject({ name: '가'.repeat(41) }, 'name');
  reject({ avatarColor: '#ff0000' }, 'avatarColor');
  reject({ avatarColor: '#49634F'.replace('4', '5') }, 'avatarColor');
  reject({ avatarKind: 'emoji', avatarValue: '🙂🙂' }, 'avatar');
  reject({ avatarKind: 'initial', avatarValue: 'ABC' }, 'avatar');
  reject({ role: 'x'.repeat(81) }, 'role');
  reject({ tone: 'angry' }, 'tone');
  reject({ traits: ['a', 'b', 'c', 'd', 'e', 'f', 'g'] }, 'traits');
  reject({ traits: ['t'.repeat(41)] }, 'traits');
  reject({ speechNotes: 's'.repeat(501) }, 'speechNotes');
  reject({ expertise: Array.from({ length: 9 }, (_, i) => `일 ${i}`) }, 'expertise');
  reject({ expertise: ['e'.repeat(81)] }, 'expertise');
  reject({ instructions: 'i'.repeat(8001) }, 'instructions');
  reject({ toolPreferences: ['browser tool'] }, 'toolPreferences');
  reject({ toolPreferences: Array.from({ length: 21 }, (_, i) => `tool_${i}`) }, 'toolPreferences');
  // Exactly at every limit is accepted, with the store's own normalization.
  const full = Chat.validateProfileForm({ ...base, name: '가'.repeat(40), avatarKind: 'emoji', avatarValue: '🦉', avatarColor: '#F5F0DF',
    role: 'r'.repeat(80), tone: 'formal', traits: ['꼼꼼함', '꼼꼼함', ...Array.from({ length: 5 }, (_, i) => `특징${i}`)], speechNotes: 's'.repeat(500),
    expertise: Array.from({ length: 8 }, (_, i) => `맡길 일 ${i}`), instructions: 'line one\r\nline two', toolPreferences: ['browser', 'egdesk_browser_observe'] });
  assert.equal(full.ok, true, JSON.stringify(full.errors));
  assert.deepEqual(Object.keys(full.body), ['name', 'avatar', 'role', 'personality', 'expertise', 'instructions', 'toolPreferences', 'model', 'toolCeiling']);
  const { toolCeiling: noCeiling, ...storedFields } = full.body;
  assert.equal(noCeiling, null, 'the tool switch starts off: no ceiling, today\'s behavior');
  assert.deepEqual(storedFields, normalizeProfileBody(full.body), 'the bridge stores exactly what the form sends (a null ceiling leaves no key)');
  assert.equal(full.body.avatar.color, '#f5f0df');
  assert.equal(full.body.personality.traits.length, 6, 'duplicates collapse like the store');
  // A blank avatar becomes the name's first letter on the chosen tone.
  const initial = Chat.validateProfileForm({ ...base, name: 'kim', avatarValue: '', avatarColor: '#958879' });
  assert.deepEqual(initial.body.avatar, { kind: 'initial', value: 'K', color: '#958879' });
  // Editing a saved body round-trips without loss, including the unedited model.
  const saved = normalizeProfileBody({ name: '검증 담당', avatar: { kind: 'initial', value: 'V', color: '#252a26' }, role: '검토',
    personality: { tone: 'concise', traits: ['정확함'], speechNotes: '짧게' }, expertise: ['리뷰'], instructions: '근거를 먼저', toolPreferences: ['browser'],
    model: { engine: 'codex', modelId: 'gpt-5.5', effort: 'high' } });
  assert.deepEqual(Chat.validateProfileForm(Chat.profileFormFromBody(saved)).body, { ...saved, toolCeiling: null });
});

function personalityPreservationBody(personality = {
  examples: [{ user: '검토해 주세요', reply: '근거부터 확인하겠습니다.\n불확실한 내용은 구분하겠습니다.' }],
  avoid: ['확인 없이 단정하기', '원본 덮어쓰기'],
}) {
  return normalizeProfileBody({ name: '보존 검증', avatar: { kind: 'initial', value: 'V', color: '#252a26' }, role: '기존 역할',
    personality: { tone: 'concise', traits: ['정확함'], speechNotes: '짧게', ...personality },
    expertise: ['검토'], instructions: '원본을 보존하세요.', toolPreferences: ['browser'],
    model: { engine: 'codex', modelId: 'gpt-5.5', effort: 'high' } });
}
function checkedPersonalityForm(form) {
  const result = Chat.validateProfileForm(form);
  assert.equal(result.ok, true, JSON.stringify(result.errors));
  return result.body;
}

test('personality preservation: unchanged form retains examples/avoid and the canonical saved hash', () => {
  const saved = personalityPreservationBody(), original = structuredClone(saved);
  const result = checkedPersonalityForm(Chat.profileFormFromBody(saved));
  assert.deepEqual(result, { ...saved, toolCeiling: null });
  assert.deepEqual(normalizeProfileBody(result), saved);
  assert.equal(profileHash(result), profileHash(saved));
  assert.deepEqual(saved, original);
});

test('personality preservation: role-only edit changes no other saved field and leaves the original untouched', () => {
  const saved = personalityPreservationBody(), original = structuredClone(saved), oldHash = profileHash(saved);
  const form = Chat.profileFormFromBody(saved); form.role = '새 역할';
  const result = checkedPersonalityForm(form);
  assert.deepEqual(result, { ...original, role: '새 역할', toolCeiling: null });
  assert.deepEqual(normalizeProfileBody(result), { ...original, role: '새 역할' });
  assert.deepEqual(saved, original); assert.equal(profileHash(saved), oldHash);
});

test('personality preservation: body, internal form and emitted bodies share no arrays or nested example objects', () => {
  const saved = personalityPreservationBody(), original = structuredClone(saved), form = Chat.profileFormFromBody(saved);
  assert.notEqual(form.personalityExamples, saved.personality.examples);
  assert.notEqual(form.personalityExamples[0], saved.personality.examples[0]);
  assert.notEqual(form.personalityAvoid, saved.personality.avoid);
  form.personalityExamples[0].reply = 'form-only reply'; form.personalityAvoid.push('form-only avoidance');
  assert.deepEqual(saved, original);
  const first = checkedPersonalityForm(form), second = checkedPersonalityForm(form), originalForm = structuredClone(form);
  assert.notEqual(first.personality.examples, form.personalityExamples);
  assert.notEqual(first.personality.examples[0], form.personalityExamples[0]);
  assert.notEqual(first.personality.avoid, form.personalityAvoid);
  first.personality.examples[0].user = 'output-only'; first.personality.avoid.push('output-only');
  assert.deepEqual(form, originalForm); assert.deepEqual(second, checkedPersonalityForm(form));
  assert.deepEqual(saved, original);
});

test('personality preservation: each absent key stays absent and old canonical hashes remain stable', () => {
  const both = personalityPreservationBody().personality;
  for (const supplied of [{}, { examples: both.examples }, { avoid: both.avoid },
    { examples: both.examples, avoid: both.avoid }, { examples: [], avoid: [] }]) {
    const saved = personalityPreservationBody(supplied), form = Chat.profileFormFromBody(saved), result = checkedPersonalityForm(form);
    for (const [key, field] of [['examples', 'personalityExamples'], ['avoid', 'personalityAvoid']]) {
      assert.equal(Object.hasOwn(form, field), Object.hasOwn(saved.personality, key));
      assert.equal(Object.hasOwn(result.personality, key), Object.hasOwn(saved.personality, key));
    }
    assert.deepEqual(normalizeProfileBody(result), saved); assert.equal(profileHash(result), profileHash(saved));
  }
  const empty = Chat.profileFormFromBody(null);
  assert.equal(Object.hasOwn(empty, 'personalityExamples'), false);
  assert.equal(Object.hasOwn(empty, 'personalityAvoid'), false);
});

test('personality preservation: only examples/avoid carry through, without a blanket hidden-field merge', () => {
  const saved = personalityPreservationBody(); saved.personality.unrelated = { doNotCarry: true };
  const form = Chat.profileFormFromBody(saved);
  form.personality = { unrelated: true, tone: 'formal' }; form.unrelated = true; form.tone = 'warm';
  const result = checkedPersonalityForm(form);
  assert.deepEqual(Object.keys(result.personality), ['tone', 'traits', 'speechNotes', 'examples', 'avoid']);
  assert.equal(result.personality.tone, 'warm', 'the actual editable field remains authoritative');
  assert.deepEqual(result.personality.examples, saved.personality.examples);
  assert.deepEqual(result.personality.avoid, saved.personality.avoid);
  assert.equal(Object.hasOwn(result.personality, 'unrelated'), false); assert.equal(Object.hasOwn(result, 'unrelated'), false);
});

test('profile catalog, status, avatars and diffs read as the 대표님 sees them', () => {
  const rows = Chat.normalizeProfileCatalog({ profiles: [...catalogRows, { id: 'Bad ID', lifecycle: 'active', headRevision: 1, name: 'x' },
    { id: 'no-name', lifecycle: 'active', headRevision: 1, name: '' }, { id: 'odd-state', lifecycle: 'running', headRevision: 1, name: 'y' }, catalogRows[0]] });
  assert.deepEqual(rows.map(row => row.id), ['review-verifier', 'prof-stopped', 'prof-draft'], 'malformed or repeated rows are dropped');
  assert.equal(rows[0].avatar.color, '#252a26');
  assert.deepEqual(Chat.profileStatusView(rows[0]), { label: '사용 중', detail: '버전 2 사용 중 · 아직 쓰지 않은 초안 있음', lifecycle: 'active', usable: true, example: true });
  assert.equal(Chat.profileStatusView(rows[1]).usable, false);
  assert.equal(Chat.profileStatusView(rows[1]).label, '사용 중지');
  assert.equal(Chat.profileStatusView(rows[2]).detail, '초안 저장됨 · 아직 사용할 수 없음');
  assert.deepEqual(Chat.profileAvatarView(rows[2].avatar, rows[2].name), { kind: 'emoji', text: '🦉', tone: 1, saved: true });
  assert.deepEqual(Chat.profileAvatarView(null, '검증 담당'), { kind: 'initial', text: '검', tone: 0, saved: false });
  assert.equal(Chat.profileAvatarView({ kind: 'initial', value: 'V', color: '#123456' }, 'x').tone, 0, 'an unknown color never paints outside the palette');
  assert.deepEqual(Chat.profileDiffRows([
    { field: 'name', before: '검증', after: '검증 담당' }, { field: 'personality.tone', before: 'plain', after: 'warm' },
    { field: 'expertise', before: [], after: ['리뷰'], added: ['리뷰'], removed: [] }, { field: 'constructor', before: 1, after: 2 },
  ]).map(row => [row.label, row.before, row.after]), [['담당자 이름', '검증', '검증 담당'], ['말투', '담백', '따뜻'], ['맡길 일', '없음', '리뷰']]);
});

test('a chosen Agent sends its stored profile and revision; a stopped or missing one is refused, not swapped', () => {
  const ready = productionProfileResolver({ status: 'ready', profiles: Chat.normalizeProfileCatalog({ profiles: catalogRows }) });
  assert.deepEqual(ready.codexAgentProfileChoices().map(profile => profile.id), ['review-verifier'], 'only active Agents can be picked');
  const runtimeFor = (resolver, agentProfileId) => {
    const thread = { id: 'room', profileEnabled: true, agentProfileId };
    const profile = resolver.codexAgentProfile(agentProfileId);
    return { thread, profile, runtime: productionRuntimeConfig(thread, () => profile, () => profile.toolMode, () => profile.systemPrompt) };
  };
  const active = runtimeFor(ready, 'review-verifier');
  assert.equal(active.profile.name, '검증 담당');
  assert.deepEqual(active.profile.avatar, { kind: 'initial', value: 'V', color: '#252a26' });
  const body = Chat.buildChatRequest(active.thread, '확인해 줘', 'q1', active.runtime);
  assert.equal(body.profileEnabled, true);
  assert.equal(body.profileId, 'review-verifier');
  assert.equal(body.profileRevision, 2, 'the active revision, not the unsaved draft head');
  for (const field of ['systemPrompt', 'agentProfile', 'toolMode']) assert.equal(Object.hasOwn(body, field), false, field);
  for (const id of ['prof-stopped', 'prof-draft', 'prof-deleted-elsewhere']) {
    const stopped = runtimeFor(ready, id);
    assert.equal(stopped.profile.server, true);
    const wire = Chat.buildChatRequest(stopped.thread, 'hi', 'q2', stopped.runtime);
    assert.equal(wire.profileId, id, 'the bridge decides; the room never borrows another Agent');
    assert.equal(Object.hasOwn(wire, 'profileRevision'), false);
    assert.equal(Object.hasOwn(wire, 'systemPrompt'), false);
  }
  assert.equal(ready.codexAgentProfile('prof-deleted-elsewhere').name, '찾을 수 없는 Agent');
  // No profile store: the built-in definition keeps the previous systemPrompt path.
  const offline = productionProfileResolver({ status: 'unavailable', profiles: [] });
  assert.deepEqual(offline.codexAgentProfileChoices().map(profile => profile.id), ['conversational-coding', 'review-verifier']);
  const legacy = runtimeFor(offline, 'review-verifier');
  const legacyBody = Chat.buildChatRequest(legacy.thread, 'hi', 'q3', legacy.runtime);
  assert.equal(legacyBody.systemPrompt, 'legacy verifier prompt');
  assert.equal(Object.hasOwn(legacyBody, 'profileId'), false);
  // A saved user Agent keeps its ID before the catalog loads, without a borrowed prompt.
  const unknown = runtimeFor(offline, 'prof-mine');
  assert.equal(unknown.profile.systemPrompt, null);
  assert.equal(Object.hasOwn(Chat.buildChatRequest(unknown.thread, 'hi', 'q4', unknown.runtime), 'systemPrompt'), false);
  // Ordinary Codex rooms carry neither path.
  const plain = Chat.buildChatRequest({ id: 'room', profileEnabled: false }, 'hi', 'q5', active.runtime);
  assert.equal(Object.hasOwn(plain, 'profileId'), false);
  assert.equal(Object.hasOwn(plain, 'systemPrompt'), false);
  assert.equal(Chat.buildChatRequest(active.thread, 'hi', 'q6', { profileId: 'Bad ID', profileRevision: 2, systemPrompt: 'p' }).systemPrompt, 'p');
  // The room menu lists the catalog choices; send errors from runProfile read in Korean.
  const menu = surfaceSource.match(/      const renderThreadMenu = \(thread\) => \{([\s\S]*?)\n      \};/)?.[1] || '';
  assert.match(menu, /codexAgentProfileChoices\(\)\.map/);
  assert.doesNotMatch(menu, /CODEX_AGENT_PROFILE_DEFS/);
  for (const code of ['PROFILE_NOT_RUNNABLE', 'PROFILE_NOT_FOUND', 'PROFILE_REVISION_NOT_FOUND', 'INVALID_PROFILE', 'PROFILE_STORE_UNAVAILABLE']) {
    assert.match(Chat.profileSendErrorText(code), /Agent/);
  }
  assert.equal(Chat.profileSendErrorText('RUN_IN_PROGRESS'), null);
});

test('Agent answers keep the Profile avatar captured when the request was sent', () => {
  const state = Chat.createChatProtocolState();
  const avatar = { kind: 'emoji', value: '🦉', color: '#a9c5a9' };
  Chat.registerChatRequest(state, { requestId: 'q', clientThreadId: 'room', authorName: '부엉이', authorAvatar: avatar });
  const run = Chat.acceptChatRequest(state, { accepted: true, requestId: 'q', conversationId: 'c', runId: 'r' }, 'q');
  run.messages = [{ id: 'a', role: 'assistant', text: '답' }];
  const [answer] = Chat.projectRunMessages([], run);
  assert.equal(answer.authorName, '부엉이');
  assert.deepEqual(answer.authorAvatar, avatar);
  const renamed = Chat.projectRunMessages([answer], { ...run, authorName: '다른 이름', authorAvatar: { kind: 'initial', value: 'Z', color: '#49634f' } });
  assert.deepEqual(renamed[0].authorAvatar, avatar, 'an existing answer keeps its author');
  assert.equal(Chat.projectRunMessages([], { ...run, authorAvatar: { kind: 'emoji', value: 'not-emoji', color: '#49634f' } })[0].authorAvatar, null);
});

test('usage ring shows reported ChatGPT usage, grey 확인 안 됨 when nothing was reported, and the reset time on hover', () => {
  assert.equal(Chat.usageRingView({ isLoggedIn: false, usage: { level: 'ok' } }), null, 'nothing to show while signed out');
  for (const auth of [{ isLoggedIn: true }, { isLoggedIn: true, usage: usageDisplay(null) }, { isLoggedIn: true, usage: { level: 'mystery', percentLabel: '0% 사용' } }]) {
    const view = Chat.usageRingView(auth);
    assert.equal(view.level, 'unknown');
    assert.equal(view.percent, null, 'never an invented 0%');
    assert.equal(view.text, '확인 안 됨');
  }
  const now = Date.now();
  const limits = normalizeRateLimits({ rateLimits: { primary: { usedPercent: 42.6, windowDurationMins: 300, resetsAt: Math.floor((now + 3600_000) / 1000) },
    secondary: { usedPercent: 12, windowDurationMins: 10080 } } }, now);
  const ok = Chat.usageRingView({ isLoggedIn: true, rateLimits: limits, usage: usageDisplay(limits, now) });
  assert.equal(ok.level, 'ok');
  assert.equal(ok.percent, 42);
  assert.equal(ok.text, '42%');
  assert.match(ok.title, /^5시간 한도 · 42% 사용 · .+에 초기화$/);
  assert.equal(ok.stale, false);
  const full = normalizeRateLimits({ rateLimits: { primary: { usedPercent: 100, windowDurationMins: 300, resetsAt: Math.floor((now + 600_000) / 1000) }, rateLimitReachedType: 'rate_limit_reached' } }, now);
  const limit = Chat.usageRingView({ isLoggedIn: true, rateLimits: full, usage: usageDisplay(full, now) });
  assert.equal(limit.level, 'limit');
  assert.equal(limit.text, '한도');
  assert.match(limit.title, /한도 도달/);
  const old = Chat.usageRingView({ isLoggedIn: true, rateLimits: limits, usage: usageDisplay(limits, now + 16 * 60_000) });
  assert.equal(old.stale, true);
  assert.match(old.title, /확인한 지 오래되어 실제와 다를 수 있음/);
  // Both Chat heads carry the ring (the room's engine; SUB-03 Claude); the CSS draws unknown as a grey track.
  assert.equal(surfaceSource.match(/^ +chatHeadUsageRing\(activeEngine, codex\),$/gm)?.length, 2);
  assert.match(surfaceSource, /return codexUsageRing\(codex\.authStatus, '', onOpen\);/);
  const css = readFileSync(new URL('../overlay/CSS/eg-desk-surface.uc.css', import.meta.url), 'utf8');
  assert.match(css, /\.egd-usage-unknown \.egd-usage-ring \{ background: var\(--egd-outline\); \}/);
});

test('ChatGPT plan names come from the reported plan type only', () => {
  assert.equal(Chat.codexPlanLabel('plus'), 'Plus');
  assert.equal(Chat.codexPlanLabel('pro'), 'Pro');
  assert.equal(Chat.codexPlanLabel('free'), '무료');
  for (const missing of ['unknown', null, undefined, 'constructor', 'PLUS']) assert.equal(Chat.codexPlanLabel(missing), null, String(missing));
  for (const plan of PLAN_TYPES) if (plan !== 'unknown') assert.ok(Chat.codexPlanLabel(plan), `label for ${plan}`);
});

test('run errors read by kind with the next step: login, reset time, permission, retry', () => {
  const now = new Date(2026, 9, 24, 13, 0).getTime();
  const resetAt = new Date(2026, 9, 24, 15, 20).getTime();
  const quota = publicError({ message: 'You have hit your usage limit', codexErrorInfo: 'usageLimitExceeded' }, 'TURN_FAILED', 'codex');
  assert.equal(quota.kind, 'quota');
  assert.deepEqual(Chat.runErrorNotice(quota, { resetsAt: resetAt }, now), { kind: 'quota', text: '사용 한도에 도달했습니다. 오후 3:20에 다시 쓸 수 있습니다.', action: null });
  assert.equal(Chat.runErrorNotice({ ...quota, retryAt: new Date(2026, 9, 25, 9, 5).getTime() }, null, now).text,
    '사용 한도에 도달했습니다. 10월 25일 오전 9:05에 다시 쓸 수 있습니다.', 'retryAt from the error wins');
  assert.match(Chat.runErrorNotice(quota, { resetsAt: now - 1 }, now).text, /다시 쓸 수 있는 시각은 아직 확인되지 않았습니다/);
  const auth = publicError({ message: 'unauthorized', codexErrorInfo: 'unauthorized' }, 'TURN_FAILED', 'codex');
  assert.deepEqual(Chat.runErrorNotice(auth, null, now), { kind: 'auth', text: '다시 로그인이 필요합니다.', action: 'login' });
  assert.deepEqual(Chat.runErrorNotice(publicError({ message: 'blocked', codexErrorInfo: 'sandboxError' }, 'TURN_FAILED', 'codex'), null, now),
    { kind: 'permission', text: '권한이 부족합니다.', action: null });
  assert.deepEqual(Chat.runErrorNotice(publicError(new Error('socket closed'), 'CONNECTION_LOST'), null, now),
    { kind: 'network', text: '연결이 불안정합니다. 다시 시도해 주세요.', action: 'retry' });
  assert.deepEqual(Chat.runErrorNotice(publicError({ message: 'Context window exceeded', codexErrorInfo: 'contextWindowExceeded' }, 'TURN_FAILED', 'codex'), null, now),
    { kind: 'model', text: 'Context window exceeded', action: null }, 'model keeps the existing text');
  assert.deepEqual(Chat.runErrorNotice({ code: 'RUNTIME_LOST', message: '실행 연결이 끊어졌습니다.' }, null, now), { kind: 'unknown', text: '실행 연결이 끊어졌습니다.', action: null });
  assert.deepEqual(Chat.runErrorNotice('문자열 오류'), { kind: 'unknown', text: '문자열 오류', action: null });
  assert.equal(Chat.runErrorNotice(null), null);
  // The conversation shows the notice with its button; the activity log uses the same words.
  assert.match(surfaceSource, /ChatState\.runErrorNotice\(run\.error,\s*\[activeThread\.engineId, run\.engineId, run\.engine\?\.id, run\.error\?\.origin, run\.rateLimit\?\.engineId\]\.includes\('claude'\) \? null : codex\.authStatus\?\.usage\)/);
  assert.match(surfaceSource, /runError\.action === 'login' && ChatState\.chatThreadEngineId\(activeThread, codex\) === 'codex' \? el\('button'[\s\S]*?onclick: \(\) => codexBridge\.startLogin\(\)/);
  assert.match(surfaceSource, /runError\.action === 'retry' \? el\('button'[\s\S]*?onclick: \(\) => codexBridge\.retryRun\(activeThread\.id, run\.runId\)/);
  assert.match(surfaceSource, /rows\.push\(el\('p', \{ class: 'egd-codex-error' \}, ChatState\.runErrorNotice\(run\.error,\s*\[thread\.engineId, run\.engineId, run\.engine\?\.id, run\.error\?\.origin, run\.rateLimit\?\.engineId\]\.includes\('claude'\) \? null : state\.codex\.authStatus\?\.usage\)\.text\)\)/);
});

test('Settings, avatar and usage CSS use approved tokens only', () => {
  const css = readFileSync(new URL('../overlay/CSS/eg-desk-surface.uc.css', import.meta.url), 'utf8');
  const rules = [...css.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/([^{}]+)\{([^{}]*)\}/g)]
    .filter(([, selector]) => /\.egd-(?:settings|profile-avatar|usage)/.test(selector));
  assert.ok(rules.length > 40);
  for (const [, selector, body] of rules) assert.doesNotMatch(body, /#[0-9a-fA-F]{3,8}\b/, selector.trim());
  const token = name => css.match(new RegExp(`${name}:\\s*(#[0-9A-Fa-f]{6})`))?.[1]?.toLowerCase();
  assert.deepEqual([token('--egd-primary'), token('--egd-avatar-sage'), token('--egd-avatar-wood'), token('--egd-avatar-muted'),
    token('--egd-on-surface'), token('--egd-note')], AVATAR_PALETTE, 'the six tones are the store palette');
  const light = readRootProperties(css, { scheme: 'light' });
  for (const scheme of ['light', 'dark']) {
    const properties = readRootProperties(css, { scheme });
    const tones = readAvatarTones(css, { scheme });
    assert.deepEqual(tones.map(({ tone }) => tone), [0, 1, 2, 3, 4, 5], `${scheme} keeps all six tones`);
    for (const { tone, background, color } of tones) {
      const paint = resolveColor(background, properties);
      const ink = resolveColor(color, properties);
      assert.ok(paint && ink, `${scheme} avatar tone ${tone} resolves both colours`);
      assert.deepEqual(paint, resolveColor(background, light), `tone ${tone} keeps its pale background in both schemes`);
      assert.deepEqual(ink, resolveColor('var(--egd-avatar-ink)', light), `tone ${tone} keeps the fixed avatar ink`);
      assert.ok(contrastRatio(paint, resolveColor('#000', properties)) >= 10, `tone ${tone} has a pale background`);
      assert.ok(contrastRatio(ink, resolveColor('#fff', properties)) >= 7, `tone ${tone} has dark ink`);
      assert.ok(contrastRatio(ink, paint) >= 4.5, `${scheme} tone ${tone} initials meet 4.5:1`);
      const chat = cssDeclarationsFor(css, `.egd-codex-message-avatar.egd-profile-avatar-tone-${tone}`, { scheme });
      assert.deepEqual(resolveColor(chat.background, properties), paint, `chat tone ${tone} keeps the profile background`);
      assert.deepEqual(resolveColor(chat.color, properties), ink, `chat tone ${tone} keeps the profile ink`);
    }
  }
});

test('Browser scroll/press are wired into the Card dispatch allow-list and receipt', () => {
  assert.match(surfaceSource, /const BrowserAgentReceipts = ChromeUtils\.importESModule\('chrome:\/\/userchrome\/content\/EGDeskBrowserAgentRuntimeParent\.sys\.mjs'\);/);
  // BRW-10 appends the trusted pointer press and typing routes to the same list.
  assert.match(surfaceSource, /\['navigate', 'click', 'fill', 'scroll', 'press', 'pointer-click', 'type-text'\]\.includes\(request\.action\?\.type\)/);
  assert.match(surfaceSource, /request\.action\.selector \|\| \(!\['navigate', 'scroll'\]\.includes\(request\.action\.type\) && !request\.action\.ref\)/);
  assert.match(surfaceSource, /BrowserAgentReceipts\.browserToolDispatchReceiptFields\(action\.type, result\?\.result\?\.dispatchDiagnostics\)/);
});

test('다시 시도 sends the failed request words once more, only into an empty composer', () => {
  const body = surfaceSource.match(/      retryRun\(threadId, runId\) \{([\s\S]*?)\n      \},\n      async sendMessage/)?.[1];
  assert.ok(body, 'production retryRun must remain directly testable');
  const retry = compileFunction(body, ['threadId', 'runId', 'state', 'getCodexThreadById', 'threadBusy', 'codexRuns', 'boardNotice', 'getCodexThreadDraft', 'ChatState']);
  const thread = { id: 'room', messages: [{ id: 'u1', role: 'user', content: '첫 질문', requestId: 'q1' }, { id: 'u2', role: 'user', content: '다시 보낼 질문', requestId: 'q2' }] };
  const state = { codex: { activeThreadId: 'other', threadDrafts: {} } };
  const notices = [];
  const calls = [];
  const ctx = { setDraft: (text, id) => { calls.push(['draft', text, id]); state.codex.threadDrafts[id] = text; }, sendMessage: () => { calls.push(['send']); return 'sent'; } };
  const run = (draft = '', busy = false) => {
    state.codex.threadDrafts.room = draft;
    return retry.call(ctx, 'room', 'turn-2', state, () => thread, () => busy, () => [{ runId: 'turn-2', requestId: 'q2' }],
      text => notices.push(text), (codex, id) => codex.threadDrafts[id] || '', Chat);
  };
  assert.equal(run('입력 중'), null);
  assert.deepEqual(calls, [], 'a draft in progress is never replaced');
  assert.match(notices.at(-1), /입력 중인 내용이 있어/);
  assert.equal(run('', true), null);
  assert.deepEqual(calls, [], 'a busy room is not re-sent');
  assert.equal(run(''), 'sent');
  assert.deepEqual(calls, [['draft', '다시 보낼 질문', 'room'], ['send']]);
  assert.equal(state.codex.activeThreadId, 'room');
  // A plan step resumed in place is the bridge's turn, not 대표님's words to send again.
  calls.length = 0;
  thread.messages[1] = { id: 'u2', role: 'user', content: '<egdesk-await-resume>\n  <await_id>g/s</await_id>\n</egdesk-await-resume>', requestId: 'q2' };
  assert.equal(run(''), null);
  assert.deepEqual(calls, [], 'the resume message never lands in the composer');
  assert.match(notices.at(-1), /계획 단계에서 이어진 실행은 다시 보내지 않습니다/);
});

test('Settings window frame: a named title row, two working dots and resize from any edge', () => {
  const document = settingsFakeDocument(), docListeners = {};
  document.addEventListener = (type, fn) => { (docListeners[type] ||= []).push(fn); };
  const { el, codexProfileAvatar } = compileFunction(`${declaration('el')}\n${declaration('codexProfileAvatar')}\nreturn { el, codexProfileAvatar };`, ['document', 'ChatState'])(document, Chat);
  const state = { codex: { connected: false, isStartingLogin: false, authStatus: { isLoggedIn: false }, recentEngineId: 'codex', threads: [] } };
  state.codexBridge = { subscribe(listener) { listener(state.codex); return () => {}; }, profileCatalog: () => ({ status: 'ready', profiles: [] }), loadProfiles: () => Promise.resolve() };
  const effects = { closed: 0, fullscreen: 0, focus: 0, dirty: [] };
  let maximized = false;
  const deps = { singletonSourceRef: () => ({ kind: 'settings-card' }), focusOpenSourceCard: () => null, cardSeq: 0,
    resolveCanvasCardPlacement: () => ({ x: 100, y: 80, width: 600, height: 500, inView: true }), revealPlacedCanvasCard() {}, el, cardZ: 0,
    closeCanvasCard: () => effects.closed++, state, ChatState: Chat, codexProfileAvatar, document, window: { setTimeout: () => 0, confirm: () => false },
    bindCardSourceRef() {}, markAgendaDirty: reason => effects.dirty.push(reason), setActiveEntity() {}, isCardFullscreen: () => maximized,
    focusCanvasCard: () => effects.focus++, installCardHeaderFullscreenToggle() {}, canvasZoom: () => 2, ...settingsTransferDeps(document, state),
    AccountSettingsView, codexBridgeNotice: settingsBridgeNotice, deskIcon: settingsDeskIcon(document), toggleCardFullscreen: () => effects.fullscreen++ };
  const card = compileFunction(`${declaration('spawnSettingsCard')}\nreturn spawnSettingsCard;`, Object.keys(deps))(...Object.values(deps))();
  const byClass = name => settingsNodes(card, node => String(node.className).split(/\s+/).includes(name));

  // Title row: grip, the Settings icon and the Korean window name.
  const titlebar = byClass('egd-desk-window-titlebar')[0];
  assert.ok(titlebar, 'Settings uses the shared title row class');
  assert.equal(titlebar.parentNode.className, 'egd-card-header egd-desk-window-header', 'the header is one title row high, with no empty band under it');
  assert.equal(cssDeclarationsFor(surfaceCss, '.egd-desk-window-header')['min-height'], '32px');
  assert.equal(byClass('egd-settings-title')[0].textContent, '설정');
  assert.deepEqual(settingsNodes(titlebar, node => !!node.dataset.icon).map(node => node.dataset.icon), ['grip', 'settings']);
  assert.equal(byClass('egd-window-grip')[0].getAttribute('aria-hidden'), 'true');

  // Dots: close, fold and maximize. UX-06: Settings folds to its title row like other windows.
  const allDots = byClass('egd-card-dot');
  assert.deepEqual(allDots.map(dot => dot.className), ['egd-card-dot egd-card-dot-close egd-desk-window-control',
    'egd-card-dot egd-card-dot-min egd-desk-window-control', 'egd-card-dot egd-card-dot-max egd-desk-window-control']);
  const fold = allDots[1];
  assert.deepEqual([fold.getAttribute('title'), fold.getAttribute('aria-expanded')], ['창 접기', 'true']);
  const dotDirty = effects.dirty.length;
  fold.click = () => fold.fire('click');
  fold.fire('click');
  assert.equal(card.classList.contains('egd-card-collapsed'), true);
  assert.deepEqual([fold.getAttribute('title'), fold.getAttribute('aria-expanded')], ['창 펼치기', 'false']);
  fold.fire('keydown', { key: 'Enter', preventDefault() {}, stopPropagation() {} });
  assert.equal(card.classList.contains('egd-card-collapsed'), false);
  assert.deepEqual(effects.dirty.slice(dotDirty), ['collapse-settings-window', 'expand-settings-window']);
  assert.equal(card._setWindowCollapsed(true, { quiet: true }), true, 'restore folds it without a change mark');
  card._setWindowCollapsed(false, { quiet: true });
  assert.equal(effects.dirty.length, dotDirty + 2);
  const dots = [allDots[0], allDots[2]];
  for (const dot of dots) {
    assert.equal(dot.getAttribute('role'), 'button'); assert.equal(dot.getAttribute('tabindex'), '0');
    assert.ok(dot.getAttribute('title')); assert.equal(dot.getAttribute('aria-label'), dot.getAttribute('title'));
    dot.click = () => dot.fire('click');
  }
  const [close, maximize] = dots;
  assert.deepEqual([close.getAttribute('title'), maximize.getAttribute('title'), maximize.getAttribute('aria-pressed')], ['창 닫기', '창 최대화', 'false']);
  close.fire('click'); assert.equal(effects.closed, 1);
  let prevented = 0;
  close.fire('keydown', { key: 'Enter', preventDefault() { prevented++; } }); assert.equal(effects.closed, 2);
  maximize.fire('keydown', { key: ' ', preventDefault() { prevented++; } }); assert.equal(effects.fullscreen, 1);
  close.fire('keydown', { key: 'a', preventDefault() { prevented++; } });
  assert.deepEqual([prevented, effects.closed], [2, 2], 'other keys are left alone');

  // Resize: eight handles, camera zoom respected, smallest size held, the far edge stays put.
  const hits = byClass('egd-card-resize-hit');
  assert.equal(hits.length, 8);
  Object.assign(card, { offsetLeft: 100, offsetTop: 80, offsetWidth: 600, offsetHeight: 500 });
  const hit = edge => byClass(`egd-card-resize-hit-${edge}`)[0];
  const move = (clientX, clientY) => { for (const fn of docListeners.mousemove) fn({ clientX, clientY }); };
  const release = () => { for (const fn of docListeners.mouseup) fn({}); };
  const rect = () => [card.style.left, card.style.top, card.style.width, card.style.height];
  const created = effects.dirty.length, focus = effects.focus;
  hit('se').fire('mousedown', { button: 0, clientX: 700, clientY: 580 });
  assert.equal(effects.focus, focus + 1);
  move(760, 620);
  assert.deepEqual(rect(), ['100px', '80px', '630px', '520px'], 'half the pointer distance at 2x zoom');
  release();
  assert.deepEqual(effects.dirty.slice(created), ['resize-settings-card']);
  hit('nw').fire('mousedown', { button: 0, clientX: 100, clientY: 80 });
  move(1100, 1080);
  assert.deepEqual(rect(), ['280px', '260px', '420px', '320px'], 'the smallest size holds and the right/bottom edge does not move');
  release();
  move(0, 0);
  assert.deepEqual(rect(), ['280px', '260px', '420px', '320px'], 'no resize after release');
  assert.deepEqual(effects.dirty.slice(created), ['resize-settings-card', 'resize-settings-card']);
  hit('e').fire('mousedown', { button: 2, clientX: 0, clientY: 0 }); move(500, 0); release();
  maximized = true;
  hit('e').fire('mousedown', { button: 0, clientX: 0, clientY: 0 }); move(500, 0); release();
  assert.deepEqual(rect(), ['280px', '260px', '420px', '320px'], 'no resize from another button or while maximized');
  assert.equal(effects.dirty.length, created + 2);
  const settingsCss = cssDeclarationsFor(surfaceCss, '.egd-settings-card');
  assert.deepEqual([settingsCss['min-width'], settingsCss['min-height']], ['420px', '320px'], 'the script and the stylesheet agree on the smallest size');
});

// A small element fake: enough for el(), events and text, so the production
// Settings card can be driven without Firefox.
function settingsFakeDocument() {
  const byId = new Map();
  const doc = { activeElement: null };
  class FakeNode {
    constructor(tag) { this.tagName = tag.toUpperCase(); this.children = []; this.attributes = {}; this.dataset = {}; this.style = {}; this.listeners = {}; this.className = ''; this.ownText = ''; this.value = ''; this.isConnected = true; }
    _connect(value) { this.isConnected = value; for (const child of this.children) { if (child._connect) child._connect(value); else child.isConnected = value; } }
    appendChild(child) { child.remove?.(); this.children.push(child); child.parentNode = this; if (child._connect) child._connect(this.isConnected); else child.isConnected = this.isConnected; return child; }
    append(...children) { for (const child of children) this.appendChild(typeof child === 'string' ? doc.createTextNode(child) : child); }
    remove() { if (this.parentNode) this.parentNode.children = this.parentNode.children.filter(child => child !== this); this.parentNode = null; this._connect(false); }
    contains(node) { return this === node || this.children.some(child => child === node || child.contains?.(node)); }
    replaceChildren(...children) { for (const child of [...this.children]) child.remove?.(); this.children = []; this.ownText = ''; this.append(...children.filter(child => child != null)); }
    setAttribute(key, value) { this.attributes[key] = String(value); if (key === 'id') byId.set(String(value), this); if (key.startsWith('data-')) this.dataset[key.slice(5).replace(/-([a-z])/g, (_, letter) => letter.toUpperCase())] = String(value); }
    getAttribute(key) { return this.attributes[key] ?? null; }
    addEventListener(type, fn) { (this.listeners[type] ||= []).push(fn); }
    removeEventListener(type, fn) { this.listeners[type] = (this.listeners[type] || []).filter(item => item !== fn); }
    get textContent() { return this.ownText + this.children.map(child => child.textContent).join(''); }
    set textContent(value) { this.children = []; this.ownText = String(value); }
    focus(options) { doc.activeElement = this; this.focusOptions = options; }
    setSelectionRange(start, end, direction) { Object.assign(this, { selectionStart: start, selectionEnd: end, selectionDirection: direction }); this.scrollTop = 0; }
    fire(type, extra = {}) { for (const fn of this.listeners[type] || []) fn({ stopPropagation() {}, preventDefault() {}, currentTarget: this, target: this, ...extra }); }
    set classList(value) { Object.defineProperty(this, 'classList', { value, writable: true, configurable: true }); }
    get classList() {
      const names = () => this.className.split(/\s+/).filter(Boolean);
      const contains = name => names().includes(name);
      const toggle = (name, force = !contains(name)) => {
        this.className = force ? [...new Set([...names(), name])].join(' ') : names().filter(item => item !== name).join(' ');
        return force;
      };
      return { contains, toggle, add: name => toggle(name, true), remove: name => toggle(name, false) };
    }
  }
  Object.assign(doc, {
    createElement: tag => new FakeNode(tag),
    createTextNode: text => ({ textContent: String(text), children: [] }),
    getElementById: id => byId.get(id) || null,
    documentElement: new FakeNode('html'),
    addEventListener() {}, removeEventListener() {},
  });
  return doc;
}
// The Settings title row draws its grip and kind icon through deskIcon.
const settingsDeskIcon = document => (name, className = 'egd-ui-icon') => {
  const icon = document.createElement('svg'); icon.className = className; icon.dataset.icon = name; return icon;
};
const settingsNodes = (node, predicate, found = []) => {
  if (node?.tagName && predicate(node)) found.push(node);
  for (const child of node?.children || []) settingsNodes(child, predicate, found);
  return found;
};
const settingsButton = (root, text) => settingsNodes(root, node => node.tagName === 'BUTTON' && node.textContent.trim() === text)[0];
const settle = async () => { for (let i = 0; i < 6; i++) await new Promise(resolve => setImmediate(resolve)); };

// The Settings card's bridge notice, as the production codexBridgeNotice derives it.
const settingsBridgeNotice = codex => Surface.bridgeConnectionNotice({ connected: codex.connected, failures: codex.bridgeFailures, error: codex.bridgeError, bridge: codex.bridgeBuild });
function settingsTransferDeps(document, state, files = { readText: async () => ({ cancelled: true }), saveText: async () => ({ cancelled: true }) }) {
  return compileFunction(`${declaration('settingsProfileAccountKey')}\n${declaration('createSettingsProfileTransfer')}\nreturn { settingsProfileAccountKey, createSettingsProfileTransfer };`,
    ['document', 'state', 'ProfileTransfer', 'ProfileTransferView', 'nativeTextFilePickers'])(document, state, ProfileTransfer, ProfileTransferView, () => files);
}

test('production Settings card renders the reported account and drives Agent edits through the profile routes', async () => {
  const document = settingsFakeDocument();
  const { el, codexProfileAvatar } = compileFunction(`${declaration('el')}\n${declaration('codexProfileAvatar')}\nreturn { el, codexProfileAvatar };`, ['document', 'ChatState'])(document, Chat);
  const spawnSource = declaration('spawnSettingsCard');
  assert.ok(spawnSource);
  const listeners = new Set();
  const calls = [];
  const now = Date.now();
  const limits = normalizeRateLimits({ rateLimits: { primary: { usedPercent: 42, windowDurationMins: 300, resetsAt: Math.floor((now + 3600_000) / 1000) } } }, now);
  const state = { codex: { connected: false, isStartingLogin: false, authStatus: { isLoggedIn: false },
    recentEngineId: 'codex', threads: [{ id: 'fixture-room', engineId: 'codex' }] } };
  let catalog = { status: 'ready', profiles: Chat.normalizeProfileCatalog({ profiles: catalogRows }) };
  const verifier = { id: 'review-verifier', lifecycle: 'active', origin: 'template', activeRevision: 2, headRevision: 3, hasDraft: true,
    active: { revision: 2, body: normalizeProfileBody({ name: '검증 담당', role: '버그와 회귀를 먼저 봅니다', avatar: { kind: 'initial', value: 'V', color: '#252a26' } }) },
    head: { revision: 3, body: normalizeProfileBody({ name: '검증 담당', role: '새 역할', personality: { tone: 'warm' } }) } };
  let respond = null;
  state.codexBridge = {
    subscribe(listener) { listeners.add(listener); listener(state.codex); return () => listeners.delete(listener); },
    startLogin() { calls.push(['login']); }, signOut() { calls.push(['signOut']); }, refreshAuthStatus() { calls.push(['refresh']); },
    sendMessage() { calls.push(['sendMessage']); }, setThreadEngine() { calls.push(['setThreadEngine']); },
    profileCatalog: () => catalog, loadProfiles() { calls.push(['loadProfiles']); return Promise.resolve(); },
    async profileRequest(path, init = {}) {
      calls.push([init.method || 'GET', path, init.body]);
      if (respond) { const answer = respond(path, init); if (answer) return answer; }
      if (path === '/profiles/review-verifier') return verifier;
      if (path === '/profiles/review-verifier/revisions') return { profileId: 'review-verifier', revisions: [3, 2, 1].map(revision => ({ profileId: 'review-verifier', revision, parentRevision: revision - 1 || null, createdAt: now })) };
      throw Object.assign(new Error('not mocked'), { status: 500 });
    },
  };
  const emit = () => { for (const listener of listeners) listener(state.codex); };
  let confirmAnswer = false;
  const windowStub = { innerWidth: 1280, innerHeight: 800, confirm: () => confirmAnswer, setTimeout: () => 0 };
  const placements = [];
  const spawn = compileFunction(`${spawnSource}\nreturn spawnSettingsCard;`, ['singletonSourceRef', 'focusOpenSourceCard', 'cardSeq', 'resolveCanvasCardPlacement',
    'revealPlacedCanvasCard', 'el', 'cardZ',
    'closeCanvasCard', 'state', 'ChatState', 'codexProfileAvatar', 'document', 'window', 'bindCardSourceRef', 'markAgendaDirty', 'setActiveEntity',
    'isCardFullscreen', 'focusCanvasCard', 'installCardHeaderFullscreenToggle', 'canvasZoom', 'settingsProfileAccountKey', 'createSettingsProfileTransfer',
    'fetch', 'fetchJson', 'spawnTerminalCard', 'AccountSettingsView', 'codexBridgeNotice', 'deskIcon'])(
    () => ({ kind: 'settings-card' }), () => null, 0, kind => { placements.push(kind); return { x: 10, y: 20, width: 600, height: 600, inView: true }; },
    () => {}, el, 0, () => {}, state, Chat, codexProfileAvatar, document, windowStub,
    () => {}, () => {}, () => {}, () => false, () => {}, () => {}, () => 1, ...Object.values(settingsTransferDeps(document, state)),
    (...args) => { calls.push(['fetch', ...args]); }, (...args) => { calls.push(['fetchJson', ...args]); },
    (...args) => { calls.push(['terminal', ...args]); }, AccountSettingsView, settingsBridgeNotice, settingsDeskIcon(document));
  const card = spawn();
  assert.deepEqual(placements, ['settings'], 'Settings opens through the shared placement policy');
  assert.deepEqual([card.style.left, card.style.top, card.style.width, card.style.height], ['10px', '20px', '600px', '600px']);
  const text = () => card.textContent;
  assert.match(text(), /연결 확인 중…/, 'before the bridge answers the card does not claim it is gone');
  assert.equal(settingsNodes(card, node => node.dataset.testid === 'settings-account')[0].dataset.state, 'checking');
  state.codex.bridgeFailures = 3;
  emit();
  assert.match(text(), /연결이 끊겼습니다/);
  assert.equal(settingsNodes(card, node => node.dataset.testid === 'settings-account')[0].dataset.state, 'offline');
  assert.ok(settingsButton(card, '다시 연결'));
  state.codex.bridgeFailures = 0;
  emit();
  assert.match(text(), /연결 확인 중…/);
  const claude = () => settingsNodes(card, node => node.dataset.testid === 'settings-claude')[0];
  assert.equal(claude().dataset.auth, 'unknown');
  assert.equal(claude().dataset.state, 'unknown');
  assert.match(claude().textContent, /현재 상태는 확인할 수 없습니다/);
  assert.doesNotMatch(text(), /AI 모델|Provider|GPT-4/);

  // Opening Settings and receiving engine updates is passive: no login,
  // refresh, profile request, terminal command, message or engine selection.
  assert.deepEqual(calls, []);
  state.codex.connected = true;
  state.codex.engines = [claudeSettingsFixture()];
  emit();
  assert.equal(claude().dataset.auth, 'signedIn');
  assert.match(claude().textContent, /연결 프로그램의 마지막 보고 기준 · 인증: 인증됨/);
  assert.match(claude().textContent, /엔진: 준비됨/);
  assert.match(claude().textContent, /버전 2\.1\.300/);
  assert.equal((claude().textContent.match(/마지막 보고/g) || []).length, 1, 'one provenance for all reported fields');
  state.codex.engines = [claudeSettingsFixture({ auth: { status: 'signedOut' } })];
  emit();
  assert.equal(claude().dataset.auth, 'signedOut', 'an engine-only change re-renders the account tab');
  state.codex.engines = [claudeSettingsFixture({ auth: { status: 'unknown' } })];
  emit();
  assert.deepEqual([claude().dataset.auth, claude().dataset.state], ['unknown', 'offline']);
  state.codex.engines = [claudeSettingsFixture({ installed: false, version: null, auth: null })];
  emit();
  assert.deepEqual([claude().dataset.auth, claude().dataset.state], ['unknown', 'notInstalled']);
  assert.match(claude().textContent, /설치되지 않음/);
  assert.equal(settingsNodes(claude(), node => node.dataset.testid === 'settings-claude-version').length, 0);
  state.codex.engines = [claudeSettingsFixture({ version: '2.1.204', versionStatus: 'unsupported' })];
  emit();
  assert.deepEqual([claude().dataset.auth, claude().dataset.state], ['signedIn', 'versionUnsupported']);
  assert.match(claude().textContent, /사용할 수 없음/);
  state.codex.engines = [];
  emit();
  assert.deepEqual([claude().dataset.auth, claude().dataset.state], ['unknown', 'unknown']);
  assert.match(claude().textContent, /연결 프로그램의 보고 확인 안 됨 · 인증: 확인 안 됨/);
  assert.doesNotMatch(claude().textContent, /마지막 보고/);
  state.codex.engines = [claudeSettingsFixture({ auth: { status: 'signedOut' } })];
  emit();
  state.codex.connected = false;
  emit();
  assert.equal(claude().dataset.auth, 'signedOut', 'disconnect does not turn an old sign-out into a new auth result');
  assert.match(claude().textContent, /연결 프로그램의 마지막 보고 기준 · 인증: 인증 안 됨/);
  assert.equal((claude().textContent.match(/마지막 보고/g) || []).length, 1);
  assert.match(claude().textContent, /현재 상태는 확인할 수 없습니다/);
  state.codex.connected = true;
  state.codex.engines = [claudeSettingsFixture()];
  emit();
  assert.equal(claude().dataset.auth, 'signedIn');
  assert.doesNotMatch(claude().textContent, /현재 상태는 확인할 수 없습니다/);
  assert.equal(settingsNodes(claude(), node => node.tagName === 'BUTTON').length, 0);
  assert.equal(state.codex.recentEngineId, 'codex');
  assert.equal(state.codex.threads[0].engineId, 'codex', 'Claude status never switches a room engine');
  assert.equal(state.codex.authStatus.isLoggedIn, false, 'Claude authentication is not a Codex login');
  assert.deepEqual(calls, [], 'opening and re-rendering sends no request, login, command or message');

  Object.assign(state.codex, { connected: true, authStatus: { isLoggedIn: false } });
  emit();
  settingsButton(card, '로그인').fire('click');
  assert.deepEqual(calls.at(-1), ['login'], 'the actual login flow');

  state.codex.authStatus = { isLoggedIn: true, accountEmail: 'owner@example.test', planType: 'pro', rateLimits: limits, usage: usageDisplay(limits, now) };
  emit();
  assert.match(text(), /owner@example\.test/);
  assert.match(text(), /Pro 요금제/);
  assert.match(text(), /5시간 한도 · 42% 사용/);
  assert.match(text(), /에 초기화/);
  assert.equal(settingsButton(card, '로그아웃').getAttribute('role'), 'menuitem', 'no bare sign-out button: 로그아웃 is a menu item that confirms first');
  const menuItem = id => settingsNodes(card, node => node.dataset.testid === `settings-account-${id}`)[0];
  assert.deepEqual(['refresh', 'switch', 'signout'].map(id => menuItem(id).textContent), ['상태 새로고침', '다른 계정으로 로그인', '로그아웃']);
  const callsBefore = calls.length;
  menuItem('signout').fire('click');
  assert.equal(calls.length, callsBefore, 'choosing 로그아웃 only asks; nothing is sent yet');
  const confirmBox = () => settingsNodes(card, node => node.dataset.testid === 'settings-account-confirm')[0];
  assert.equal(confirmBox().dataset.action, 'signout');
  assert.equal(confirmBox().dataset.busyRuns, '0');
  assert.match(confirmBox().textContent, /owner@example\.test 계정에서 로그아웃할까요\?/);
  assert.match(confirmBox().textContent, /터미널의 codex/);
  settingsNodes(card, node => node.dataset.testid === 'settings-account-confirm-cancel')[0].fire('click');
  assert.equal(confirmBox(), undefined, '취소 keeps the account');
  assert.equal(calls.length, callsBefore);
  state.codex.chatProtocol = { runs: { 'c1/r1': { conversationId: 'c1', runId: 'r1', status: 'running', localThreadId: 'fixture-room' } }, requests: {} };
  state.codex.threads[0].title = '배포 점검';
  menuItem('switch').fire('click');
  assert.equal(confirmBox().dataset.action, 'switch');
  assert.equal(confirmBox().dataset.busyRuns, '1', 'a running Run is named before the switch');
  assert.match(confirmBox().textContent, /진행 중인 실행 1개가 중단될 수 있습니다 \('배포 점검'\)/);
  assert.match(confirmBox().textContent, /새 계정으로 옮기지 않습니다/);
  settingsNodes(card, node => node.dataset.testid === 'settings-account-confirm-cancel')[0].fire('click');
  menuItem('signout').fire('click');
  settingsNodes(card, node => node.dataset.testid === 'settings-account-confirm-ok')[0].fire('click');
  await settle();
  assert.deepEqual(calls.slice(callsBefore), [['signOut'], ['refresh']], 'the real sign-out, then the account is read back');
  const result = () => settingsNodes(card, node => node.dataset.testid === 'settings-account-result')[0];
  assert.equal(result().dataset.phase, 'unknown', 'the stub left the login in place, so the card says the result is unconfirmed');
  assert.match(result().textContent, /로그아웃 결과를 확인하지 못했습니다/);
  delete state.codex.chatProtocol;
  state.codex.authStatus = { isLoggedIn: true, accountEmail: 'owner@example.test', planType: 'unknown' };
  emit();
  assert.match(text(), /요금제 확인 안 됨/);
  assert.match(text(), /사용 한도 확인 안 됨/);
  assert.doesNotMatch(text(), /0%/, 'no invented zero');

  settingsButton(card, 'Agent 관리').fire('click');
  assert.match(text(), /검증 담당예시/);
  assert.match(text(), /쉬는 Agent/);
  settingsNodes(card, node => node.dataset.profileId === 'review-verifier' && node.tagName === 'BUTTON')[0].fire('click');
  await settle();
  assert.match(text(), /사용 중 · 버전 2 사용 중 · 아직 쓰지 않은 초안 있음/);
  assert.ok(settingsButton(card, '사용 시작 (버전 3)'));

  // Delete asks first; a cancelled confirmation sends nothing.
  const before = calls.length;
  settingsButton(card, '삭제').fire('click');
  assert.equal(calls.length, before);

  settingsButton(card, '편집').fire('click');
  assert.match(text(), /Agent 편집/);
  const nameInput = document.getElementById(`${card.attributes.id}-profile-name`);
  assert.equal(nameInput.value, '검증 담당', 'the form opens on the newest saved draft');
  nameInput.value = '   ';
  nameInput.fire('input');
  settingsButton(card, '초안 저장').fire('click');
  await settle();
  assert.match(text(), /저장하지 못했습니다\. 아래 항목을 확인해 주세요\./);
  assert.match(text(), /담당자 이름을 입력해 주세요\./);
  assert.equal(calls.some(call => call[0] === 'PUT'), false, 'an invalid form never reaches the bridge');

  nameInput.value = '검증 담당 2';
  nameInput.fire('input');
  respond = (path, init) => {
    if (init.method === 'PUT') throw Object.assign(new Error('Profile changed since this edit started'), { status: 409, code: 'PROFILE_REVISION_CONFLICT' });
    if (path === '/profiles/review-verifier') return { ...verifier, headRevision: 4, head: { revision: 4, body: normalizeProfileBody({ name: '다른 곳에서 바꾼 이름' }) } };
    return null;
  };
  document.getElementById(`${card.attributes.id}-profile-name`).value = '검증 담당 2';
  document.getElementById(`${card.attributes.id}-profile-name`).fire('input');
  settingsButton(card, '초안 저장').fire('click');
  await settle();
  const put = calls.find(call => call[0] === 'PUT');
  assert.equal(put[1], '/profiles/review-verifier/draft');
  assert.equal(put[2].expectedRevision, 3);
  assert.equal(put[2].body.name, '검증 담당 2');
  assert.match(text(), /다른 곳에서 바뀌었습니다\. 최신 내용을 불러왔습니다\./);
  assert.equal(document.getElementById(`${card.attributes.id}-profile-name`).value, '다른 곳에서 바꾼 이름');
  settingsButton(card, '내 수정 다시 넣기').fire('click');
  assert.equal(document.getElementById(`${card.attributes.id}-profile-name`).value, '검증 담당 2');

  // A catalog without the store says so instead of an empty, working-looking list.
  respond = null;
  settingsButton(card, '취소').fire('click');
  await settle();
  settingsButton(card, '← Agent 목록').fire('click');
  catalog = { status: 'unavailable', profiles: [] };
  emit();
  assert.match(text(), /Agent 저장소에 연결하지 못했습니다/);
  card._cleanup();
  assert.equal(listeners.size, 0, 'closing the card stops listening');
});

// ============ Canvas marks, Board regions and the Board in view ============
const surfaceCss = readFileSync(new URL('../overlay/CSS/eg-desk-surface.uc.css', import.meta.url), 'utf8');

function windowBoardMetadataHarness() {
  const document = settingsFakeDocument(), create = document.createElement;
  document.getElementById = id => settingsNodes(document.documentElement, node => node.id === id)[0] || null;
  document.createElement = tag => {
    const node = create(tag);
    Object.defineProperty(node, 'id', { get: () => node.getAttribute('id') || '', set: value => node.setAttribute('id', value) });
    node.removeAttribute = key => { delete node.attributes[key]; };
    node.closest = () => null;
    node.prepend = child => { node.appendChild(child); node.children.unshift(node.children.pop()); };
    const classNames = () => node.className.split(/\s+/).filter(Boolean);
    node.classList = { contains: name => classNames().includes(name),
      add: (...names) => { node.className = [...new Set([...classNames(), ...names])].join(' '); },
      remove: (...names) => { node.className = classNames().filter(name => !names.includes(name)).join(' '); },
      toggle: (name, force) => { const on = force ?? !classNames().includes(name); node.classList[on ? 'add' : 'remove'](name); return on; } };
    node.click = () => node.fire('click');
    node.querySelector = () => null;
    node.getBoundingClientRect = () => ({ left: 0, top: 0, right: 24, bottom: 24, width: 24, height: 24 });
    return node;
  };
  document.querySelectorAll = selector => settingsNodes(document.documentElement, node => {
    const classes = node.className.split(/\s+/);
    if (selector === '.egd-desk-window') return classes.includes('egd-desk-window');
    if (selector === '.egd-memo-card') return classes.includes('egd-memo-card');
    if (selector === '.egd-canvas-card, .egd-canvas-shape') return classes.includes('egd-canvas-card') || classes.includes('egd-canvas-shape');
    return false;
  });
  document.querySelector = selector => document.querySelectorAll(selector)[0] || null;
  const listeners = new Map(), effects = { focus: 0, fullscreen: 0, dirty: 0, saved: 0, failWrite: false, deskSaves: 0, activations: [] };
  const window = { addEventListener: (type, fn) => listeners.set(type, fn), removeEventListener() {} };
  class ResizeObserver { observe() {} disconnect() {} }
  const a = { id: 'board-a', boardId: 'logical-a', title: '같은 이름', members: [{ viewId: 'owned' }, { viewId: 'restored-real' }] };
  const b = { id: 'board-b', boardId: 'logical-b', title: '같은 이름', members: [] };
  const state = { boards: { projections: { [a.id]: a, [b.id]: b }, activeProjectionId: b.id },
    activeEntityId: 'existing-selection', agenda: { activeAgendaId: b.boardId }, codex: { activeThreadId: 'existing-run' },
    pan: { x: 13, y: 14 }, zoom: 0.8, surface: { restoring: false }, sourceRefs: { cardsByKey: {} } };
  const store = { agendas: {}, meta: {} };
  let api, spawned = 0;
  const deps = { document, window, state, MinimapLayout, ResizeObserver, DESK_WINDOW_RESIZE_HITS: [], cardSeq: 0, queueMicrotask, console, TAG: 'test',
    deskIcon: () => document.createElement('i'),
    markAgendaDirty: () => effects.dirty++, setActiveEntity: view => { effects.activations.push(view); state.activeEntityId = view?.id || null; },
    focusCanvasCard: () => effects.focus++, toggleCardFullscreen: () => effects.fullscreen++, closeCanvasCard: () => {},
    isCardFullscreen: () => false, canvasZoom: () => 1, syncBoardRegionMarks: () => {}, scheduleViewportBoardSync: () => {},
    buildBoardRegionProjectChip: () => document.createElement('button'), syncBoardRegionProject: () => {},
    persistentEntityGeometry: view => view?.geometry || ({ x: 0, y: 0, width: 300, height: 200 }),
    MemoState: Memo, BoardMembership, cardLabelForViewportRail: view => view.title || view.id,
    normalizeBrowserNavigationUri: value => value, resolveFloatingMenuPlacement: () => ({ left: 0, top: 24 }),
    SurfaceState: { ...Surface, boardRegionRect: () => ({ x: 0, y: 0, width: 400, height: 300 }), placeCanvasView: () => ({ x: 0, y: 0 }) },
    coerceAgendaStore: () => store, writeAgendaStoreAndSync: next => {
      effects.saved++; if (effects.failWrite) return false; Object.assign(store, next); return true;
    }, syncViewportAgendaRail: () => {}, cloneJson: value => structuredClone(value),
    spawnBrowserCard: () => { const view = api.spawnDeskWindowShell({ id: `spawned-${++spawned}`, kind: 'browser', className: 'egd-browser-card', activate: false }).root;
      view._xulBrowser = { live: true }; return view; },
    spawnMemoCard: ({ record }) => {
      const view = api.spawnDeskWindowShell({ id: `spawned-${++spawned}`, kind: 'memo', className: 'egd-memo-card', activate: false }).root;
      view._memoRecord = Memo.normalizeMemoRecord(record, { now: 1 });
      const badge = document.createElement('span'); badge.className = 'egd-memo-anchor'; view.appendChild(badge);
      view.querySelector = selector => selector === '.egd-memo-anchor' ? badge : null;
      api.syncMemoCardPosition(view);
      return view;
    },
    applyPersistentEntityGeometry: (view, geometry) => {
      view.geometry = geometry;
      if (Number.isFinite(geometry?.x)) view.style.left = `${geometry.x}px`;
      if (Number.isFinite(geometry?.y)) view.style.top = `${geometry.y}px`;
    },
    selectBoardProjection: () => {}, scheduleDeskSessionSave: () => effects.deskSaves++, safeViewportWorldRect: () => ({}),
    boardNotice: () => {}, RecoveryState: Recovery, refreshDeskMinimap: () => {}, activeBoardProjection: () => null };
  const names = ['el', 'normalizeSourcePart', 'sourceRefKey', 'registerSourceRefCard', 'unregisterSourceRefCard', 'bindCardSourceRef',
    'deskWindowBoardIndex', 'syncDeskWindowBoardMetadata', 'syncAllDeskWindowBoardMetadata',
    'refreshBoardRegion', 'retargetRestoredEntityId', 'installCardHeaderFullscreenToggle', 'spawnDeskWindowShell',
    'normalizeAgendaTitle', 'renameAgenda', 'allocateRestoredEntityId', 'canRemapRestoredBoardMember',
    'syncRestoredMemoReferences', 'remapRestoredBoardMember', 'remapRestoredProjectionIds', 'mountBoardMember', 'openBoardSnapshot',
    'memoCards', 'memoAnchorCandidates', 'memoTargetLabel', 'syncMemoCardPosition',
    'cleanSourceRef', 'cardKindForPersistence', 'runtimeStateForCard', 'serializeCardState',
    'applyBoardMembershipPatches', 'bindViewToBoard', 'unbindViewFromBoard', 'markBoardMembershipDirty', 'viewBoardRecord',
    'addViewToBoard', 'removeViewFromBoard', 'dismissBoardMembershipSuggestion', 'closeBoardRegionMenu', 'toggleViewBoardMenu',
    'canRestoreDeskSnapshotIdentity', 'restoreDeskSession'];
  const source = names.map(declaration);
  assert.ok(source.every(Boolean));
  api = compileFunction(`let boardRegionMenu = null; const recentBoardProjectionIds = [];\n${source.join('\n')}\nreturn { bindCardSourceRef, spawnDeskWindowShell, refreshBoardRegion, retargetRestoredEntityId, renameAgenda, remapRestoredBoardMember, mountBoardMember, openBoardSnapshot, canRestoreDeskSnapshotIdentity, restoreDeskSession, syncMemoCardPosition, toggleViewBoardMenu, serializeCardState };`,
    Object.keys(deps))(...Object.values(deps));
  // Runtime wiring stays callable without becoming fixture snapshot data.
  Object.defineProperty(state, 'toggleViewBoardMenu', {
    value: api.toggleViewBoardMenu, writable: true, configurable: true, enumerable: false,
  });
  const canvas = document.createElement('div'); canvas.id = 'egd-canvas-layer'; document.documentElement.appendChild(canvas);
  for (const projection of [a, b]) {
    const region = document.createElement('section'); region.id = projection.id; document.documentElement.appendChild(region);
  }
  return { ...api, document, window, listeners, effects, state, store, a, b };
}

test('window Board harness keeps runtime menu wiring callable without polluting state snapshots', () => {
  const h = windowBoardMetadataHarness();
  assert.equal(typeof h.state.toggleViewBoardMenu, 'function');
  assert.equal(h.state.toggleViewBoardMenu, h.toggleViewBoardMenu);
  assert.equal(Object.prototype.propertyIsEnumerable.call(h.state, 'toggleViewBoardMenu'), false);
  const snapshot = structuredClone(h.state);
  assert.deepEqual(h.state, snapshot);
  h.a.title = 'changed Board';
  assert.notDeepEqual(h.state, snapshot, 'full-state comparisons still detect enumerable data changes');
  assert.equal(snapshot.boards.projections[h.a.id].title, '같은 이름');
});

test('window Board metadata follows recorded IDs across rename, membership and restore without changing selection', () => {
  const h = windowBoardMetadataHarness();
  const focus = h.document.createElement('textarea'); h.document.documentElement.appendChild(focus); focus.focus();
  const owned = h.spawnDeskWindowShell({ id: 'owned', kind: 'browser', activate: false });
  const unowned = h.spawnDeskWindowShell({ id: 'unowned', kind: 'file', activate: false });
  owned.root.dataset.projectionId = h.b.id; owned.root.style.left = '600px';
  assert.equal(owned.boardMetadata.textContent, '같은 이름');
  assert.equal(unowned.boardMetadata.hidden, true, 'the active or nearby Board does not own an unrecorded View');
  assert.equal(owned.boardMetadata.getAttribute('role'), 'note');
  assert.equal(owned.boardMetadata.getAttribute('aria-label'), '소속 Board: 같은 이름');
  assert.equal(owned.boardMetadata.getAttribute('tabindex'), null);
  assert.equal(owned.boardMetadata.title, '같은 이름');
  assert.equal(owned.slots.topbar.children.indexOf(owned.boardMetadata), owned.slots.topbar.children.indexOf(owned.slots.identity) + 1);
  h.effects.dirty = 0;
  h.renameAgenda(h.b.boardId, '다른 B');
  assert.equal(owned.boardMetadata.textContent, '같은 이름', 'duplicate titles do not determine ownership');
  h.renameAgenda(h.a.boardId, '긴 Board 이름 '.repeat(30));
  assert.equal(owned.boardMetadata.textContent, h.a.title);
  assert.equal(owned.boardMetadata.title, h.a.title, 'the full name remains available on hover');
  h.a.members = h.a.members.filter(member => member.viewId !== 'owned');
  h.b.members.push({ viewId: 'owned' }); h.refreshBoardRegion(h.a);
  assert.equal(owned.boardMetadata.textContent, '다른 B', 'a membership update refreshes the same View');
  h.a.members.push({ viewId: 'owned' }); h.refreshBoardRegion(h.a);
  assert.equal(owned.boardMetadata.hidden, true, 'conflicting legacy membership is never guessed');
  const restored = h.spawnDeskWindowShell({ id: 'temporary', kind: 'file', activate: false });
  assert.equal(restored.boardMetadata.hidden, true);
  h.retargetRestoredEntityId(restored.root, 'restored-real');
  assert.equal(restored.root.id, 'restored-real');
  assert.equal(restored.boardMetadata.textContent, h.a.title, 'restore resolves only after the final View ID');
  assert.equal(h.document.activeElement, focus);
  assert.deepEqual([h.state.activeEntityId, h.state.boards.activeProjectionId, h.state.codex.activeThreadId],
    ['existing-selection', 'board-b', 'existing-run']);
  assert.deepEqual([h.state.pan, h.state.zoom], [{ x: 13, y: 14 }, 0.8]);
  assert.equal(h.effects.focus, 0); assert.equal(h.effects.fullscreen, 0);
  assert.deepEqual(h.effects.activations, [], 'metadata never activates a View');
  assert.equal(h.effects.dirty, 1, 'only the explicitly created restore shell marked dirty');
  assert.equal(h.effects.saved, 2, 'only the two explicit Board renames write their store');
});

