test('File-only compact focus uses the real existing camera transition, retaining world/Board geometry and readable cards', () => {
  const projectionBody = surfaceSource.match(/    const focusProjection = \(entry, \{ revealHeader = false \} = \{\}\) => \{([\s\S]*?)\n    \};/)?.[1];
  const fileBody = surfaceSource.match(/    const focusFileDockIfCompact = card => \{([\s\S]*?)\n    \};/)?.[1];
  const screenBody = surfaceSource.match(/    const screenRect = \(card, zoom, pan\) => \{([\s\S]*?)\n    \};/)?.[1];
  assert.ok(projectionBody && fileBody && screenBody);
  const card = { id: 'file', isConnected: true, hidden: false,
    classList: { contains: name => name === 'egd-file-card' },
    style: { left: '500px', top: '300px', width: '900px', height: '620px' } };
  const worldBefore = { ...card.style };
  const savedBoard = { members: [{ viewId: card.id, geometry: { x: 500, y: 300, width: 900, height: 620 } }], camera: { zoom: 0.71, pan: { x: 10, y: 20 } } };
  const savedBefore = structuredClone(savedBoard);
  const state = { activeEntityId: card.id, panModifier: false, surface: { restoring: false }, agenda: { restoreInProgress: false },
    zoom: 0.71, zoomTarget: 0.71, pan: { x: 10, y: 20 }, panTarget: { x: 10, y: 20 } };
  const previousCamera = { zoom: state.zoom, pan: { ...state.pan } };
  const safe = { left: 88, top: 76, right: 1188, bottom: 676, width: 1100, height: 600 };
  const entries = new Map([[card, { card, kind: 'file', bodyFontPx: 13, level: 'outline' }]]);
  const entry = entries.get(card), cameraTargets = [], focused = [];
  state.setCanvasViewportTarget = target => { cameraTargets.push(target); state.zoomTarget = target.zoom; state.panTarget = { ...target.pan }; };
  const parsePxNumber = (value, fallback = 0) => Number.parseFloat(value) || fallback;
  const screenRect = compileFunction('return (card, zoom, pan) => {' + screenBody + '};', ['parsePxNumber'])(parsePxNumber);
  const authorVisible = current => !current.card.hidden;
  const focusProjection = compileFunction('return (entry, { revealHeader = false } = {}) => {' + projectionBody + '};',
    ['state', 'authorVisible', 'screenRect', 'safeViewportRect', 'SurfaceState', 'ZOOM_MAX', 'detailWidth', 'detailHeight', 'focusCanvasCard'])(
    state, authorVisible, screenRect, () => safe, Surface, 4, 240, 180, target => focused.push(target));
  const focus = compileFunction('return card => {' + fileBody + '};',
    ['state', 'syncEntries', 'entries', 'authorVisible', 'screenRect', 'SurfaceState', 'detailWidth', 'detailHeight', 'isCardFullscreen', 'focusProjection'])(
    state, () => {}, entries, authorVisible, screenRect, Surface, 240, 180, () => false, focusProjection);
  state.zoomTarget = .5;
  assert.equal(focus(card), true, 'the File Dock action still requests readable focus at 50% even while the Card is detailed');
  assert.ok(state.zoomTarget >= 10.6 / 13, 'the action retains its readable font target');
  cameraTargets.length = 0;
  focused.length = 0;
  state.zoomTarget = previousCamera.zoom;
  state.panTarget = { ...previousCamera.pan };
  assert.equal(focus(card), true);
  assert.equal(cameraTargets.length, 1);
  assert.deepEqual(focused, [card], 'the same File View is focused');
  assert.equal(surfaceSemanticLevel({ width: 900 * state.zoomTarget, height: 620 * state.zoomTarget, fontPx: 13 * state.zoomTarget,
    previous: 'outline', detailWidth: 240, detailHeight: 180 }), 'detail');
  assert.ok(state.panTarget.y + 300 * state.zoomTarget >= safe.top, 'the existing revealHeader route keeps controls reachable');
  assert.deepEqual(card.style, worldBefore, 'no position, dimensions, transform or temporary cap rewrite');
  assert.deepEqual(savedBoard, savedBefore, 'saved Board layout and camera are not rewritten');
  assert.deepEqual({ zoom: state.zoom, pan: state.pan }, previousCamera, 'the transition begins from the prior camera, without a direct reset');
  assert.equal(focus(card), false, 'a pending readable target needs no second transition');
  assert.equal(cameraTargets.length, 1);
  state.zoomTarget = 0.71; state.panTarget = { ...previousCamera.pan };
  card.hidden = true; assert.equal(focus(card), false); card.hidden = false;
  for (const kind of ['chat', 'browser', 'terminal']) {
    const other = { ...card, classList: { contains: name => name === 'egd-' + kind + '-card' } };
    assert.equal(focus(other), false, 'not an all-card policy: ' + kind);
  }
  state.surface.restoring = true; assert.equal(focus(card), false);
  assert.equal(cameraTargets.length, 1);
});

// The actual Surface panel, real retained-output modules and scoped bridge
// adapter together. No provider, OS input, network listener or filesystem open.
function activityDetailsHarness({ fetchRead, approval = true, openFile } = {}) {
  const document = requestProjectDOM();
  const thread = { id: 'room-original', clientBindingId: 'binding-original', conversationId: 'conversation / original', engineId: 'codex', messages: [] };
  const command = { id: 'command / original', kind: 'commandExecution', title: '명령 실행', status: 'completed',
    detail: { command: 'node --test', cwd: '/not-authority', exitCode: 0, durationMs: 1250 } };
  const change = { id: 'change / original', kind: 'fileChange', title: '파일 변경', status: 'completed', detail: { text: '보존된 변경' } };
  const pending = { approvalId: 'approval-original', itemId: 'approval-item-original', kind: 'fileChange', status: 'pending',
    choices: ['accept', 'decline'], reason: '확인할 변경', paths: ['/not-authority/code.js'] };
  const run = { conversationId: thread.conversationId, runId: 'run / original', clientThreadId: thread.clientBindingId, localThreadId: thread.id,
    status: 'inProgress', messages: [], activities: [command, change], pendingApprovals: approval ? [pending] : [], pendingUserInputs: [], subAgents: [] };
  const protocol = Chat.createChatProtocolState();
  protocol.runs[Chat.runKey(run.conversationId, run.runId)] = run;
  const state = { codex: { threads: [thread], activeThreadId: thread.id, activityThreadId: thread.id, chatProtocol: protocol } };
  const calls = [], decisions = [], scopes = [];
  const epochScope = Chat.createChatEpochScope();
  const packet = target => ({ protocolVersion: 1, ...target, retained: true, complete: true,
    head: '', tail: '# tests 2\n# pass 2\n# fail 0\n', totalBytes: 31, omittedBytes: 0 });
  const changes = target => ({ protocolVersion: 1, conversationId: target.conversationId, runId: target.runId, retained: true,
    items: [{ itemId: target.itemId, status: 'completed', files: [{ path: '/not-authority/code.js', kind: 'update',
      diff: '@@ -1 +1 @@\n-old\n+kept change\n', omitted: null }] }], turn: null });
  const fetchJson = async (path, options) => {
    const url = new URL(path, 'http://unused.invalid');
    const target = Object.fromEntries(url.searchParams);
    calls.push({ path, options, target });
    assert.equal(options.method, 'GET');
    assert.equal(Object.hasOwn(options, 'body'), false);
    assert.ok(['/chat/command-output', '/chat/run-changes', '/chat/run-project-origin'].includes(url.pathname));
    return fetchRead ? fetchRead(url.pathname, target, options) : url.pathname === '/chat/command-output' ? packet(target)
      : url.pathname === '/chat/run-project-origin' ? { protocolVersion: 1, ...target, status: 'unavailable', verified: false } : changes(target);
  };
  const deps = { state, document, window: { AbortController }, ChatState: Chat, ChatRunResult, ChatChangeReview, InputContext,
    cloneJson: value => JSON.parse(JSON.stringify(value)),
    pruneUserInputDrafts() {}, contextResolverRecordSection: () => null, codexSubAgentSection: () => null,
    formatMessageTime: () => '', queueMicrotask, openChatFileReference: () => assert.fail('no inferred FileView authority'),
    openVerifiedRunFile: request => openFile ? openFile(request) : assert.fail('no verified file opening requested by this fixture'),
    codexUserInputBlock: () => assert.fail('this fixture has no Agent answer'), userInputDrafts: new Map(), userInputDraftKey: () => '' };
  const names = ['el', 'getCodexThreadById', 'codexRuns', 'codexRunLabel', 'openCodexActivityPanel', 'codexActivityDetailTarget',
    'codexCommandInfo', 'createCodexActivityReadScope', 'replaceCodexActivityDetails', 'createCodexActivityDetailsView', 'renderCodexActivityPanel'];
  for (const name of ['briefingInputReferences', 'acceptedInputReceipt', 'visibleInputAnswer', 'historyReadReferenceCurrent', 'inputDeliveryProof']) {
    if (surfaceSource.includes(`  function ${name}(`)) names.push(name);
  }
  const api = compileFunction('let activityPanelComposing = false, activityPanelDeferred = false, activityDetailsGeneration = 0, activityDetailsView = null;\n'
    + names.map(declaration).join('\n') + '\nreturn { ' + names.join(', ') + ', generation: () => activityDetailsGeneration };', Object.keys(deps))(...Object.values(deps));
  const bridgeFactory = requestProjectBridgeMethod('createActivityReadScope', { createCodexActivityReadScope: api.createCodexActivityReadScope, epochScope, fetchJson });
  state.codexBridge = { createActivityReadScope: (...args) => { const scope = bridgeFactory(...args); scopes.push(scope); return scope; },
    replyApproval: request => decisions.push(request), refreshConversation: () => assert.fail('no implicit conversation refresh') };
  const panel = () => document.getElementById('egd-codex-activity-panel');
  const result = () => panel().testid('chat-command-result');
  return { ...api, state, document, thread, run, command, change, pending, calls, decisions, scopes, epochScope, packet, changes, panel, result,
    async openResult() { await result().querySelector('button').click(); },
    async openChanges(kind = 'activity') { const node = panel().testid(kind === 'approval' ? 'chat-approval-changes' : 'chat-activity-changes'); await node.querySelector('summary').click(); return node; },
  };
}

test('first-send Activity delivery control shows only a receipt for the visible answer', async t => {
  for (const scenario of ['verified A', 'unrelated B packet', 'missing accepted receipt', 'wrong account']) await t.test(scenario, async () => {
    // The production Activity renderer and production inspector share state;
    // their small synthetic documents are separate to reuse both fixtures.
    const input = await firstSendThroughActualBridge({ hasAReceipt: scenario !== 'unrelated B packet',
      acceptedUserId: scenario !== 'missing accepted receipt' });
    const activity = activityDetailsHarness({ approval: false });
    activity.state.codex = input.state.codex; activity.state.codex.activityThreadId = input.thread.id;
    activity.state.codexBridge.inspectInput = (...args) => input.bridge.inspectInput(...args);
    if (scenario === 'unrelated B packet') {
      input.run.contextPackets = [{ packetId: input.packetB.packetId, sourceId: input.capture.sourceId,
        receiptId: 'receipt-b', hash: input.packetB.hash, mode: input.packetB.mode,
        coverage: input.packetB.coverage, deliveryStatus: input.packetB.deliveryStatus }];
    } else if (scenario === 'missing accepted receipt') assert.notEqual(input.user.localMessageId, 'local-message-a');
    else if (scenario === 'wrong account') input.state.codex.authStatus.accountEmail = 'other@example.test';
    activity.renderCodexActivityPanel();
    const panel = activity.panel(), buttons = panel.querySelectorAll('[data-testid="chat-delivered-input-open"]');
    if (scenario !== 'verified A') {
      assert.equal(buttons.length, 0, 'an unverified packet must not become an A delivery control');
      assert.equal(panel.textContent.includes('packet-b'), false); assert.equal(input.observed.length, 0);
    } else {
      assert.equal(buttons.length, 1, 'the visible answer retains its own positive control');
      assert.equal(Object.hasOwn(buttons[0].dataset, 'packetId'), false, 'the packet identifier is not exposed before verification');
      await buttons[0].click(); await input.inspections.at(-1); await settle();
      const inspector = input.document.getElementById('egd-codex-input-panel'); assert.ok(inspector);
      const rendered = inspectorRenderedData(inspector);
      assert.ok(rendered.includes(input.packetA.text), `A packet is missing; synthetic reads: ${JSON.stringify(input.observed.map(row => [row.request, row.body.delivered?.packetId]))}; notices: ${JSON.stringify(input.notices)}; panel: ${rendered.slice(0, 1200)}`);
      assert.equal(/packet-b|conversation-b\/run-b/.test(rendered) || rendered.includes(input.packetB.text), false,
        'a source page may contain B\'s words, but B\'s packet and identity are not A\'s delivery');
      await input.settleTracking(); input.close();
    }
    assert.equal(JSON.stringify(input.user.inputReferences[0]), input.originalJson);
  });
});

