function profileTransferBridgeMethods(fetchJson, epochScope) {
  const method = signature => {
    const start = surfaceSource.indexOf(`      ${signature}`), end = surfaceSource.indexOf('\n      },', start);
    assert.ok(start >= 0 && end > start); return surfaceSource.slice(start, end + 8);
  };
  return compileFunction(`return { ${method('async profileRequest(')}, ${method('createProfileTransferScope(')} };`, ['fetchJson', 'epochScope'])(fetchJson, epochScope);
}

function portableSettingsHarness({ respond, fullscreen = false, initialDetail = null, loggedOut = false } = {}) {
  const document = settingsFakeDocument(), native = nativeTextGlueHarness(), calls = [], listeners = new Set();
  if (fullscreen) {
    const decorate = node => {
      Object.defineProperty(node, 'id', { get: () => node.getAttribute('id') });
      const names = () => node.className.split(/\s+/).filter(Boolean);
      node.classList = { contains: name => names().includes(name),
        add: (...values) => { node.className = [...new Set([...names(), ...values])].join(' '); },
        remove: (...values) => { node.className = names().filter(name => !values.includes(name)).join(' '); } };
      node.click = () => node.fire('click'); return node;
    };
    const create = document.createElement; document.createElement = tag => decorate(create(tag)); decorate(document.documentElement);
  }
  const epoch = Chat.createChatEpochScope(), state = { codex: { connected: true, codexAccountKey: 'account-a', authStatus: { isLoggedIn: true, accountEmail: 'a@example.test' } } };
  if (loggedOut) Object.assign(state.codex, { codexAccountKey: null, authStatus: { isLoggedIn: false } });
  const body = normalizeProfileBody({ name: '보이는 Agent', role: '검토', instructions: 'Visible revision instructions.' });
  const detail = initialDetail || { id: 'visible-agent', lifecycle: 'active', activeRevision: 2, headRevision: 3, hasDraft: true,
    active: { revision: 2, hash: profileHash(body), body }, head: { revision: 3, hash: 'b'.repeat(64), body: { ...body, name: '숨은 새 초안' } } };
  const catalog = () => ({ status: 'ready', profiles: [{ id: detail.id, name: body.name, role: body.role, lifecycle: 'active', activeRevision: detail.activeRevision, headRevision: detail.headRevision }] });
  let refreshes = 0;
  const methods = profileTransferBridgeMethods(async (path, options = {}) => {
    calls.push({ path, ...options });
    if (respond) { const custom = respond(path, options); if (custom !== undefined) return custom; }
    if (path === '/profiles/visible-agent') return structuredClone(detail);
    if (path === '/profiles/visible-agent/revisions') return { revisions: [] };
    if (path === '/profiles/import') {
      const input = JSON.parse(options.body), parsed = importAgentFile(input.text, { filename: input.filename });
      if (input.dryRun) return { dryRun: true, ...parsed };
      const hash = profileHash(parsed.body), id = 'imported-agent';
      return { id, revision: 1, hash, unchanged: false, preview: parsed.preview, profile: { id, lifecycle: 'draft', activeRevision: null, active: null,
        reviewRequired: true, headRevision: 1, hasDraft: true, head: { profileId: id, revision: 1, hash, body: parsed.body } } };
    }
    const url = new URL(path, 'http://fixture.invalid');
    if (url.pathname === '/profiles/visible-agent/export') return { profileId: detail.id, revision: Number(url.searchParams.get('revision')), hash: detail.active.hash,
      ...exportAgentFile(body, url.searchParams.get('format')) };
    throw Object.assign(new Error('unexpected route'), { status: 404, code: 'NOT_FOUND' });
  }, epoch);
  state.codexBridge = { ...methods, profileCatalog: catalog, loadProfiles: async () => { refreshes++; }, subscribe(fn) { listeners.add(fn); fn(); return () => listeners.delete(fn); } };
  const el = compileFunction(`${declaration('el')}\nreturn el;`, ['document'])(document);
  const codexProfileAvatar = compileFunction(`${declaration('codexProfileAvatar')}\nreturn codexProfileAvatar;`, ['document', 'el', 'ChatState'])(document, el, Chat);
  const deps = { singletonSourceRef: () => ({ kind: 'settings-card' }), focusOpenSourceCard: () => null, cardSeq: 0,
    resolveCanvasCardPlacement: () => ({ x: 0, y: 0, width: 600, height: 600 }), revealPlacedCanvasCard() {}, el, cardZ: 0, closeCanvasCard() {}, state, ChatState: Chat,
    codexProfileAvatar, document, window: { setTimeout: () => 0, confirm: () => false }, bindCardSourceRef() {}, markAgendaDirty() {}, setActiveEntity() {},
    isCardFullscreen: () => false, focusCanvasCard() {}, installCardHeaderFullscreenToggle() {}, canvasZoom: () => 1, ...settingsTransferDeps(document, state, native.adapter),
    AccountSettingsView, codexBridgeNotice: settingsBridgeNotice, deskIcon: settingsDeskIcon(document) };
  if (fullscreen) {
    Object.assign(state, { cardFullscreen: null, surface: { initialBrowserFocus: false }, pan: { x: 0, y: 0 }, zoom: 1,
      setCanvasViewportTarget(camera) { this.pan = { ...camera.pan }; this.zoom = camera.zoom; } });
    const fullDeps = { state, document, cardZ: 0, canvasZoom: () => 1, parsePxNumber: Number.parseFloat, SurfaceState: Surface, ZOOM_MAX: 4,
      safeViewportRect: () => ({ left: 10, top: 10, width: 980, height: 680 }),
      setActiveEntity: card => { state.activeEntityId = card?.id; }, syncViewportAgendaRail() {}, syncHudViewportFit() {},
      closeDeskMinimap() {}, toggleDeskMinimap() {}, scheduleDeskSessionSave() {}, toggleHUD() {} };
    const source = ['isCardFullscreen', 'getCardRect', 'applyCardRect', 'setHudPresentationHidden', 'syncCardFullscreenLayout',
      'enterCardFullscreen', 'exitCardFullscreen', 'restoreHudAfterCardFullscreen', 'toggleCardFullscreen'].map(declaration).join('\n');
    Object.assign(deps, compileFunction(`${source}\nreturn { isCardFullscreen, toggleCardFullscreen };`, Object.keys(fullDeps))(...Object.values(fullDeps)));
  }
  const spawn = compileFunction(`${declaration('spawnSettingsCard')}\nreturn spawnSettingsCard;`, Object.keys(deps))(...Object.values(deps));
  const card = spawn({ tab: 'agents', profileId: detail.id });
  const part = id => settingsNodes(card, node => node.dataset.testid === id)[0];
  const emit = () => { for (const fn of listeners) fn(); };
  const pickImport = async sourceOverride => {
    const text = sourceOverride ?? '---\nname: reviewer\ndescription: Checks work\ntools: Read, MagicTool\ncolor: orange\nunknownFlag: keep-warning\n---\nFull instructions <literal>.\n';
    native.files.set('/chosen/reviewer.md', new TextEncoder().encode(text));
    part('settings-agent-import').fire('click'); native.pickers.at(-1).answer(0, '/chosen/reviewer.md'); await settle();
    return text;
  };
  return { card, state, detail, calls, native, part, emit, epoch, document, pickImport, refreshes: () => refreshes };
}

async function duplicateSettingsHarness(t, { reply, lifecycle = 'active', loggedOut = false } = {}) {
  const [{ openProfileStore }, { handleProfileHttp }, { createPrivateQaTempDirectory }] = await Promise.all([
    import('../helper/egdesk-profile-store.mjs'), import('../helper/egdesk-profile-http.mjs'), import('./egdesk-qa-platform.mjs')]);
  const dataDir = createPrivateQaTempDirectory('egdesk-settings-duplicate-');
  const store = openProfileStore({ dataDir, ownerHash: 'duplicate-owner' });
  t.after(() => { store.close(); rmSync(dataDir, { recursive: true, force: true }); });
  const created = store.createDraft({ name: '표시할 Agent', role: '원본 역할', instructions: 'VERSION_ONE' });
  const sourceId = created.id;
  store.saveDraft(sourceId, { ...created.profile.head.body, instructions: 'SHOWN_VERSION_TWO' }, 1);
  if (lifecycle !== 'draft') store.activate(sourceId, 2, null);
  store.saveDraft(sourceId, { ...created.profile.head.body, instructions: 'STORED_HEAD_THREE' }, 2);
  if (lifecycle === 'archived') store.lifecycle(sourceId, 'archive');
  const before = store.get(sourceId);
  const h = portableSettingsHarness({ initialDetail: before, loggedOut, respond: async (path, options = {}) => {
    const req = Readable.from(options.body === undefined ? [] : [Buffer.from(options.body)]);
    Object.assign(req, { method: options.method || 'GET', url: path, socket: { remoteAddress: '127.0.0.1' },
      headers: { host: '127.0.0.1:39218', ...(options.body === undefined ? {} : { 'content-type': 'application/json' }) } });
    let response;
    assert.equal(await handleProfileHttp(req, new URL(path, 'http://127.0.0.1:39218'), { store,
      send: (status, body) => { response = { status, body }; } }), true);
    if (response.status >= 400) throw Object.assign(new Error('Profile request refused'), { status: response.status, ...response.body });
    return path.endsWith('/duplicate') && reply ? reply(response.body) : response.body;
  } });
  await settle();
  return { ...h, store, sourceId, before: structuredClone(before), posts: () => h.calls.filter(call => call.method === 'POST') };
}

test('Settings duplicate: explicit displayed v2 goes through real HTTP/store into a new unused draft; original and room choice stay unchanged', async t => {
  const h = await duplicateSettingsHarness(t);
  h.state.codex.threads = [{ id: 'room-copy', engineId: 'codex', assignedAgentProfileId: h.sourceId }];
  h.state.codex.activeThreadId = 'room-copy'; const room = structuredClone(h.state.codex.threads);
  const control = h.part('settings-agent-duplicate');
  assert.equal(control.textContent, '복제해서 새로 만들기'); assert.equal(control.getAttribute('type'), 'button');
  assert.deepEqual([control.dataset.profileId, control.dataset.revision, control.dataset.state], [h.sourceId, '2', 'idle']);
  assert.deepEqual([h.part('settings-agent-detail').dataset.profileId, h.part('settings-agent-detail').dataset.revision], [h.sourceId, '2']);
  assert.equal(h.posts().length, 0); assert.equal(h.detail.headRevision, 3);
  control.fire('click'); control.fire('click'); h.part('settings-agent-duplicate').fire('click');
  assert.equal(h.part('settings-agent-duplicate').dataset.state, 'pending');
  assert.equal(h.part('settings-agent-duplicate').getAttribute('disabled'), 'true');
  await settle();
  assert.equal(h.posts().length, 1);
  assert.equal(h.posts()[0].path, `/profiles/${h.sourceId}/duplicate`);
  assert.deepEqual(JSON.parse(h.posts()[0].body), { revision: 2 });
  const shown = h.part('settings-agent-detail'), copied = h.store.get(shown.dataset.profileId);
  assert.notEqual(copied.id, h.sourceId); assert.deepEqual([shown.dataset.lifecycle, shown.dataset.revision], ['draft', '1']);
  assert.equal(copied.head.body.instructions, 'SHOWN_VERSION_TWO'); assert.equal(copied.activeRevision, null);
  assert.deepEqual(copied.source.at(-1).profileId, h.sourceId); assert.equal(copied.source.at(-1).revision, 2);
  assert.match(h.part('settings-agent-notice').textContent, /새 초안.*원본은 그대로.*아직 사용하거나 대화방에 배정하지 않았습니다/);
  assert.deepEqual(h.store.get(h.sourceId), h.before); assert.deepEqual(h.state.codex.threads, room);
  assert.equal(h.refreshes(), 1); assert.equal(h.calls.some(call => /\/(activate|lifecycle|draft)$/.test(call.path)), false);
});

