test('Agent personality UI: 409 shows latest head, retains the entire raw edit, and restoring it never resubmits', async () => {
  const h = await personalitySettingsHarness({ conflict: true }); h.edit();
  h.type(h.at('settings-agent-example-user'), '  내 질문  '); h.type(h.at('settings-agent-example-reply'), '내 답변\n둘째 줄');
  h.type(h.at('settings-agent-avoid-text'), '  내 금지 표현  '); h.type(h.field('speechNotes'), '내 메모');
  h.type(h.field('traits'), '미추가 특징'); h.type(h.field('expertise'), '미추가 할 일');
  settingsButton(h.card, '간결').fire('click');
  h.part('settings-agent-save').fire('click'); await settle();
  assert.equal(h.puts.length, 1); assert.equal(h.field('name').value, '다른 곳의 초안');
  assert.deepEqual(h.parts('settings-agent-example-user').map(node => node.value), ['새 질문']);
  assert.deepEqual(h.parts('settings-agent-avoid-text').map(node => node.value), ['새 표현']);
  assert.ok(h.part('settings-agent-restore-kept'));
  h.part('settings-agent-restore-kept').fire('click'); await settle(); h.emit(); await settle();
  assert.equal(h.puts.length, 1, 'restore is local only, with no automatic retry');
  assert.equal(h.field('name').value, '편집할 이름'); assert.equal(h.field('speechNotes').value, '내 메모');
  assert.equal(h.at('settings-agent-example-user').value, '  내 질문  ');
  assert.equal(h.at('settings-agent-example-reply').value, '내 답변\n둘째 줄');
  assert.equal(h.at('settings-agent-avoid-text').value, '  내 금지 표현  ');
  assert.match(h.part('settings-agent-form').textContent, /미추가 특징.*미추가 할 일/);
  assert.equal(settingsButton(h.card, '간결').getAttribute('aria-pressed'), 'true');
  assert.equal(h.detail.activeRevision, 2);
  assert.equal(h.calls.some(call => call.path.includes('/activate')), false);
});

test('Agent personality UI: long form keeps the existing inner scroller and visible sticky actions without reducing type size', () => {
  assert.equal(cssDeclarationsFor(surfaceCss, '.egd-settings-content')['overflow-y'], 'auto');
  assert.equal(cssDeclarationsFor(surfaceCss, '.egd-settings-content')['min-height'], '0');
  const actions = cssDeclarationsFor(surfaceCss, '.egd-settings-form-actions');
  assert.equal(actions.position, 'sticky'); assert.equal(actions.bottom, '0');
  assert.equal(cssDeclarationsFor(surfaceCss, '.egd-settings-personality-editor')['min-width'], '0');
  assert.equal(cssDeclarationsFor(surfaceCss, '.egd-settings-personality-list')['white-space'], 'pre-wrap');
  assert.equal(cssDeclarationsFor(surfaceCss, '.egd-settings-diff-values')['white-space'], 'pre-wrap');
  assert.match(surfaceCss, /font: 13px\/1\.45 var\(--egd-font\)/);
});

function productionTaskAnswerFactory() {
  return compileFunction(`${declaration('createChatTaskAnswers')}\nreturn createChatTaskAnswers;`, ['ChatState'])(Chat);
}

function taskQuestionGraph({ response = { kind: 'choice', options: [{ id: 'email', label: '메일로 보내기' }, { id: 'hold', label: '잠시 보관하기' }] },
  label = '어떤 방법으로 전달할까요?', status = 'waiting', graphId = 'graph-a', gateId = 'question', taskStatus = 'waiting-on-dependency' } = {}) {
  return awaitGraph({ graphId, tasks: [{ taskId: 'answer-task', status: taskStatus,
    gates: [{ gateId, kind: 'userAction', status, label, response }, { gateId: 'later-file', kind: 'file', root: 'root-1', relativeGlob: '*.pdf', status: 'waiting' }] }] });
}

function taskQuestionHarness(graph = taskQuestionGraph(), { boardKnown = true } = {}) {
  const document = settingsFakeDocument(), root = document.createElement('section'); document.documentElement.appendChild(root);
  const epochScope = Chat.createChatEpochScope(), requests = [], replies = [], graphReceipts = [];
  const thread = { id: 'room-a', clientBindingId: 'binding-a', engineId: 'codex', type: 'dm', profileEnabled: false, messages: [] };
  const state = { codex: { threads: [thread], activeThreadId: thread.id, codexAccountKey: 'account-a', authStatus: { isLoggedIn: true, accountEmail: 'a@example.test' },
    taskBoard: boardKnown ? Chat.taskBoardWithState(Chat.createTaskBoard(), awaitState(graph)) : Chat.taskBoardWithGraph(Chat.createTaskBoard(), graph),
    taskBoardOpen: true, taskContinue: null, taskApproval: null, taskResume: null, planProposals: Chat.createPlanProposals() } };
  const el = compileFunction(`${declaration('el')}\nreturn el;`, ['document'])(document);
  const renderer = compileFunction(`${declaration('renderChatTaskQuestion')}\n${declaration('renderChatTaskBoard')}\nreturn renderChatTaskBoard;`,
    ['ChatState', 'el', 'deskIcon'])(Chat, el, () => document.createElement('svg'));
  let api;
  const draw = () => { root.replaceChildren(renderer(state.codex, api.methods, () => '연결된 폴더')); };
  const start = surfaceSource.indexOf('    const taskStateReads = new Map();'), end = surfaceSource.indexOf('    const handleEvent = (event) => {', start);
  const methodsStart = surfaceSource.indexOf('      toggleTaskBoard() {'), methodsEnd = surfaceSource.indexOf("      // '다시 시도' after the quiet retries ran out", methodsStart);
  const emitBody = surfaceSource.match(/    const emit = \(\) => \{([\s\S]*?)\n    \};/)?.[1];
  const deps = { state, ChatState: Chat, epochScope, createChatTaskAnswers: productionTaskAnswerFactory(), document,
    getCodexThreadById: (codex, id) => codex.threads.find(thread => thread.id === id), codexThreadRuntimeConfig: () => ({}),
    normalizeThreads() {}, listeners: [() => { if (api) draw(); }], renderCodexActivityPanel() {}, scheduleDeskSessionSave() {},
    browserWorkflow: { graph: value => graphReceipts.push(value) },
    fetchJson: async (path, options = {}) => {
      requests.push({ path, method: options.method || 'GET', body: options.body && JSON.parse(options.body), signal: options.signal });
      const answer = replies.shift();
      if (answer instanceof Error) throw answer;
      return typeof answer === 'function' ? answer(path, options) : answer;
    } };
  Object.assign(deps, productionMemoReadWatch(deps));
  api = compileFunction(`let taskAnswers = null;\nconst emit = () => {${emitBody}\n};\n${surfaceSource.slice(start, end)}\nreturn { emit, taskGraphFrame, readTaskGraphs, methods: {\n${surfaceSource.slice(methodsStart, methodsEnd)}\n} };`, Object.keys(deps))(...Object.values(deps));
  draw();
  const parts = id => settingsNodes(root, node => node.dataset.testid === id);
  const part = id => parts(id)[0];
  const question = () => part('chat-task-condition');
  const draft = () => api.methods.taskAnswerDraft(graph.graphId, 'answer-task', graph.tasks[0].gates[0].gateId,
    Chat.taskGateView(Chat.taskBoardEntry(state.codex.taskBoard, graph.graphId).graph.tasks[0].gates[0]).responseKey);
  const type = value => { const input = part('chat-task-answer-text'); input.value = value; input.fire('input'); return input; };
  const choose = id => { const input = parts('chat-task-answer-choice').find(node => node.dataset.choiceId === id); input.checked = true; input.fire('change'); return input; };
  return { api, state, thread, root, document, epochScope, requests, replies, graphReceipts, draw, parts, part, question, draft, type, choose,
    post: () => requests.filter(request => request.method === 'POST'), frame: next => api.taskGraphFrame(next) };
}

function taskAnswerRevealHarness({ height = 220, scale = 1, spanTop = 100, spanHeight = 170, top = 0, layout = null } = {}) {
  const frames = [], listeners = new Map(), writes = [];
  const draft = { key: 'original-draft', phase: 'editing', error: null, current: true, value: 'PRIVATE_ANSWER' };
  const doc = { activeElement: { id: 'unchanged-focus' }, defaultView: { innerHeight: 1000 },
    addEventListener(name, fn) { listeners.set(name, fn); },
    removeEventListener(name, fn) { if (listeners.get(name) === fn) listeners.delete(name); } };
  const body = { ownerDocument: doc, list: null,
    querySelector: () => body.list,
    contains: node => node?._body === body,
    addEventListener(name, fn) { listeners.set(name, fn); },
    removeEventListener(name, fn) { if (listeners.get(name) === fn) listeners.delete(name); },
    getBoundingClientRect: () => ({ top: 0, bottom: 1000, height: 1000 }),
  };
  if (layout) {
    Object.assign(body, { clientHeight: 387, clientWidth: 420,
      getBoundingClientRect: () => ({ top: 108.77, bottom: 481.70, height: 372.93 }) });
    doc.defaultView.innerHeight = 600; doc.defaultView.innerWidth = layout.width;
    doc.defaultView.getComputedStyle = node => ({ lineHeight: '18.85px', fontSize: '13px',
      paddingTop: node.padding || '0px', paddingBottom: node.padding || '0px', borderTopWidth: '0px', borderBottomWidth: '0px' });
  }
  const makeList = ({ threadId = 'room-a', error = draft.error, current = () => draft.current } = {}) => {
    let position = layout ? body.list?.scrollTop || top : top, listHeight = height;
    const border = layout ? 1 : 0;
    const listTop = () => layout ? 367.98333740234375 - (listHeight + border) * scale : 100;
    const input = { _body: body, isConnected: true, dataset: { focusKey: draft.key }, value: draft.value, selectionStart: 2, selectionEnd: 6, selectionDirection: 'backward', scrollTop: 19, scrollLeft: 3,
      closest: selector => selector.includes('chat-task-condition') ? row : selector.includes('chat-composer') && selector.includes('chat-task-answer-text') ? input : null,
      setSelectionRange(start, end, direction) { Object.assign(this, { selectionStart: start, selectionEnd: end, selectionDirection: direction }); this.scrollTop = 0; } };
    const errorTitle = { dataset: { focusKey: `${draft.key}:error-question` }, scrollTop: 0, scrollLeft: 0 };
    const list = { dataset: { threadId }, isConnected: true, clientTop: border, scrollHeight: 800, scrollLeft: 0,
      get clientHeight() { return listHeight; }, get offsetHeight() { return listHeight + border; },
      get scrollTop() { return position; }, set scrollTop(value) { position = Math.max(0, Math.min(800 - listHeight, value)); writes.push(position); },
      getBoundingClientRect: () => ({ top: listTop(), bottom: listTop() + (listHeight + border) * scale, height: (listHeight + border) * scale }),
      querySelectorAll: selector => selector.includes('chat-task-answer-text') ? [input]
        : selector.includes('chat-task-error-question') ? [errorTitle] : [row],
      contains: node => node === row,
      closest: () => body,
    };
    let log, board, pane, composer, footer;
    if (layout) {
      const properties = {};
      log = { padding: '12px', scrollTop: body.list?._log?.scrollTop ?? 247, scrollLeft: 3, scrollHeight: 1400,
        content: ['old reply', 'completed task', 'current conversation'],
        get clientHeight() { return layout.logHeight + (pane?.dataset.taskAnswerCompact ? layout.compactGain || 0 : 0) - (listHeight - height); },
        getBoundingClientRect: () => ({ top: 156, bottom: 156 + log.clientHeight * scale, height: log.clientHeight * scale }),
        querySelectorAll: () => [anchor] };
      const anchor = { getBoundingClientRect: () => ({ top: 156 + (parseFloat(log.padding) + 260 - log.scrollTop) * scale,
        bottom: 156 + (parseFloat(log.padding) + 284 - log.scrollTop) * scale }) };
      board = { dataset: {}, get offsetHeight() { return listHeight + 35; },
        style: { setProperty(name, value) { properties[name] = value; listHeight = parseFloat(value) - border; },
          removeProperty(name) { delete properties[name]; listHeight = height; } } };
      composer = { _body: body, isConnected: true, value: layout.composerDraft || '', selectionStart: 0, selectionEnd: 0,
        selectionDirection: 'none', scrollTop: 2, scrollLeft: 3,
        closest: selector => selector.includes('chat-composer') && selector.includes('chat-task-answer-text') ? composer : null,
        setSelectionRange(start, end, direction) { Object.assign(this, { selectionStart: start, selectionEnd: end, selectionDirection: direction }); } };
      const inputRow = { clientWidth: layout.composerWidth ?? 380, querySelector(selector) {
        if (selector.includes('chat-composer')) return composer;
        if (selector.includes('chat-project-target')) return {};
        if (selector.includes('chat-attachment') || selector.includes('chat-briefing-input')) return layout.attached ? {} : null;
        return null;
      } };
      footer = { querySelector: () => inputRow, getBoundingClientRect: () => ({
        height: 100 - (pane?.dataset.taskAnswerCompact ? layout.compactGain || 0 : 0) }) };
      const main = { dataset: { compactComposer: 'true' }, querySelector: () => layout.compactGain ? footer : null };
      pane = { dataset: {}, parentElement: main, style: { setProperty(name, value) { properties[name] = value; log.padding = '0px'; },
        removeProperty(name) { delete properties[name]; log.padding = '12px'; } },
        querySelector: () => log, getBoundingClientRect: () => ({ top: 108.77, bottom: 374.73, height: 265.96 }) };
      list.closest = selector => selector === '.egd-task-board' ? board : selector === '.egd-codex-conversation-pane' ? pane : null;
      list._log = log;
    }
    const part = (start, end) => ({ isConnected: true, getBoundingClientRect: () => ({ top: listTop() + (border + start - position) * scale,
      bottom: listTop() + (border + end - position) * scale, height: (end - start) * scale, width: 340 * scale }) });
    const fieldsHeight = layout?.fieldHeight || 90;
    const parts = { '.egd-task-answer-fields': part(spanTop, spanTop + fieldsHeight),
      '[data-testid="chat-task-error-summary"]': part(spanTop + (layout ? fieldsHeight + 6 : 96), spanTop + spanHeight - (layout ? 36 : 38)),
      '.egd-task-answer-actions': part(spanTop + spanHeight - 32, spanTop + spanHeight) };
    const row = { dataset: {}, isConnected: true, _taskAnswerReveal: { key: draft.key, current, phase: () => draft.phase, error: () => draft.error },
      querySelector: selector => parts[selector] };
    return { list, row, input, errorTitle, parts, error, log, board, pane, composer, footer };
  };
  const factory = compileFunction(`${declaration('createChatTaskAnswerReveal')}\nreturn createChatTaskAnswerReveal;`, [])();
  const api = factory(body, { schedule: fn => frames.push(fn) });
  let shown = makeList(); body.list = shown.list; api.afterRender();
  const render = options => {
    const focusedInput = doc.activeElement === shown.input;
    const focusedComposer = shown.composer && doc.activeElement === shown.composer;
    const composerView = focusedComposer ? { start: shown.composer.selectionStart, end: shown.composer.selectionEnd,
      direction: shown.composer.selectionDirection, top: shown.composer.scrollTop, left: shown.composer.scrollLeft } : null;
    api.beforeRender(); shown.list.isConnected = false; shown.row.isConnected = false;
    shown = makeList(options); body.list = shown.list;
    api.restoreLayout();
    // The real Chat renderer restores focus before afterRender; that is not a user gesture.
    if (focusedInput) doc.activeElement = shown.input;
    if (focusedComposer) {
      doc.activeElement = shown.composer;
      shown.composer.setSelectionRange(composerView.start, composerView.end, composerView.direction);
      shown.composer.scrollTop = composerView.top; shown.composer.scrollLeft = composerView.left;
    }
    listeners.get('focusin')?.({ type: 'focusin', target: doc.activeElement }); api.afterRender(); return shown;
  };
  const sending = ({ explicit = true } = {}) => {
    const control = { closest: selector => selector.includes('chat-task-condition') ? shown.row : control };
    if (explicit) listeners.get('click')?.({ type: 'click', target: control });
    draft.phase = 'sending'; draft.error = null; render();
  };
  const failed = () => { draft.phase = 'error'; draft.error = '전체 오류 이유와 해결 방법'; return render(); };
  return { api, body, doc, draft, frames, writes, listeners, render, sending, failed, shown: () => shown,
    interact: (type, target = { outsideChat: true }, extra = {}) => listeners.get(type)?.({ type, target, ...extra }),
    flush: () => { while (frames.length) frames.shift()(); } };
}

test('Task new-error reveal: moves the full input/error/actions union by the minimum inner scroll without focus/caret/textarea changes', () => {
  for (const scale of [1, 0.96, 1.5]) {
    const h = taskAnswerRevealHarness({ scale }), focus = h.doc.activeElement;
    h.sending(); const rendered = h.failed(); h.flush();
    assert.ok(Math.abs(rendered.list.scrollTop - 54) < 1e-10, 'only floating-point transform precision differs');
    assert.deepEqual(h.writes, [rendered.list.scrollTop]);
    const rects = Object.values(rendered.parts).map(part => part.getBoundingClientRect());
    assert.ok(Math.min(...rects.map(rect => rect.top)) >= 100 + 4 * scale - 1e-10);
    assert.ok(Math.max(...rects.map(rect => rect.bottom)) <= 100 + 216 * scale + 1e-10);
    assert.equal(h.doc.activeElement, focus); assert.equal(rendered.input.value, 'PRIVATE_ANSWER');
    assert.deepEqual([rendered.input.selectionStart, rendered.input.selectionEnd, rendered.input.selectionDirection,
      rendered.input.scrollTop, rendered.input.scrollLeft], [2, 6, 'backward', 19, 3]);
  }
});

test('Task new-error reveal: same-error SSE retains one pending reveal, then never repeats; already-visible and oversized forms do not move', () => {
  const h = taskAnswerRevealHarness(); h.sending(); h.failed(); h.render(); h.flush();
  assert.equal(h.writes.length, 1, 'only the newest attached render moves');
  h.render(); h.flush(); assert.equal(h.writes.length, 1, 'an unchanged error is not a new reveal');
  for (const options of [{ spanTop: 20 }, { spanHeight: 260 }]) {
    const fixed = taskAnswerRevealHarness(options); fixed.sending(); fixed.failed(); fixed.flush();
    assert.equal(fixed.writes.length, 0, 'never reveal only the error/buttons when the complete form cannot fit');
  }
  const otherView = taskAnswerRevealHarness(); otherView.sending({ explicit: false }); otherView.failed(); otherView.flush();
  assert.equal(otherView.writes.length, 0, 'a failure submitted in another view never moves this view');
});

test('Task new-error reveal: user interaction during the request or deferred frame cancels movement', () => {
  for (const event of ['pointerdown', 'wheel', 'keydown', 'input', 'compositionstart', 'focusin']) for (const timing of ['request', 'frame']) {
    const h = taskAnswerRevealHarness(); h.sending();
    if (timing === 'request') h.interact(event);
    h.failed(); if (timing === 'frame') h.interact(event);
    h.flush(); assert.equal(h.writes.length, 0, `${event}/${timing}`);
    h.render(); h.flush(); assert.equal(h.writes.length, 0, 'SSE does not revive a cancelled reveal');
  }
});

test('Task new-error reveal: room/draft/currentness changes, detached views and disposal reject deferred work', () => {
  for (const change of [h => h.render({ threadId: 'other-room' }), h => { h.draft.key = 'replacement'; h.render(); },
    h => { h.draft.current = false; }, h => { h.draft.phase = 'editing'; h.draft.error = null; },
    h => { h.body.list = null; h.api.afterRender(); }, h => { h.shown().list.isConnected = false; }, h => h.api.dispose()]) {
    const h = taskAnswerRevealHarness(); h.sending(); h.failed(); change(h); h.flush(); assert.equal(h.writes.length, 0);
  }
  const h = taskAnswerRevealHarness(); h.api.dispose(); assert.equal(h.listeners.size, 0);
});

test('Task measured 600/800 layout: short answer/error/actions fit by borrowing only the needed transcript height', () => {
  const inputCss = cssDeclarationsFor(surfaceCss, '.egd-task-answer-text');
  const questionCss = cssDeclarationsFor(surfaceCss, '.egd-task-question');
  const fieldHeight = parseFloat(inputCss['min-height']), gap = parseFloat(questionCss.gap);
  // Runtime: list clientHeight 123, offsetHeight 124, scale .9620968; the
  // transcript has 28 CSS px. Model real Task/header/footer space, not an
  // absent Task board. Browser painting remains Main's serial QA.
  const spanHeight = fieldHeight + gap * 2 + 2 + 34.5 + 32;
  for (const width of [600, 800]) {
    const h = taskAnswerRevealHarness({ height: 123, scale: 0.9620967988044985, spanHeight,
      layout: { width, logHeight: 28, fieldHeight } });
    const focus = h.doc.activeElement;
    h.sending(); const rendered = h.failed();
    const anchorBefore = rendered.log.querySelectorAll()[0].getBoundingClientRect().top;
    h.flush();
    assert.equal(rendered.row.dataset.answerReveal, 'full', `${width}: complete form, not only the buttons`);
    assert.equal(rendered.list.clientHeight, Math.ceil(spanHeight + 8), 'borrow only the missing six CSS pixels');
    assert.ok(rendered.log.clientHeight >= 20, 'transcript remains a native scroller with one visible line');
    assert.deepEqual(rendered.log.content, ['old reply', 'completed task', 'current conversation']);
    assert.ok(Math.abs(rendered.log.querySelectorAll()[0].getBoundingClientRect().top - anchorBefore) < 1e-9);
    assert.equal(h.doc.activeElement, focus); assert.equal(rendered.input.value, 'PRIVATE_ANSWER');
    const listRect = rendered.list.getBoundingClientRect(), scale = listRect.height / rendered.list.offsetHeight;
    for (const part of Object.values(rendered.parts)) {
      const rect = part.getBoundingClientRect();
      assert.ok(rect.top >= listRect.top + (rendered.list.clientTop + 4) * scale - .01);
      assert.ok(rect.bottom <= listRect.top + (rendered.list.clientTop + rendered.list.clientHeight - 4) * scale + .01);
    }
    const moved = h.writes.length, top = rendered.list.scrollTop;
    h.render(); h.flush();
    assert.equal(h.writes.length, moved, 'unchanged SSE restores layout but requests no new scroll');
    assert.equal(h.shown().list.scrollTop, top);
    assert.equal(h.shown().list.clientHeight, rendered.list.clientHeight);
    h.render({ threadId: 'other-room' }); h.flush();
    assert.equal(h.shown().board.dataset.answerSpace, undefined, 'space does not leak to another room');
  }
});

test('Task measured layout: cancelled reveal does not allocate; impossible full forms expose complete error/actions with input still scrollable', () => {
  for (const event of ['pointerdown', 'wheel', 'keydown', 'input', 'compositionstart', 'focusin']) {
    const h = taskAnswerRevealHarness({ height: 123, scale: .9620968, spanHeight: 120.5,
      layout: { width: 600, logHeight: 28, fieldHeight: 44 } });
    h.sending(); h.failed(); h.interact(event); h.flush();
    assert.equal(h.shown().board.dataset.answerSpace, undefined);
    assert.equal(h.writes.length, 0);
    h.body.clientWidth += 1; h.render(); h.flush();
    assert.equal(h.shown().board.dataset.answerSpace, undefined, 'resize must not revive a user-cancelled reveal');
    assert.equal(h.writes.length, 0);
  }
  const h = taskAnswerRevealHarness({ height: 123, scale: .9620968, spanHeight: 256.5,
    layout: { width: 600, logHeight: 28, fieldHeight: 180 } });
  h.sending(); const rendered = h.failed(); h.flush();
  assert.equal(rendered.row.dataset.answerReveal, 'actions', 'not reported as full-form visibility');
  assert.ok(rendered.list.scrollHeight > rendered.list.clientHeight);
  assert.equal(rendered.input.value, 'PRIVATE_ANSWER');
  const rect = rendered.list.getBoundingClientRect();
  for (const part of Object.values(rendered.parts).slice(1)) {
    const shown = part.getBoundingClientRect();
    assert.ok(shown.top >= rect.top); assert.ok(shown.bottom <= rect.bottom);
  }
});

test('Task measured 600/800 layout: a taller question/error summary remains with the actions when the full form cannot fit', () => {
  for (const width of [600, 800]) {
    const h = taskAnswerRevealHarness({ height: 123, scale: .9620968, spanHeight: 150.5,
      layout: { width, logHeight: 28, fieldHeight: 44 } });
    const focus = h.doc.activeElement;
    h.sending(); const rendered = h.failed(); h.flush();
    assert.equal(rendered.row.dataset.answerReveal, 'actions', 'the title and error stay together, not a false full-form claim');
    const rect = rendered.list.getBoundingClientRect(), scale = rect.height / rendered.list.offsetHeight;
    for (const selector of ['[data-testid="chat-task-error-summary"]', '.egd-task-answer-actions']) {
      const shown = rendered.parts[selector].getBoundingClientRect();
      assert.ok(shown.top >= rect.top + (rendered.list.clientTop + 4) * scale - .01, width);
      assert.ok(shown.bottom <= rect.top + (rendered.list.clientTop + rendered.list.clientHeight - 4) * scale + .01, width);
    }
    assert.equal(h.doc.activeElement, focus); assert.equal(rendered.input.value, 'PRIVATE_ANSWER');
    assert.deepEqual([rendered.input.selectionStart, rendered.input.selectionEnd, rendered.input.selectionDirection,
      rendered.input.scrollTop, rendered.input.scrollLeft], [2, 6, 'backward', 19, 3]);
  }
});

test('Task measured 600/800 long-title first error: borrow the actually released empty-composer row for the whole form', () => {
  // R6 receipt: 124px list, 44px answer, roughly 153px answer/title/error/actions
  // union; compacting the existing two composer rows frees about 40 CSS px.
  for (const width of [600, 800]) {
    const h = taskAnswerRevealHarness({ height: 124, scale: .9621334, spanHeight: 152.5,
      layout: { width, logHeight: 24, fieldHeight: 44, compactGain: 40 } });
    const focus = h.doc.activeElement;
    h.sending(); const rendered = h.failed(); h.flush();
    assert.equal(rendered.pane.dataset.taskAnswerCompact, 'true');
    assert.equal(rendered.row.dataset.answerReveal, 'full');
    assert.ok(rendered.list.clientHeight >= 161);
    const box = rendered.list.getBoundingClientRect(), scale = box.height / rendered.list.offsetHeight;
    for (const [name, part] of Object.entries(rendered.parts)) {
      const shown = part.getBoundingClientRect();
      assert.ok(shown.top >= box.top + (rendered.list.clientTop + 4) * scale - .01, `${width}: ${name} top`);
      assert.ok(shown.bottom <= box.top + (rendered.list.clientTop + rendered.list.clientHeight - 4) * scale + .01, `${width}: ${name} bottom`);
    }
    assert.equal(rendered.input.value, 'PRIVATE_ANSWER');
    assert.equal(h.doc.activeElement, focus);
    assert.ok(rendered.log.clientHeight >= 20);
    const scroll = rendered.list.scrollTop, writes = h.writes.length;
    h.render(); h.flush();
    assert.equal(h.shown().pane.dataset.taskAnswerCompact, 'true');
    assert.equal(h.shown().list.scrollTop, scroll);
    assert.equal(h.writes.length, writes, 'same failure redraw cannot re-reveal');
  }
});

